}
// The index of a native's result named `name`, matched as natives are: an
// exact name first, else the one name that matches loosely; -1 for none and
// -2 when several match.
FindResult :: (ports: ResolvedPort[], native: ResolvedNative, name: string) -> int {
    found: int = -1;
    index: int = 0;
    while (index < native.results) {
        result := ports[native.first + native.parameters + index].name;
        if (result == name) {
            return index;
        }
        if (NameMatches(result, name)) {
            if (found >= 0) {
                found = -2;
            } else if (found == -1) {
                found = index;
            }
        }
        index += 1;
    }
    return found;
}
// The port of a native's argument `index`; a variadic native's last
// parameter takes every argument from it on.
NativePort :: (native: ResolvedNative, index: int) -> int {
    if (index >= native.parameters && native.variadic && native.parameters > 0) {
        return native.first + native.parameters - 1;
    }
    return native.first + index;
}
ArrayUpdate :: union {
    NotApplicable | InPlace(mode: int, array: int, item: int, native: int)
}
// How `xs = name(xs, value)` updates the local array names[found] in place:
// mode 0 pushes and mode 1 extends. The actual native and bound parameters
// identify a candidate; preparation proves whether its item may write.
InPlaceUpdate :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], natives: ResolvedNative[],
                  ports: ResolvedPort[], identities: u64[], names: Name[], package: int, found: int, destination: int,
                  value: int) -> ArrayUpdate {
    updated := names[found];
    if (updated.place != CellPlace || updated.container != ArrayContainer || !updated.writable ||
        !Is(forest, value, "call_expression")) {
        return ArrayUpdate.NotApplicable;
    }
    callee := Field(forest, value, "function");
    method := Is(forest, callee, "member_expression");
    native: int = -1;
    if (method) {
        native = ArrayMethod(natives, ports, Text(forest, text, Field(forest, callee, "member")));
    } else if (Is(forest, callee, "identifier") &&
               SourceCallable(callables, natives, names, package, Text(forest, text, callee)) == -1) {
        native = FindNative(natives, Text(forest, text, callee));
    }
    if (native < 0 || !natives[native].direct || natives[native].intrinsic != 0 ||
        natives[native].variadic || natives[native].parameters != 2) {
        return ArrayUpdate.NotApplicable;
    }
    capability := identities[2 * native];
    mode: int = -1;
    if (capability == binding.ID("capability", "Append")) {
        mode = 0;
    } else if (capability == binding.ID("capability", "Extend")) {
        mode = 1;
    }
    if (mode < 0) {
        return ArrayUpdate.NotApplicable;
    }
    switch BindNative(forest, text, value, NativeSources(forest, value, method), natives[native], ports) {
        case .Failed(problem, message):
            return ArrayUpdate.NotApplicable;
        case .Bound(arguments, total):
            if (total != 2 || length(arguments) != 2) {
                return ArrayUpdate.NotApplicable;
            }
            array: int = -1;
            item: int = -1;
            for (argument in arguments) {
                if (argument.parameter == 0) {
                    array = argument.node;
                } else if (argument.parameter == 1) {
                    item = argument.node;
                }
            }
            if (array < 0 || item < 0 || !Is(forest, array, "identifier") ||
                Text(forest, text, array) != Text(forest, text, destination)) {
                return ArrayUpdate.NotApplicable;
            }
            // The copying form reads the array before the item, so an item
            // that changes the array keeps it.
            if (Holds(MutatedNames(forest, text, item, []), Text(forest, text, destination))) {
                return ArrayUpdate.NotApplicable;
            }
            return ArrayUpdate.InPlace(mode, array, item, native);
    }
}

// The array function a method call on an array runs, with the array first.
// -1 for none.
ArrayMethod :: (natives: ResolvedNative[], ports: ResolvedPort[], name: string) -> int {
    index: int = 0;
    for (native in natives) {
        if (!native.source && native.kind == NativeFunctionKind && native.parameters > 0 &&
            ports[native.first].container == ArrayContainer && NameMatches(native.name, name)) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// Whether an array function returns its array changed, so its method changes
// the array in place, as `append` does and `slice` does not.
ArrayChanger :: (natives: ResolvedNative[], native: int) -> bool {
    changers: string[] = ["append", "add_unique", "extend", "set_array_elem", "insert", "remove_index", "remove_item",
                          "clear", "reverse", "swap", "resize"];
    for (changer in changers) {
        if (NameMatches(natives[native].name, changer)) {
            return true;
        }
    }
    return false;
}
// The array an expression statement's method call changes, as `xs.append(x)`
// changes xs: the receiver, a name of an array, or -1.
ChangedArray :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], natives: ResolvedNative[], ports: ResolvedPort[],
                 statement: int) -> int {
    call := FirstMember(forest, statement);
    function := Field(forest, call, "function");
    if (!Is(forest, statement, "expression_statement") || !Is(forest, call, "call_expression") ||
        !Is(forest, function, "member_expression") || !Is(forest, Field(forest, function, "object"), "identifier")) {
        return -1;
    }
    object := Field(forest, function, "object");
    found := Lookup(names, Text(forest, text, object));
    if (found < 0 || names[found].container != ArrayContainer) {
        return -1;
    }
    method := ArrayMethod(natives, ports, Text(forest, text, Field(forest, function, "member")));
    if (method < 0 || !ArrayChanger(natives, method)) {
        return -1;
    }
    return object;
}
// An assignment's target and value, or the array a method statement changes
// and its call.
StatementTarget :: (forest: snapshot.SnapshotNode[], statement: int) -> int {
    if (Is(forest, statement, "expression_statement")) {
        return Field(forest, Field(forest, FirstMember(forest, statement), "function"), "object");
    }
    return Field(forest, statement, "target");
}
StatementValue :: (forest: snapshot.SnapshotNode[], statement: int) -> int {
    if (Is(forest, statement, "expression_statement")) {
        return FirstMember(forest, statement);
    }
    return Field(forest, statement, "value");
}
// The tables a body starts from: its parameters, its record or array result's
// symbol, its point and its named results, which are locals from `named` on.
Start :: union {
    Begun(work: Work[], names: Name[], slots: Slot[], locals: Slot[], cells: Cell[], hosts: Host[], code: Code[],
          points: SourcePoint[], named: int)
}
Prologue :: (forest: snapshot.SnapshotNode[], text: string, params: Param[], callable: Callable, aliases: Name[],
             key: string, solid: int[], meaning: u64, referenced: string[], mutated: string[], addressed: string[],
             ops: Ops, target: Target, evaluating: bool) -> Start {
    declaration := forest[callable.node];
    // Import aliases are the outermost names; every local may hide one.
    names := aliases;
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    code: Code[] = [];
    // Scalar and string parameters move to locals, so assigning one needs no
    // other form. Calls lend their arguments, so written pointer parameters
    // get local copies before the body runs.
    work: Work[] = [Visit(Field(forest, callable.node, "body"))];
    if (evaluating) {
        work = [Visit(callable.node)];
    }
    index: int = 0;
    while (index < callable.count) {
        param := params[callable.first + index];
        if (param.reference) {
            name: Name = {owned: false, name: param.name, place: ReferencePlace, index: index, storage: param.storage,
                          container: param.container, record: param.record, writable: true, node: param.node};
            names.append(name);
        } else if (Holds(addressed, param.name)) {
            work.append(Resume(callable.node, PointerParameterPhase, index, 0));
        } else if (Holds(referenced, param.name) && !Pointer(param.storage, param.container)) {
            work.append(Resume(callable.node, 0, index, 1));
        } else if (Pointer(param.storage, param.container) && Holds(mutated, param.name)) {
            work.append(Resume(callable.node, 0, index, 0));
        } else if (Pointer(param.storage, param.container)) {
            name: Name = {owned: false, name: param.name, place: ParameterPlace, index: index, storage: param.storage,
                          container: param.container, record: param.record, writable: true, node: param.node};
            names.append(name);
        } else {
            slot: Slot = {storage: param.storage, kind: ValueKind};
            slots.append(slot);
            read := Instruction(ops.argument, param.storage, length(slots) - 1, index, 0, 0, declaration);
            read.value_storage = param.storage;
            code.append(read);
            locals.append(ValueLocal(param.storage));
            code.append(Instruction(ops.save, param.storage, 0, length(slots) - 1, 0,
                                    length(locals) - 1, declaration));
            name: Name = {owned: false, name: param.name, place: LocalPlace, index: length(locals) - 1,
                          storage: param.storage, container: 0, record: param.record, writable: true,
                          node: param.node};
            names.append(name);
        }
        index += 1;
    }
    // A record or array result is a symbol the function stores before it
    // starts.
    if (callable.results == 0 && (callable.result == StructStorage || callable.result_container != 0)) {
        code.append(SymbolCode(ops, -1, declaration));
    }
    // Named results reserve consecutive locals. A record local holds its
    // stable cell's header address, while its name reads the cell's payload.
    // A query evaluator returns its row instead.
    named := length(locals);
    index = 0;
    while (!evaluating && index < callable.results) {
        result := params[callable.first + callable.count + index];
        place := LocalPlace;
        location := length(locals);
        if (result.storage == StructStorage) {
            // Normalize the typed zero buffer through the constructor, so
            // native record ranges receive the same defaults as stage zero.
            cell: Cell = {storage: result.storage, container: result.container, record: result.record,
                          constant: 0, variant: -1, kind: ValueKind};
            cells.extend([cell, cell]);
            host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: ConstructIntrinsic, linked: -1, first: length(cells) - 2,
                          result_first: length(cells) - 1, result_count: 1, written: false};
            hosts.append(host);
            code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, length(hosts) - 1, declaration));
            slots.append(AddressSlot(target));
            code.append(Instruction(ops.host_slot, target.pointer_storage, length(slots) - 1,
                                    length(cells) - 1, 0, 0, declaration));
            locals.append(AddressSlot(target));
            code.append(Instruction(ops.save, target.pointer_storage, 0, length(slots) - 1, 0,
                                    length(locals) - 1, declaration));
            code.append(SymbolCode(ops, result.node, declaration));
            place = CellPlace;
            location = length(cells) - 1;
        } else {
            slots.append(ValueLocal(result.storage));
            code.append(ConstantCode(ops, result.storage, 0, length(slots) - 1, declaration));
            locals.append(ValueLocal(result.storage));
            code.append(Instruction(ops.save, result.storage, 0, length(slots) - 1, 0, length(locals) - 1,
                                    declaration));
        }
        bound: Name = {owned: false, name: result.name, place: place, index: location, storage: result.storage,
                       container: result.container, record: result.record, writable: true, node: result.node};
        names.append(bound);
        index += 1;
    }
    // Initial result construction precedes the function's first point.
    points: SourcePoint[] = [PointAt(key, solid, FunctionRecord, meaning, false, declaration, declaration)];
    code.append(PointCode(ops, 0, declaration));
    return Start.Begun(work, names, slots, locals, cells, hosts, code, points, named);
}

// The back edge of a counted loop, kept separate from body dispatch so the
// compiler's own dispatch stays within the runtime definition budget.
ForTail :: union {
    Finished(code: Code[], slots: Slot[], breaks: int[], continues: int[])
}
FinishFor :: (forest: snapshot.SnapshotNode[], item: Work, input_code: Code[], input_slots: Slot[], input_breaks: int[],
              input_continues: int[], loop: Loop, ops: Ops, node: snapshot.SnapshotNode) -> ForTail {
    code := input_code;
    slots := input_slots;
    breaks := input_breaks;
    continues := input_continues;
    at_continue := loop.first_continue;
    while (at_continue < length(continues)) {
        resume := code[continues[at_continue]];
        resume.target = length(code);
        code[continues[at_continue]] = resume;
        at_continue += 1;
    }
    continues = slice(continues, 0, loop.first_continue);
    slots.append(ValueLocal(IntStorage));
    current := length(slots) - 1;
    code.append(Instruction(ops.local, IntStorage, current, loop.index, 0, 0, node));
    // An inclusive or reversed range ends once the index reaches
    // its bound, so neither INT_MAX nor INT_MIN wraps.
    at_bound: int = -1;
    if (loop.counted) {
        slots.append(ValueLocal(IntStorage));
        code.append(Instruction(ops.local, IntStorage, length(slots) - 1, loop.bound, 0, 0, node));
        slots.append(ValueLocal(BoolStorage));
        code.append(Instruction(ops.eq, IntStorage, length(slots) - 1, current, length(slots) - 2,
                                -1, node));
        at_bound = length(code);
        code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, Pending, node));
    }
    slots.append(ValueLocal(IntStorage));
    code.append(ConstantCode(ops, IntStorage, 1, length(slots) - 1, node));
    step_op := ops.add;
    if (loop.reverse) {
        step_op = ops.sub;
    }
    slots.append(ValueLocal(IntStorage));
    code.append(Instruction(step_op, IntStorage, length(slots) - 1, current, length(slots) - 2,
                            -1, node));
    code.append(Instruction(ops.save, IntStorage, 0, length(slots) - 1, 0, loop.index, node));
    if (Field(forest, item.node, "bound") >= 0) {
        code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
    }
    code.append(Instruction(ops.jump, 0, 0, 0, 0, loop.head, node));
    exits_here: int[] = [loop.leave, at_bound, loop.empty];
    for (pending in exits_here) {
        if (pending >= 0) {
            done := code[pending];
            done.target = length(code);
            code[pending] = done;
        }
    }
    at_break := loop.first_break;
    while (at_break < length(breaks)) {
        escape := code[breaks[at_break]];
        escape.target = length(code);
        code[breaks[at_break]] = escape;
        at_break += 1;
    }
    breaks = slice(breaks, 0, loop.first_break);
    return ForTail.Finished(code, slots, breaks, continues);
}

RangeHead :: union {
    Failed(diagnostic: syntax.Diagnostic) | Ready(code: Code[], slots: Slot[], locals: Slot[], bound: Name, loop: Loop)
}
StartRange :: (forest: snapshot.SnapshotNode[], text: string, document: int, bounds: Value[], item: Work, ops: Ops,
               input_code: Code[], input_slots: Slot[], input_locals: Slot[], break_count: int, continue_count: int,
               name_count: int) -> RangeHead {
    code := input_code;
    slots := input_slots;
    locals := input_locals;
    node := forest[item.node];
    ends: int[] = [];
    end_index: int = 0;
    while (end_index < 2) {
        end := bounds[end_index];
        if (end.container != 0 || !Integer(end.storage) ||
            (end.storage != IntStorage && !Widens(end.storage, IntStorage))) {
            return RangeHead.Failed(Diagnose(forest, item.node, document, "range bounds need int values"));
        }
        if (end.storage != IntStorage) {
            slots.append(ValueLocal(IntStorage));
            code.append(CastCode(ops, IntStorage, length(slots) - 1, end.slot, 0, node));
            end = Typed(length(slots) - 1, IntStorage, 0, -1);
        }
        ends.append(end.slot);
        end_index += 1;
    }
    reverse := Field(forest, item.node, "reverse") >= 0;
    exclusive := Text(forest, text, Field(forest, item.node, "bound")) == "..<";
    start := ends[0];
    stop := ends[1];
    if (reverse) {
        start = ends[1];
        stop = ends[0];
    }
    empty: int = -1;
    if (reverse && exclusive) {
        slots.append(ValueLocal(BoolStorage));
        code.append(Instruction(ops.lt, IntStorage, length(slots) - 1, ends[0], ends[1], -1, node));
        code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, length(code) + 2, node));
        empty = length(code);
        code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
        slots.append(ValueLocal(IntStorage));
        code.append(ConstantCode(ops, IntStorage, 1, length(slots) - 1, node));
        slots.append(ValueLocal(IntStorage));
        code.append(Instruction(ops.sub, IntStorage, length(slots) - 1, ends[1], length(slots) - 2,
                                -1, node));
        start = length(slots) - 1;
    }
    locals.append(ValueLocal(IntStorage));
    index_local := length(locals) - 1;
    code.append(Instruction(ops.save, IntStorage, 0, start, 0, index_local, node));
    // The range's name is stored before the loop and at each step.
    code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
    locals.append(ValueLocal(IntStorage));
    bound_local := length(locals) - 1;
    code.append(Instruction(ops.save, IntStorage, 0, stop, 0, bound_local, node));
    head := length(code);
    code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
    slots.append(ValueLocal(IntStorage));
    code.append(Instruction(ops.local, IntStorage, length(slots) - 1, index_local, 0, 0, node));
    slots.append(ValueLocal(IntStorage));
    code.append(Instruction(ops.local, IntStorage, length(slots) - 1, bound_local, 0, 0, node));
    compare := ops.lt;
    if (reverse) {
        compare = ops.ge;
    } else if (!exclusive) {
        compare = ops.le;
    }
    slots.append(ValueLocal(BoolStorage));
    code.append(Instruction(compare, IntStorage, length(slots) - 1, length(slots) - 3,
                            length(slots) - 2, -1, node));
    code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, length(code) + 2, node));
    loop: Loop = {held_slot: -1, held_storage: 0, held_container: 0, held_record: -1, held_owned: false, head: head,
                  first_break: break_count, first_continue: continue_count, each: true,
                  index: index_local, mark: name_count, leave: length(code), reverse: reverse,
                  counted: !exclusive || reverse, bound: bound_local, empty: empty};
    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
    binding: Name = {owned: false, name: Text(forest, text, Field(forest, item.node, "name")), place: LocalPlace,
                     index: index_local, storage: IntStorage, container: 0, record: -1, writable: false,
                     node: Field(forest, item.node, "name")};
    return RangeHead.Ready(code, slots, locals, binding, loop);
}

QueryGuardCallPhase: int : 71;
GuardCall :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Scheduled(code: Code[], slots: Slot[], locals: Slot[], next: Work[], popped: int, produced: Value)
}
// Each argument stores the result before its early exit. Pending branches
// link through their targets until the last argument patches the whole chain.
QueryGuardCall :: (forest: snapshot.SnapshotNode[], text: string, document: int,
                   values: Value[], top: int, item: Work, ops: Ops,
                   input_code: Code[], input_slots: Slot[], input_locals: Slot[]) -> GuardCall {
    code := input_code;
    slots := input_slots;
    locals := input_locals;
    node := forest[item.node];
    function := Text(forest, text, Field(forest, item.node, "function"));
    if (function != "all" && function != "any" && function != "not") {
        return GuardCall.Failed(Diagnose(forest, item.node, document, "unknown query guard call"));
    }
    if (item.phase == 0) {
        first := FirstMember(forest, Field(forest, item.node, "arguments"));
        if (function == "not" && (first < 0 || NextMember(forest, first) >= 0)) {
            return GuardCall.Failed(Diagnose(forest, item.node, document, "not needs exactly one Boolean argument"));
        }
        argument := first;
        while (argument >= 0) {
            if (Is(forest, argument, "named_argument") || Is(forest, argument, "typed_argument") ||
                Is(forest, argument, "reference_argument")) {
                return GuardCall.Failed(Diagnose(forest, argument, document, "query guards need positional Boolean arguments"));
            }
            argument = NextMember(forest, argument);
        }
        locals.append(ValueLocal(BoolStorage));
        held := length(locals) - 1;
        if (first < 0) {
            identity: u64 = 0;
            if (function == "all") {
                identity = 1;
            }
            slots.append(ValueLocal(BoolStorage));
            output := length(slots) - 1;
            code.append(ConstantCode(ops, BoolStorage, identity, output, node));
            code.append(Instruction(ops.save, BoolStorage, 0, output, 0, held, node));
            return GuardCall.Scheduled(code, slots, locals, [], 0, Typed(output, BoolStorage, 0, -1));
        }
        resume := Resume(item.node, QueryGuardCallPhase, first, held);
        resume.c = -1;
        return GuardCall.Scheduled(code, slots, locals, [Visit(first), resume], 0, NoValue());
    }
    if (top <= 0 || values[top - 1].storage != BoolStorage || values[top - 1].container != 0) {
        return GuardCall.Failed(Diagnose(forest, item.a, document, "query guard arguments need Boolean values"));
    }
    value := values[top - 1];
    result := value.slot;
    if (function == "not") {
        slots.append(ValueLocal(BoolStorage));
        zero := length(slots) - 1;
        code.append(ConstantCode(ops, BoolStorage, 0, zero, node));
        slots.append(ValueLocal(BoolStorage));
        result = length(slots) - 1;
        code.append(Instruction(ops.eq, BoolStorage, result, value.slot, zero, -1, node));
    }
    code.append(Instruction(ops.save, BoolStorage, 0, result, 0, item.b, node));
    argument := NextMember(forest, item.a);
    if (argument >= 0) {
        condition := value.slot;
        if (function == "all") {
            slots.append(ValueLocal(BoolStorage));
            zero := length(slots) - 1;
            code.append(ConstantCode(ops, BoolStorage, 0, zero, node));
            slots.append(ValueLocal(BoolStorage));
            condition = length(slots) - 1;
            code.append(Instruction(ops.eq, BoolStorage, condition, value.slot, zero, -1, node));
        }
        jump := length(code);
        code.append(Instruction(ops.branch_if, 0, 0, condition, 0, item.c, node));
        resume := Resume(item.node, QueryGuardCallPhase, argument, item.b);
        resume.c = jump;
        return GuardCall.Scheduled(code, slots, locals, [Visit(argument), resume], 1, NoValue());
    }
    pending := item.c;
    while (pending >= 0) {
        patched := code[pending];
        prior := patched.target;
        patched.target = length(code);
        code[pending] = patched;
        pending = prior;
    }
    slots.append(ValueLocal(BoolStorage));
    output := length(slots) - 1;
    code.append(Instruction(ops.local, BoolStorage, output, item.b, 0, 0, node));
    return GuardCall.Scheduled(code, slots, locals, [], 1, Typed(output, BoolStorage, 0, -1));
}

OwnerCodes :: union {
    Failed(diagnostic: syntax.Diagnostic) | Read(code: Code[])
}
// The selected constant owner argument becomes the invocation owner, along
// with its typed output watch. Selection and validation stay unchanged.
OwnerArgumentCodes :: (forest: snapshot.SnapshotNode[], document: int, original: Code[], item: Work,
                       ops: Ops) -> OwnerCodes {
    code := original;
    producer: int = -1;
    index: int = 0;
    while (index < length(code)) {
        instruction := code[index];
        if (instruction.output == item.a && instruction.op == ops.constant &&
            instruction.type == HandleStorage && instruction.value_storage == HandleStorage &&
            instruction.value_container == 0 && instruction.payload == 0 && !instruction.has_text) {
            if (producer >= 0) {
                return OwnerCodes.Failed(Diagnose(forest, item.node, document,
                                                  "native owner argument has several constant producers"));
            }
            producer = index;
        }
        index += 1;
    }
    if (producer < 0 || item.storage != HandleStorage || item.container != 0 || item.record < 0) {
        return OwnerCodes.Failed(Diagnose(forest, item.node, document,
                                          "native owner argument has no constant handle producer"));
    }
    instruction := code[producer];
    instruction.op = ops.owner;
    instruction.value_record = item.record;
    code[producer] = instruction;
    index = 0;
    while (index < length(code)) {
        watch := code[index];
        if (watch.op == ops.source_watch && watch.output == 1 && watch.left == item.a &&
            watch.value_storage == HandleStorage && watch.value_container == 0) {
            watch.value_record = item.record;
            code[index] = watch;
        }
        index += 1;
    }
    return OwnerCodes.Read(code);
}
DebugPrefix :: union {
    Read(code: Code[], slots: Slot[], points: SourcePoint[])
}
// Debugger records before a node's step. The returned tables contain only
// this node's additions; their instructions use the caller's absolute bases.
DebugPoints :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], types: TypeDecl[],
                constants: ConstDecl[], package: int, key: string, solid: int[], document_hash: u64,
                point_base: int, slot_base: int, item: Work, negated: bool, ops: Ops) -> DebugPrefix {
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    points: SourcePoint[] = [];
    if (Statement(kind)) {
        points.append(PointAt(key, solid, StatementRecord, 0, false, node, node));
        code.append(PointCode(ops, point_base + length(points) - 1, node));
        // Stage zero assigns each returned value to a result, a statement
        // of its own.
        value := Field(forest, item.node, "value");
        returned: int[] = [];
        if (kind == "return_statement" && Is(forest, value, "argument_list")) {
            returned = Members(forest, value);
        } else if (kind == "return_statement" && value >= 0) {
            returned = [value];
        }
        for (each in returned) {
            points.append(PointAt(key, solid, StatementRecord, 0, false, forest[each], forest[each]));
            code.append(PointCode(ops, point_base + length(points) - 1, forest[each]));
        }
    }
    if (Expression(kind) && !negated && !ConstantElement(forest, item.node) &&
        !ElidedTarget(forest, text, names, item.node)) {
        points.append(PointIn(document_hash, solid, ExpressionRecord, node));
        code.append(PointCode(ops, point_base + length(points) - 1, node));
        // A name's symbol, or a package constant's, which is a symbol of
        // its own document.
        constant: int = -1;
        if (kind == "identifier") {
            found := Lookup(names, Text(forest, text, item.node));
            if (found >= 0 && !Alias(names[found].place)) {
                code.append(SymbolCode(ops, names[found].node, node));
            } else if (found < 0) {
                constant = FindConstant(constants, package, Text(forest, text, item.node));
            }
        } else if (kind == "member_expression") {
            constant = ConstantOf(forest, text, constants, names, package, item.node);
            // `self.C` reads the owner's component without visiting `self`.
            if (constant < 0 && SelfComponent(forest, text, types, names, item.node) >= 0) {
                code.extend(NamePoints(forest, text, names, ops, Field(forest, item.node, "object")));
                slots.append(ValueLocal(HandleStorage));
                code.extend(OwnerWatch(ops, slot_base + length(slots) - 1,
                                       forest[Field(forest, item.node, "object")]));
            }
        }
        if (constant >= 0) {
            code.append(OccurrenceCode(ops, SymbolRecord, constants[constant].occurrence, node));
        }
    }
    return DebugPrefix.Read(code, slots, points);
}
DebugOutput :: union {
    Read(code: Code[], slots: Slot[], roots: Root[])
}
// Output watches after a node's step, with only their added tables. Result
// cells already have absolute indices; new slots start at the caller's base.
DebugWatches :: (forest: snapshot.SnapshotNode[], item: Work, produced: Value, negated: bool,
                 callables: Callable[], params: Param[], natives: ResolvedNative[], ports: ResolvedPort[],
                 ops: Ops, target: Target, slot_base: int) -> DebugOutput {
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    roots: Root[] = [];
    // The value an expression produced is watched as its output, once:
    // the step that gives a number literal its type watches it, and a
    // copy or loan of the value for its consumer is not watched again.
    // A place a write goes through holds no value of its own.
    if (produced.storage > 0 && Expression(kind) && !negated && item.phase != CopyValuePhase &&
        !produced.place && !ConstantElement(forest, item.node) && !NumberLiteral(forest, item.node)) {
        code.append(WatchCode(ops, produced.slot, produced.storage, produced.container, produced.record,
                              0, true, node, target));
    }
    // A call's several results are each watched, numbered.
    if (kind == "call_expression" &&
        (produced.storage == FunctionResultsStorage || produced.storage == ResultsStorage)) {
        count: int = 0;
        if (produced.storage == FunctionResultsStorage) {
            count = callables[produced.record].results;
        } else {
            count = natives[produced.record].results;
        }
        at_result: int = 0;
        while (at_result < count) {
            storage: int = 0;
            container: int = 0;
            record: int = -1;
            if (produced.storage == FunctionResultsStorage) {
                called := callables[produced.record];
                result := params[called.first + called.count + at_result];
                storage = result.storage;
                container = result.container;
                record = result.record;
            } else {
                linked := natives[produced.record];
                storage = ports[linked.first + linked.parameters + at_result].storage;
                container = ports[linked.first + linked.parameters + at_result].container;
                record = ports[linked.first + linked.parameters + at_result].record;
            }
            address: Slot = {storage: target.pointer_storage, kind: AddressKind};
            loaded: Slot = {storage: SlotStorage(storage, container, target), kind: SlotKind(storage, container)};
            slots.extend([address, loaded]);
            code.extend(CellRead(loaded.storage, produced.slot + at_result, ops, target,
                                 slot_base + length(slots) - 2, node));
            if (Pointer(storage, container)) {
                root: Root = {slot: slot_base + length(slots) - 1, storage: storage,
                              container: container, record: record};
                roots.append(root);
            }
            code.append(WatchCode(ops, slot_base + length(slots) - 1, storage, container, record, at_result,
                                  true, node, target));
            at_result += 1;
        }
    }
    return DebugOutput.Read(code, slots, roots);
}
EmitBody :: (forest: snapshot.SnapshotNode[], text: string, document: int,
             callables: Callable[], params: Param[], table: ^(TypeDecl[]), members: TypeMember[],
             constants: ConstDecl[], natives: ResolvedNative[], ports: ResolvedPort[], identities: u64[],
             operators: NumericOperator[], makes: NativeMake[], make_fields: int[], aliases: Name[], key: string,
             solid: int[], undeclared: u64, meaning: u64, function: int, referenced: string[],
             mutated: string[], built: int[], context: BodyContext, generic_updates: int[],
             ops: Ops, target: Target, query_specs: QuerySpec[]) -> Body {
    types := table^;
    math_enabled := false;
    for (math_type in types) {
        if (math_type.kind == MathDecl) {
            math_enabled = true;
            break;
        }
    }
    callable := callables[function];
    declaration := forest[callable.node];
    inferring := Expression(declaration.kind);
    document_hash := DocumentHash(key);
    slots: Slot[] = [];
    // Locals hold scalars and the header addresses of named record results.
    locals: Slot[] = [];
    cells: Cell[] = [];
    code: Code[] = [];
    calls: Invocation[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    names: Name[] = [];
    work: Work[] = [];
    points: SourcePoint[] = [];
    named: int = 0;
    evaluating := QueryEvaluator(query_specs, function);
    address_root := Field(forest, callable.node, "body");
    if (inferring) {
        address_root = callable.node;
    }
    if (evaluating >= 0) {
        address_root = Field(forest, callable.node, "parameters");
    }
    addressed := AddressedNames(forest, text, address_root,
                                ScopedArguments(forest, text, callables, params, natives, aliases, callable.package,
                                                address_root));
    begun := Prologue(forest, text, params, callable, aliases, key, solid, meaning, referenced, mutated, addressed, ops,
                      target, evaluating >= 0);
    switch begun {
        case .Begun(begun_work, begun_names, begun_slots, begun_locals, begun_cells, begun_hosts, begun_code,
                    begun_points, begun_named):
            work = begun_work;
            names = begun_names;
            slots = begun_slots;
            locals = begun_locals;
            cells = begun_cells;
            hosts = begun_hosts;
            code = begun_code;
            points = begun_points;
            named = begun_named;
    }
    if (inferring) {
        work = [Visit(callable.node)];
    }
    values: Value[] = [];
    native_calls: NativeCallFact[] = [];
    loops: Loop[] = [];
    breaks: int[] = [];
    continues: int[] = [];
    switches: Switch[] = [];
    exits: int[] = [];
    covered: int[] = [];
    // Where each open scope's names start: blocks, if and while statements,
    // and switch arms.
    scopes: int[] = [];
    work_top: int = 0;
    value_top: int = 0;
    watches: SourceWatch[] = [];
    semantic_effects: int = 0;
    // The arguments of overloaded natives, by node, and the jump each
    // reserves where it is written.
    reserved_nodes: int[] = [];
    reserved_jumps: int[] = [];
    // The reserved jumps a call took, retargeted once the body is done.
    retargets: int[] = [];
    retarget_starts: int[] = [];
    direct_write: int = 0;
    facts: SemanticFact[] = [];
    work_top = length(work);
    while (work_top > 0) {
        work_top -= 1;
        item := work[work_top];
        types = table^;
        if (item.phase == EffectsPhase) {
            semantic_effects = semantic_effects | item.a;
            continue;
        }
        if (item.phase == SemanticPhase || item.phase == NativeCallPhase) {
            switch DirectiveFacts(forest, context, direct_write, facts, item) {
                case .Read(summary, recorded):
                    direct_write = summary;
                    facts = recorded;
            }
            if (item.phase == SemanticPhase) {
                continue;
            }
            fact: NativeCallFact = {node: item.node, native: item.a, storage: item.storage,
                                    container: item.container, record: item.record};
            native_calls.append(fact);
            continue;
        }
        if (item.phase == OwnerArgumentPhase) {
            switch OwnerArgumentCodes(forest, document, code, item, ops) {
                case .Failed(diagnostic):
                    return Body.Failed(diagnostic);
                case .Read(rewritten):
                    code = rewritten;
            }
            continue;
        }
        node := forest[item.node];
        kind := node.kind;
        // Items this one schedules, in the order they run.
        next: Work[] = [];
        // A value this item leaves for its consumer, when `produced.storage` is set.
        produced := NoValue();
        iteration := NoValue();
        // Whether a for loop reads its record element in place, unowned.
        lent_element := false;
        // A record or array to copy into a fresh cell; the copy is produced.
        retained := NoValue();
        operator := Text(forest, text, Field(forest, item.node, "operator"));
        logic := kind == "binary_expression" &&
                 (operator == "&&" || operator == "and" || operator == "||" || operator == "or");
        // Stage zero reads `-1` as one literal.
        negated := kind == "number" && Is(forest, node.parent, "unary_expression") &&
                   Text(forest, text, Field(forest, node.parent, "operator")) == "-";
        if (ops.debug && item.phase == 0) {
            switch DebugPoints(forest, text, names, types, constants, callable.package, key, solid,
                               document_hash, length(points), length(slots), item, negated, ops) {
                case .Read(added_code, added_slots, added_points):
                    code.extend(added_code);
                    slots.extend(added_slots);
                    points.extend(added_points);
            }
        }
        if (ops.debug && kind == "call_expression" && item.phase == 1 && item.c == 4) {
            typed_at: Bases = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                               host: length(hosts), call: length(calls)};
            switch OverloadArguments(forest, text, document, constants, callables, types, names, callable.package,
                                     natives, ports, ops, item, values, value_top - item.b, reserved_nodes,
                                     reserved_jumps, typed_at, node, target) {
                case .Failed(diagnostic):
                    return Body.Failed(diagnostic);
                case .Typed(typed_code, typed_slots, typed_values, typed_jumps, typed_starts):
                    code.extend(typed_code);
                    slots.extend(typed_slots);
                    values = typed_values;
                    retargets.extend(typed_jumps);
                    retarget_starts.extend(typed_starts);
            }
        }
        // The step a node other than control flow takes.
        stepped := true;
        at: Bases = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                     host: length(hosts), call: length(calls)};
        step := Fail(forest, item.node, document, "");
        query_handled := false;
        switch QueryStep(forest, text, document, types, members, params, query_specs, evaluating, names, values,
                         value_top, item, ops, target, at) {
            case .Handled(emitted):
                step = emitted;
                query_handled = true;
            case .Ordinary:
                query_handled = false;
        }
        if (query_handled) {
        } else if (item.phase == MathCapturePhase) {
            step = MathCaptureStep(forest, document, types, members, values[value_top - 1], ops, target, at, node);
        } else if ((item.phase >= MathAssignBegin && item.phase <= MathAssignWrite) ||
                   (math_enabled && item.phase == 0 && MathAssignment(forest, text, types, members, callables, natives, ports,
                                                                      names, callable.package, item.node))) {
            step = MathAssignmentStep(forest, text, document, types, members, constants, names, callable.package,
                                      callables, natives, ports, values, value_top, item, ops, target, at);
        } else if (item.phase == CopyValuePhase) {
            step = CopyValueStep(values[value_top - 1], 1, ops, target, at, node);
        } else if (item.phase == MapDeletePlacePhase || item.phase == MapDeleteDonePhase) {
            step = MapPlaceDeleteStep(forest, document, types, values, value_top, item, ops, target, at);
        } else if ((item.phase >= PlacePhase && item.phase <= PlacePointerPhase) || item.phase == PlaceComponentPhase) {
            step = SequencePlaceStep(forest, text, document, types, members, names, values, value_top,
                                     item, ops, target, at);
        } else if (QueryGuardFunction(forest, text, item.node)) {
            stepped = false;
            switch QueryGuardCall(forest, text, document, values, value_top, item, ops, code, slots, locals) {
                case .Failed(diagnostic):
                    return Body.Failed(diagnostic);
                case .Scheduled(full_code, full_slots, full_locals, scheduled, popped, value):
                    code = full_code;
                    slots = full_slots;
                    locals = full_locals;
                    next = scheduled;
                    value_top -= popped;
                    produced = value;
            }
        } else if ((kind == "state_declaration" || kind == "function_declaration" || kind == "handler") &&
                   Is(forest, forest[item.node].parent, "system_body")) {
            // System declarations share the behavior collector; only statements execute per row.
            stepped = false;
        } else if (kind == "callable_body" || kind == "block" || kind == "system_body") {
            stepped = false;
            if (item.phase == 0) {
                child := FirstMember(forest, item.node);
                while (child >= 0) {
                    next.append(Visit(child));
                    child = NextMember(forest, child);
                }
                next.append(Resume(item.node, 1, length(names), 0));
                scopes.append(length(names));
            } else {
                stepped = true;
                step = DropNamesStep(names, item.a, natives, ports, ops, target, at, node);
                names = slice(names, 0, item.a);
                scopes = slice(scopes, 0, length(scopes) - 1);
            }
        } else if (kind == "if_statement" || kind == "while_statement") {
            stepped = false;
            // Bindings of the condition's patterns last through the consequence
            // or body; the work item keeps where they start in `c`.
            if (item.phase == 0) {
                head := length(code);
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                next.append(Visit(Field(forest, item.node, "condition")));
                resume := Resume(item.node, 1, head, 0);
                resume.c = length(names);
                next.append(resume);
                scopes.append(length(names));
            } else if (item.phase == 1) {
                value_top -= 1;
                condition := values[value_top];
                optional_condition := condition;
                if (OptionalElement(types, condition).storage != 0) {
                    condition_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                                           cell: length(cells), host: length(hosts), call: length(calls)};
                    switch OptionalPresentStep(condition, false, 0, ops, target, condition_at, node) {
                        case .Failed(diagnostic):
                            return Body.Failed(diagnostic);
                        case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                      added_calls, added_names, scheduled, popped, value, kept, marks):
                            code.extend(added_code);
                            slots.extend(added_slots);
                            condition = value;
                    }
                }
                if (!Single(condition, BoolStorage)) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.node, "condition"), document,
                                                "condition needs a bool"));
                }
                code.append(Instruction(ops.branch_if, 0, 0, condition.slot, 0, length(code) + 2, node));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                leave := length(code) - 1;
                names.extend(OptionalConditionNames(types, names, forest, text, Field(forest, item.node, "condition"),
                                                    optional_condition));
                field := "consequence";
                if (kind == "while_statement") {
                    field = "body";
                    loop: Loop = {held_slot: -1, held_storage: 0, held_container: 0, held_record: -1, held_owned: false, head: item.a, first_break: length(breaks), first_continue: length(continues),
                                  each: false, index: -1, mark: length(names), leave: leave,
                                  reverse: false, counted: false, bound: -1, empty: -1};
                    loops.append(loop);
                }
                next.append(Visit(Field(forest, item.node, field)));
                resume := Resume(item.node, 2, item.a, leave);
                resume.c = item.c;
                next.append(resume);
            } else if (item.phase == 2) {
                names = slice(names, 0, item.c);
                scopes = slice(scopes, 0, length(scopes) - 1);
                alternative := Field(forest, item.node, "alternative");
                if (kind == "while_statement") {
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, item.a, node));
                    loop := loops[length(loops) - 1];
                    loops = slice(loops, 0, length(loops) - 1);
                    at_break := loop.first_break;
                    while (at_break < length(breaks)) {
                        escape := code[breaks[at_break]];
                        escape.target = length(code);
                        code[breaks[at_break]] = escape;
                        at_break += 1;
                    }
                    breaks = slice(breaks, 0, loop.first_break);
                    skip := code[item.b];
                    skip.target = length(code);
                    code[item.b] = skip;
                } else if (alternative >= 0) {
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                    skip := code[item.b];
                    skip.target = length(code);
                    code[item.b] = skip;
                    next.append(Visit(alternative));
                    next.append(Resume(item.node, 3, 0, length(code) - 1));
                } else {
                    skip := code[item.b];
                    skip.target = length(code);
                    code[item.b] = skip;
                }
            } else {
                end := code[item.b];
                end.target = length(code);
                code[item.b] = end;
            }
        } else if (kind == "for_statement") {
            if (item.phase == 0) {
                if (Field(forest, item.node, "reference") >= 0) {
                    return Body.Failed(Diagnose(forest, item.node, document, "`for &item` loops are not supported yet"));
                }
                stepped = false;
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                if (Field(forest, item.node, "first") >= 0) {
                    // Ranges never count down, so constant bounds that descend
                    // are a mistake, as stage zero reports.
                    if (Descends(forest, text, document, constants, names, callable.package, item.node)) {
                        message := "Range bounds descend; count down with for <";
                        if (Field(forest, item.node, "reverse") >= 0) {
                            message = "Range bounds descend; for < takes the low bound first, as in for < i in 0..10";
                        }
                        return Body.Failed(Diagnose(forest, item.node, document, message));
                    }
                    next.append(Expect(Field(forest, item.node, "first"), IntStorage, 0, -1));
                    next.append(Expect(Field(forest, item.node, "last"), IntStorage, 0, -1));
                    next.append(Resume(item.node, 5, 0, 0));
                } else {
                    next.append(Visit(Field(forest, item.node, "value")));
                    next.append(Resume(item.node, 1, 0, 0));
                }
            } else if (item.phase == QueryIteratorEndPhase) {
                loop := loops[length(loops) - 1];
                switch QueryFinishLoop(code, breaks, continues, loop, ops, target, at, node) {
                    case .Finished(finished_code, finished_breaks, finished_continues, tail_step):
                        code = finished_code;
                        breaks = finished_breaks;
                        continues = finished_continues;
                        step = tail_step;
                }
                names = slice(names, 0, loop.mark);
                loops = slice(loops, 0, length(loops) - 1);
            } else if (item.phase == 5) {
                stepped = false;
                value_top -= 2;
                switch StartRange(forest, text, document, slice(values, value_top, 2), item, ops, code, slots, locals,
                                  length(breaks), length(continues), length(names)) {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Ready(range_code, range_slots, range_locals, range_name, range_loop):
                        code = range_code;
                        slots = range_slots;
                        locals = range_locals;
                        names.append(range_name);
                        loops.append(range_loop);
                }
                next.append(Visit(Field(forest, item.node, "body")));
                next.append(Resume(item.node, 4, 0, 0));
            } else if (item.phase == 1) {
                // The loop walks its own copy, whatever the body changes, or
                // the array itself when nothing can change it.
                stepped = false;
                value_top -= 1;
                array := values[value_top];
                iterable := Unparenthesized(forest, Field(forest, item.node, "value"));
                if (array.storage == QueryStorage && array.container == 0) {
                    stepped = true;
                    step = QueryIteratorStep(forest, text, document, types, array, item, ops, target, at);
                } else if (array.container != ArrayContainer && array.container != ViewContainer && !IsMap(array)) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.node, "value"), document, "for needs an array"));
                } else if (array.container == ArrayContainer && FixedArray(forest, text, names, referenced, mutated, addressed,
                                                                           iterable)) {
                    // A local or parameter nothing changes stays as it is
                    // while the loop walks it, so the loop walks it itself.
                    cells.append(MovedCell(array));
                    slots.append(AddressSlot(target));
                    code.extend(MoveCode(array, ops, target, length(slots) - 1, length(cells) - 1, node));
                    produced = array;
                    produced.cell = length(cells) - 1;
                } else if (IsMap(array) || array.container == ArrayContainer) {
                    retained = array;
                } else {
                    // Ordinary iteration observes an outer snapshot. Aliases
                    // can resize the original while the body runs.
                    stepped = true;
                    step = SequenceCallStep([array], SequenceCloneIntrinsic,
                                            Typed(-1, array.storage, ArrayContainer, array.record),
                                            u64(0), false, 0, ops, target, at, node);
                }
                if (array.storage != QueryStorage) {
                    next.append(Resume(item.node, 2, 0, 0));
                }
            } else if (item.phase == 2) {
                // The array or its copy is in the last cell; the step loads each element.
                value_top -= 1;
                if (Text(forest, text, ItemField(forest, item.node)) == "") {
                    return Body.Failed(Diagnose(forest, ItemField(forest, item.node), document,
                                                "Invalid string or embedded NUL"));
                }
                array := values[value_top];
                iteration = array;
                if (IsMap(array)) {
                    step = MapForStep(forest, text, document, types, array, item, ops, target, at);
                } else {
                    // A record element nothing changes or keeps is read in
                    // place from the loop's array, which the loop alone holds.
                    name := ItemField(forest, item.node);
                    lent_element = Fixed(referenced, mutated, addressed, Text(forest, text, name)) &&
                                   !built.contains(name) &&
                                   ReadsInPlace(array, SequenceElement(types, {storage: array.storage,
                                                                               container: array.container,
                                                                               record: array.record}), true);
                    step = ForStep(types, array, Packable(array.storage, array.record, types, members),
                                   Field(forest, item.node, "reverse") >= 0, lent_element, ops, target, at, node);
                }
            } else if (item.phase == 3) {
                // A record element was copied, or read in place, into the
                // last cell; one read in place from the array (item.a) is
                // not the binding's to drop.
                stepped = false;
                value_top -= 1;
                kept := values[value_top];
                binding: Name = {owned: item.a == 0, name: Text(forest, text, ItemField(forest, item.node)), place: CellPlace,
                                 index: kept.cell, storage: kept.storage, container: kept.container, record: kept.record,
                                 writable: false, node: ItemField(forest, item.node)};
                names.append(binding);
                code.append(SymbolCode(ops, binding.node, node));
                next.append(Visit(Field(forest, item.node, "body")));
                next.append(Resume(item.node, 4, 0, 0));
            } else {
                stepped = false;
                loop := loops[length(loops) - 1];
                loops = slice(loops, 0, length(loops) - 1);
                drop_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                                  cell: length(cells), host: length(hosts), call: length(calls)};
                switch DropNamesStep(names, loop.mark, natives, ports, ops, target, drop_at, node) {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(drop_code, drop_slots, drop_locals, drop_cells, drop_hosts, drop_roots,
                                  drop_calls, drop_bound, drop_next, drop_popped, drop_value, drop_retained, drop_marks):
                        code.extend(drop_code);
                        slots.extend(drop_slots);
                        locals.extend(drop_locals);
                        cells.extend(drop_cells);
                        hosts.extend(drop_hosts);
                        roots.extend(drop_roots);
                        calls.extend(drop_calls);
                }
                switch FinishFor(forest, item, code, slots, breaks, continues, loop, ops, node) {
                    case .Finished(done_code, done_slots, done_breaks, done_continues):
                        code = done_code;
                        slots = done_slots;
                        breaks = done_breaks;
                        continues = done_continues;
                }
                owner_drop_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                                        cell: length(cells), host: length(hosts), call: length(calls)};
                held := Typed(loop.held_slot, loop.held_storage, loop.held_container, loop.held_record);
                held.owned = loop.held_owned;
                switch DropSequenceValues([held], ops, target, owner_drop_at, node) {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(drop_code, drop_slots, drop_locals, drop_cells, drop_hosts, drop_roots,
                                  drop_calls, drop_bound, drop_next, drop_popped, drop_value, drop_retained, drop_marks):
                        code.extend(drop_code);
                        slots.extend(drop_slots);
                        locals.extend(drop_locals);
                        cells.extend(drop_cells);
                        hosts.extend(drop_hosts);
                        roots.extend(drop_roots);
                        calls.extend(drop_calls);
                }
                names = slice(names, 0, loop.mark);
            }
        } else if (kind == "switch_statement") {
            if (item.phase == 0) {
                stepped = false;
                code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
                next.append(Visit(Field(forest, item.node, "value")));
                next.append(Resume(item.node, 1, 0, 0));
            } else if (item.phase == 1) {
                // The union waits in a local while each arm tests it in turn.
                stepped = false;
                value_top -= 1;
                subject := values[value_top];
                value_switch := subject.container == 0 && Integer(subject.storage);
                if (!Single(subject, UnionStorage) && !value_switch) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.node, "value"), document,
                                                "switch needs a union or integer value"));
                }
                locals.append(ValueLocal(subject.storage));
                code.append(Instruction(ops.save, subject.storage, 0, subject.slot, 0, length(locals) - 1, node));
                current: Switch = {subject: length(locals) - 1, held: subject.record, first_exit: length(exits),
                                   first_cover: length(covered), defaulted: false, skip: -1, mark: length(names),
                                   value: value_switch, storage: subject.storage, fallback: -1};
                switches.append(current);
                next.append(Resume(item.node, 2, NextArm(forest, Field(forest, item.node, "value")), 0));
            } else if (item.phase == 2 && item.a < 0 && switches[length(switches) - 1].fallback >= 0) {
                // Every value arm missed: the default arm runs last.
                stepped = false;
                current := switches[length(switches) - 1];
                arm := current.fallback;
                current.fallback = -2;
                current.mark = length(names);
                switches[length(switches) - 1] = current;
                scopes.append(length(names));
                next.append(Visit(Field(forest, arm, "body")));
                next.append(Resume(item.node, 3, arm, 1));
            } else if (item.phase == 2 && item.a < 0) {
                stepped = false;
                current := switches[length(switches) - 1];
                if (!current.value && !current.defaulted &&
                    length(covered) - current.first_cover < types[current.held].count) {
                    return Body.Failed(Diagnose(forest, item.node, document,
                                                "Non-exhaustive switch: a union alternative is missing"));
                }
                switches = slice(switches, 0, length(switches) - 1);
                covered = slice(covered, 0, current.first_cover);
                at_exit := current.first_exit;
                while (at_exit < length(exits)) {
                    exit_jump := code[exits[at_exit]];
                    exit_jump.target = length(code);
                    code[exits[at_exit]] = exit_jump;
                    at_exit += 1;
                }
                exits = slice(exits, 0, current.first_exit);
            } else if (item.phase == 2 && switches[length(switches) - 1].value) {
                stepped = false;
                current := switches[length(switches) - 1];
                pattern := Field(forest, item.a, "value");
                if (pattern < 0) {
                    if (current.fallback != -1) {
                        return Body.Failed(Diagnose(forest, item.a, document, "Duplicate default arm"));
                    }
                    current.fallback = item.a;
                    switches[length(switches) - 1] = current;
                    next.append(Resume(item.node, 2, NextArm(forest, item.a), 0));
                } else if (Is(forest, pattern, "variant_pattern")) {
                    return Body.Failed(Diagnose(forest, pattern, document, "an integer switch's arms need values"));
                } else {
                    next.append(Expect(pattern, current.storage, 0, -1));
                    next.append(Resume(item.node, 4, item.a, 0));
                }
            } else if (item.phase == 4) {
                // An integer arm's test: past the arm unless the value equals it.
                stepped = false;
                value_top -= 1;
                candidate := values[value_top];
                current := switches[length(switches) - 1];
                if (candidate.container == 0 && Integer(candidate.storage) && candidate.storage != current.storage &&
                    Widens(candidate.storage, current.storage)) {
                    slots.append(ValueLocal(current.storage));
                    code.append(CastCode(ops, current.storage, length(slots) - 1, candidate.slot, 0, node));
                    candidate = Typed(length(slots) - 1, current.storage, 0, -1);
                }
                if (!Single(candidate, current.storage)) {
                    return Body.Failed(Diagnose(forest, Field(forest, item.a, "value"), document,
                                                "case value differs from the switch value"));
                }
                slots.append(ValueLocal(current.storage));
                code.append(Instruction(ops.local, current.storage, length(slots) - 1, current.subject, 0, 0,
                                        node));
                slots.append(ValueLocal(BoolStorage));
                code.append(Instruction(ops.eq, current.storage, length(slots) - 1, length(slots) - 2,
                                        candidate.slot, -1, node));
                code.append(Instruction(ops.branch_if, 0, 0, length(slots) - 1, 0, length(code) + 2, node));
                current.skip = length(code);
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                current.mark = length(names);
                switches[length(switches) - 1] = current;
                scopes.append(length(names));
                next.append(Visit(Field(forest, item.a, "body")));
                next.append(Resume(item.node, 3, item.a, 0));
            } else if (item.phase == 2) {
                current := switches[length(switches) - 1];
                current.mark = length(names);
                switches[length(switches) - 1] = current;
                scopes.append(length(names));
                pattern := Field(forest, item.a, "value");
                if (pattern < 0) {
                    if (current.defaulted) {
                        return Body.Failed(Diagnose(forest, item.a, document, "Duplicate default arm"));
                    }
                    current.defaulted = true;
                    switches[length(switches) - 1] = current;
                    stepped = false;
                } else {
                    if (!Is(forest, pattern, "variant_pattern")) {
                        return Body.Failed(Diagnose(forest, pattern, document, "switch arms need a variant pattern"));
                    }
                    member := Text(forest, text, Field(forest, pattern, "name"));
                    variant := FindVariant(types, current.held, member);
                    if (variant < 0) {
                        return Body.Failed(Diagnose(forest, pattern, document, format_text("Unknown variant '{}'", member)));
                    }
                    if (current.defaulted || Covers(covered, current.first_cover, variant)) {
                        return Body.Failed(Diagnose(forest, pattern, document, "Unreachable duplicate union pattern"));
                    }
                    covered.append(variant);
                    code.append(ExpressionCode(ops, forest[pattern]));
                    at.pc = length(code);
                    bindings := Field(forest, pattern, "bindings");
                    count: int = 0;
                    binding := FirstMember(forest, bindings);
                    while (binding >= 0) {
                        count += 1;
                        binding = NextMember(forest, binding);
                    }
                    if (count != 0 && count != types[variant].count) {
                        return Body.Failed(Diagnose(forest, pattern, document, "A union payload pattern must bind every field"));
                    }
                    step = MatchStep(forest, text, document, types, members, names, scopes[length(scopes) - 1],
                                     current.subject, -1, variant, bindings, true, false,
                                     Field(forest, item.node, "value"), pattern, ops, target, at, node);
                }
                next.append(Visit(Field(forest, item.a, "body")));
                next.append(Resume(item.node, 3, item.a, 0));
            } else {
                // The arm is done: leave the switch, and send a failed test here.
                stepped = false;
                exits.append(length(code));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                current := switches[length(switches) - 1];
                if (current.skip >= 0) {
                    skip := code[current.skip];
                    skip.target = length(code);
                    code[current.skip] = skip;
                }
                current.skip = -1;
                switches[length(switches) - 1] = current;
                names = slice(names, 0, current.mark);
                scopes = slice(scopes, 0, length(scopes) - 1);
                if (item.b == 1) {
                    // The default arm of an integer switch was the last.
                    next.append(Resume(item.node, 2, -1, 0));
                } else {
                    next.append(Resume(item.node, 2, NextArm(forest, item.a), 0));
                }
            }
        } else if (kind == "break_statement" || kind == "continue_statement") {
            stepped = false;
            if (length(loops) == 0) {
                return Body.Failed(Diagnose(forest, item.node, document, "break or continue outside a loop"));
            }
            loop := loops[length(loops) - 1];
            drop_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                              cell: length(cells), host: length(hosts), call: length(calls)};
            switch DropNamesStep(names, loop.mark, natives, ports, ops, target, drop_at, node) {
                case .Failed(diagnostic):
                    return Body.Failed(diagnostic);
                case .Emitted(drop_code, drop_slots, drop_locals, drop_cells, drop_hosts, drop_roots,
                              drop_calls, drop_bound, drop_next, drop_popped, drop_value, drop_retained, drop_marks):
                    code.extend(drop_code);
                    slots.extend(drop_slots);
                    locals.extend(drop_locals);
                    cells.extend(drop_cells);
                    hosts.extend(drop_hosts);
                    roots.extend(drop_roots);
                    calls.extend(drop_calls);
            }
            code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
            if (kind == "break_statement") {
                breaks.append(length(code));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
            } else if (loop.each) {
                continues.append(length(code));
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
            } else {
                code.append(Instruction(ops.jump, 0, 0, 0, 0, loop.head, node));
            }
        } else if (kind == "binary_expression" && operator == "??") {
            stepped = false;
            if (item.phase == 0) {
                next.append(Visit(Field(forest, item.node, "left")));
                next.append(Resume(item.node, 1, 0, 0));
            } else if (item.phase == 1) {
                value_top -= 1;
                optional := values[value_top];
                element := OptionalElement(types, optional);
                if (element.storage == 0) {
                    return Body.Failed(Diagnose(forest, item.node, document, "left operand of ?? must be optional"));
                }
                cells.append(MovedCell(Typed(-1, element.storage, element.container, element.record)));
                answer := length(cells) - 1;
                present := NoValue();
                probe: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                                cell: length(cells), host: length(hosts), call: length(calls)};
                switch OptionalPresentStep(optional, false, 0, ops, target, probe, node) {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                  added_calls, added_names, scheduled, popped, value, kept, marks):
                        code.extend(added_code);
                        slots.extend(added_slots);
                        present = value;
                }
                code.append(Instruction(ops.branch_if, 0, 0, present.slot, 0, length(code) + 2, node));
                fallback := length(code);
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                unwrapped := NoValue();
                unwrap_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                                    cell: length(cells), host: length(hosts), call: length(calls)};
                switch OptionalUnwrapStep(types, optional, 0, ops, target, unwrap_at, node) {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                  added_calls, added_names, scheduled, popped, value, kept, marks):
                        code.extend(added_code);
                        slots.extend(added_slots);
                        cells.extend(added_cells);
                        hosts.extend(added_hosts);
                        roots.extend(added_roots);
                        unwrapped = value;
                }
                slots.append(AddressSlot(target));
                code.extend(CellWrite(SlotStorage(element.storage, element.container, target), unwrapped.slot,
                                      answer, ops, target, length(slots) - 1, node));
                skip := length(code);
                code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                absent := code[fallback];
                absent.target = length(code);
                code[fallback] = absent;
                next.append(Expect(Field(forest, item.node, "right"), element.storage, element.container, element.record));
                finish := Expect(item.node, element.storage, element.container, element.record);
                finish.phase = 2;
                finish.a = answer;
                finish.b = skip;
                next.append(finish);
            } else {
                value_top -= 1;
                fallback := values[value_top];
                if (!Accepts(types, item.storage, item.container, item.record, fallback)) {
                    return Body.Failed(Diagnose(forest, item.node, document, "fallback differs from optional payload type"));
                }
                slots.append(AddressSlot(target));
                code.extend(CellWrite(SlotStorage(item.storage, item.container, target), fallback.slot, item.a,
                                      ops, target, length(slots) - 1, node));
                done := code[item.b];
                done.target = length(code);
                code[item.b] = done;
                first := length(slots);
                slots.extend([AddressSlot(target), {storage: SlotStorage(item.storage, item.container, target),
                                                    kind: SlotKind(item.storage, item.container)}]);
                code.extend(CellRead(SlotStorage(item.storage, item.container, target), item.a, ops, target, first, node));
                produced = Typed(first + 1, item.storage, item.container, item.record);
                if (Pointer(item.storage, item.container)) {
                    roots.append({slot: produced.slot, storage: item.storage, container: item.container, record: item.record});
                }
            }
        } else if (logic) {
            // The temporary local holds the answer whichever side decides it.
            stepped = false;
            if (item.phase == 0) {
                next.append(Visit(Field(forest, item.node, "left")));
                next.append(Resume(item.node, 1, 0, 0));
            } else if (item.phase == 1) {
                value_top -= 1;
                left := values[value_top];
                if (!Single(left, BoolStorage)) {
                    return Body.Failed(Diagnose(forest, item.node, document, "logic needs bool operands"));
                }
                locals.append(ValueLocal(BoolStorage));
                answer := length(locals) - 1;
                code.append(Instruction(ops.save, BoolStorage, 0, left.slot, 0, answer, node));
                escape := length(code);
                if (operator == "&&" || operator == "and") {
                    code.append(Instruction(ops.branch_if, 0, 0, left.slot, 0, length(code) + 2, node));
                    escape = length(code);
                    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));
                } else {
                    code.append(Instruction(ops.branch_if, 0, 0, left.slot, 0, Pending, node));
                }
                next.append(Visit(Field(forest, item.node, "right")));
                next.append(Resume(item.node, 2, answer, escape));
            } else {
                value_top -= 1;
                right := values[value_top];
                if (!Single(right, BoolStorage)) {
                    return Body.Failed(Diagnose(forest, item.node, document, "logic needs bool operands"));
                }
                code.append(Instruction(ops.save, BoolStorage, 0, right.slot, 0, item.a, node));
                escape := code[item.b];
                escape.target = length(code);
                code[item.b] = escape;
                slot: Slot = {storage: BoolStorage, kind: ValueKind};
                slots.append(slot);
                code.append(Instruction(ops.local, BoolStorage, length(slots) - 1, item.a, 0, 0, node));
                produced = Typed(length(slots) - 1, BoolStorage, 0, -1);
            }
        } else if (kind == "yield_statement" || kind == "cancel_statement" || kind == "await_expression") {
            step = TaskStep(forest, text, document, callables, natives, params, types, names, callable.package,
                            values, value_top, item, ops, target, at);
        } else if (item.phase == CombinePhase) {
            if (MathAggregate(types, values[value_top - 2]) || MathAggregate(types, values[value_top - 1])) {
                step = MathBinaryStep(forest, text, document, types, members, constants, names, callable.package,
                                      values[value_top - 2], values[value_top - 1], CompoundOperator(operator), 2,
                                      ops, target, at, node);
            } else {
                step = OperatorStep(forest, text, document, types, constants, names, callable.package, values, value_top, item, ops, at);
            }
        } else if (item.phase == PointerNilPhase && OptionalElement(types, values[value_top - 1]).storage != 0) {
            step = OptionalPresentStep(values[value_top - 1], item.c == 0, 1, ops, target, at, node);
        } else if (PointerWork(item, kind)) {
            step = PointerStep(forest, text, document, types, members, names, params, callable.first,
                               values, value_top, item, ops, target, at);
        } else if (item.phase == ReferencePhase || item.phase == ScopedPhase) {
            step = ReferenceArgumentStep(forest, text, document, types, members, names, item, ops, target, at);
        } else if (item.phase == AggregatePhase) {
            step = AggregateStep(forest, text, document, types, members, operators, natives, values, value_top, item, ops,
                                 target, at);
        } else if (ArrayElementAssignment(forest, text, names, item.node)) {
            step = ElementAssignStep(forest, text, document, types, values, value_top, item, ops, target, at);
        } else if (kind == "local_declaration" || kind == "assignment" || kind == "expression_statement" ||
                   kind == "return_statement" || kind == "delete_statement") {
            step = StatementStep(forest, text, document, callables, params, table, members, natives, ports, identities, names,
                                 scopes[length(scopes) - 1], callable.package, values, value_top, function, named,
                                 referenced, mutated, built, addressed, generic_updates, item, ops, target, at);
        } else if (SequenceOperation(forest, text, names, callable.package, item.node) >= 0) {
            step = SequenceStep(forest, text, document, table, values, value_top, item, ops, target, at);
        } else if (kind == "call_expression" &&
                   ArrayMutation(forest, text, names, natives, ports, callable.package, item.node) > 0) {
            step = MutationStep(forest, text, document, types, members, natives, ports, names, values, value_top, item,
                                ArrayMutation(forest, text, names, natives, ports, callable.package, item.node),
                                ops, target, at);
        } else if (item.phase == 0 && Integer(item.storage) &&
                   ZeroCompoundDivisor(forest, text, document, constants, names, callable.package, item.node)) {
            return Body.Failed(Diagnose(forest, forest[item.node].parent, document, "Constant division by zero"));
        } else if (item.phase == 0 && kind != "parenthesized_expression" &&
                   Folds(forest, text, constants, names, callable.package, item.node, item.storage) &&
                   !ShadowedConversion(forest, text, callables, callable.package, item.node)) {
            // A parenthesized fold folds inside its parentheses, where its
            // point and watch are.
            step = FoldStep(forest, text, document, constants, names, callable.package, item, ops, at);
        } else if (kind == "number" || kind == "boolean" || kind == "string" || kind == "nil" || kind == "identifier" ||
                   kind == "parenthesized_expression" || kind == "member_expression" || kind == "index_expression") {
            step = ValueStep(forest, text, document, callables, params, types, members, constants, natives, ports,
                             native_calls, names, callable.package, referenced, mutated, built, addressed, values,
                             value_top, item, ops, target, at);
        } else if (kind == "struct_expression" || kind == "array_expression") {
            step = LiteralStep(forest, text, document, table, members, values, value_top, built, item, ops, target, at);
        } else if (kind == "map_expression") {
            step = MapLiteralStep(forest, document, types, values, value_top, item, ops, target, at);
        } else if ((kind == "binary_expression" && (operator == "in" || NotIn(forest, item.node, operator))) ||
                   (kind == "call_expression" &&
                    (item.c == MapHasMark || (item.phase == 0 && MapMethod(forest, text, names, item.node, "has"))))) {
            step = MapHasStep(forest, text, document, types, values, value_top, item, ops, target, at);
        } else if (kind == "call_expression") {
            step = CallStep(forest, text, document, callables, params, table, members, constants, natives, ports, makes,
                            make_fields, names, callable.package, values, value_top, built, item, ops, target, at);
        } else if (kind == "unary_expression" && item.phase == 1 && operator == "!" &&
                   OptionalElement(types, values[value_top - 1]).storage != 0) {
            step = OptionalPresentStep(values[value_top - 1], true, 1, ops, target, at, node);
        } else if (kind == "binary_expression" && item.phase == 1 && (operator == "==" || operator == "!=") &&
                   ((OptionalElement(types, values[value_top - 2]).storage != 0 &&
                     Is(forest, Unparenthesized(forest, Field(forest, item.node, "right")), "nil")) ||
                    (OptionalElement(types, values[value_top - 1]).storage != 0 &&
                     Is(forest, Unparenthesized(forest, Field(forest, item.node, "left")), "nil")))) {
            optional := values[value_top - 2];
            if (OptionalElement(types, optional).storage == 0) {
                optional = values[value_top - 1];
            }
            step = OptionalPresentStep(optional, operator == "==", 2, ops, target, at, node);
        } else if (kind == "unary_expression" || kind == "binary_expression") {
            if (math_enabled && item.phase == 0 && kind == "binary_expression" &&
                MathBinaryCapture(forest, text, types, members, callables, natives, ports, names, callable.package, item.node)) {
                step = MathBinaryStart(forest, item);
            } else if (item.phase != 0 && kind == "unary_expression" && MathAggregate(types, values[value_top - 1])) {
                step = MathNegateStep(document, types, members, values[value_top - 1], operator, ops, target, at, node);
            } else if (item.phase != 0 && kind == "binary_expression" &&
                       (MathAggregate(types, values[value_top - 2]) || MathAggregate(types, values[value_top - 1]))) {
                step = MathBinaryStep(forest, text, document, types, members, constants, names, callable.package,
                                      values[value_top - 2], values[value_top - 1], operator, 2, ops, target, at, node);
            } else {
                step = OperatorStep(forest, text, document, types, constants, names, callable.package, values, value_top, item, ops, at);
            }
        } else if (kind == "function_declaration") {
            step = ParameterStep(params, callable, item, ops, target, at, node);
        } else if (kind == "is_expression" && item.phase == 0) {
            stepped = false;
            next.append(Visit(Field(forest, item.node, "value")));
            next.append(Resume(item.node, 1, 0, 0));
        } else if (kind == "is_expression") {
            held := values[value_top - 1];
            if (held.storage == UnionStorage && held.record >= 0 && types[held.record].kind == TaskResultDecl) {
                step = TaskResultIsStep(forest, text, document, types, members, names, scopes[length(scopes) - 1],
                                        values, value_top, item, ops, target, at);
            } else {
                step = IsStep(forest, text, document, types, members, names, scopes[length(scopes) - 1], values, value_top,
                              item, ops, target, at);
            }
        } else {
            return Body.Failed(Diagnose(forest, item.node, document, format_text("unsupported syntax '{}'", kind)));
        }
        // Apply the step, then the copy it or the control flow asks for.
        pass: int = 0;
        while (pass < 2) {
            if (pass == 1) {
                stepped = retained.storage != 0;
                if (stepped) {
                    at = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                          host: length(hosts), call: length(calls)};
                    step = RetainStep(retained, ops, target, at, node);
                }
            }
            if (stepped) {
                if (pass == 0 && kind == "return_statement") {
                    step = DropBeforeFinish(step, names, natives, ports, ops, target, at, node);
                }
                if (kind == "return_statement") {
                    step = QueryCleanReturn(step, loops, ops, target, at, node);
                }
                if (pass == 0 && !item.capture && QueryBooleanPosition(forest, text, item.node)) {
                    step = QueryBooleanStep(types, step, ops, target, at, node);
                }
                switch step {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                  added_calls, added_names, scheduled, popped, value, kept, marks):
                        if (pass == 0) {
                            switch StepFacts(forest, context, direct_write, facts, item.node, added_hosts, added_calls) {
                                case .Read(summary, recorded):
                                    direct_write = summary;
                                    facts = recorded;
                            }
                        }
                        code.extend(added_code);
                        slots.extend(added_slots);
                        locals.extend(added_locals);
                        cells.extend(added_cells);
                        hosts.extend(added_hosts);
                        roots.extend(added_roots);
                        calls.extend(added_calls);
                        names.extend(added_names);
                        next.extend(scheduled);
                        value_top -= popped;
                        if (value.storage != 0) {
                            produced = value;
                        }
                        if (pass == 0) {
                            retained = kept;
                        }
                        if (length(marks) == 1) {
                            // A switch arm's test: the jump past the arm.
                            current := switches[length(switches) - 1];
                            current.skip = marks[0];
                            switches[length(switches) - 1] = current;
                        }
                        if (length(marks) == 2) {
                            // A map loop's head, whose step binds its names; leaving
                            // the loop drops them.
                            loop: Loop = {held_slot: iteration.slot, held_storage: iteration.storage,
                                          held_container: iteration.container, held_record: iteration.record,
                                          held_owned: iteration.owned, head: marks[0], first_break: length(breaks), first_continue: length(continues),
                                          each: true, index: at.local, mark: length(names) - length(added_names),
                                          leave: marks[1],
                                          reverse: false, counted: false, bound: -1, empty: -1};
                            loops.append(loop);
                        }
                        if (length(marks) == 3) {
                            // A for head: its loop, then its element's binding.
                            reverse := Field(forest, item.node, "reverse") >= 0;
                            loop: Loop = {held_slot: iteration.slot, held_storage: iteration.storage,
                                          held_container: iteration.container, held_record: iteration.record,
                                          held_owned: iteration.owned, head: marks[0], first_break: length(breaks), first_continue: length(continues),
                                          each: true, index: marks[2], mark: length(names), leave: marks[1],
                                          reverse: reverse, counted: false, bound: -1, empty: -1};
                            loops.append(loop);
                            // `for x, i in xs` names the item, then the index the loop owns.
                            if (Field(forest, item.node, "key") >= 0 &&
                                Text(forest, text, Field(forest, item.node, "key")) ==
                                Text(forest, text, Field(forest, item.node, "name"))) {
                                return Body.Failed(Diagnose(forest, Field(forest, item.node, "name"), document,
                                                            format_text("Duplicate declaration '{}'",
                                                                        Text(forest, text, Field(forest, item.node, "name")))));
                            }
                            if (Field(forest, item.node, "key") >= 0) {
                                key: Name = {owned: false, name: Text(forest, text, Field(forest, item.node, "name")), place: LocalPlace,
                                             index: marks[2], storage: IntStorage, container: 0, record: -1,
                                             writable: false, node: Field(forest, item.node, "name")};
                                names.append(key);
                                code.append(SymbolCode(ops, key.node, node));
                            }
                            element := produced;
                            produced = NoValue();
                            if (Pointer(element.storage, element.container) &&
                                (lent_element ||
                                 Unchanging(forest, text, callables, natives, types, names, callable.package, mutated,
                                            Field(forest, item.node, "value")))) {
                                // The array cannot change, so the element is read in place.
                                cells.append(MovedCell(element));
                                slots.append(AddressSlot(target));
                                code.extend(MoveCode(element, ops, target, length(slots) - 1,
                                                     length(cells) - 1, node));
                                produced = element;
                                lent: int = 0;
                                if (lent_element) {
                                    produced.cell = length(cells) - 1;
                                    lent = 1;
                                }
                                next.append(Resume(item.node, 3, lent, 0));
                            } else if (Pointer(element.storage, element.container)) {
                                retained = element;
                                next.append(Resume(item.node, 3, 0, 0));
                            } else {
                                locals.append(ValueLocal(element.storage));
                                code.append(Instruction(ops.save, element.storage, 0, element.slot, 0,
                                                        length(locals) - 1, node));
                                binding: Name = {owned: false, name: Text(forest, text, ItemField(forest, item.node)),
                                                 place: LocalPlace, index: length(locals) - 1, storage: element.storage,
                                                 container: 0, record: element.record, writable: false,
                                                 node: ItemField(forest, item.node)};
                                names.append(binding);
                                code.append(SymbolCode(ops, binding.node, node));
                                next.append(Visit(Field(forest, item.node, "body")));
                                next.append(Resume(item.node, 4, 0, 0));
                            }
                        }
                        if (length(marks) == 4) {
                            loop: Loop = {held_slot: -1, held_storage: 0, held_container: 0, held_record: -1,
                                          held_owned: false, head: marks[0], first_break: length(breaks),
                                          first_continue: length(continues), each: true, index: -1, mark: length(names) - length(added_names), leave: marks[1],
                                          reverse: false, counted: false, bound: marks[2], empty: -1};
                            loops.append(loop);
                        }
                }
            }
            pass += 1;
        }
        types = table^;
        if (ops.debug && item.phase != MathCapturePhase) {
            // A pointer whose member is read next is watched by that read.
            transient := length(next) > 0 && next[length(next) - 1].phase == PointerMemberReadPhase;
            switch DebugWatches(forest, item, produced, negated || transient, callables, params, natives, ports,
                                ops, target, length(slots)) {
                case .Read(added_code, added_slots, added_roots):
                    code.extend(added_code);
                    slots.extend(added_slots);
                    roots.extend(added_roots);
            }
        }
        // An argument of an overloaded native, on its last visit, reserves a
        // jump, a no-op until the call chooses its overload.
        if (ops.debug && item.phase != MathCapturePhase && !Resumed(next, item.node) && OverloadArgument(forest, work, work_top, item.node)) {
            reserved_nodes.append(item.node);
            reserved_jumps.append(length(code));
            code.append(Instruction(ops.jump, 0, 0, 0, 0, length(code) + 1, node));
        }
        // A compound assignment watches the value it stores at its target.
        if (item.phase == CombinePhase && kind == "assignment" && produced.storage > 0) {
            code.append(WatchCode(ops, produced.slot, produced.storage, produced.container, produced.record,
                                  0, true, forest[Field(forest, item.node, "target")], target));
        }
        if (produced.storage != 0) {
            if (value_top < length(values)) {
                values[value_top] = produced;
            } else {
                values.append(produced);
            }
            value_top += 1;
        }
        // Run scheduled items in order: the last pushed runs first.
        at_next := length(next) - 1;
        while (at_next >= 0) {
            scheduled := next[at_next];
            scheduled.capture = scheduled.capture || item.capture;
            if (work_top < length(work)) {
                work[work_top] = scheduled;
            } else {
                work.append(scheduled);
            }
            work_top += 1;
            at_next -= 1;
        }
    }
    cleanup_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                         cell: length(cells), host: length(hosts), call: length(calls)};
    switch DropNamesStep(names, 0, natives, ports, ops, target, cleanup_at, declaration) {
        case .Failed(diagnostic):
            return Body.Failed(diagnostic);
        case .Emitted(drop_code, drop_slots, drop_locals, drop_cells, drop_hosts, drop_roots,
                      drop_calls, drop_bound, drop_next, drop_popped, drop_value, drop_retained, drop_marks):
            code.extend(drop_code);
            slots.extend(drop_slots);
            locals.extend(drop_locals);
            cells.extend(drop_cells);
            hosts.extend(drop_hosts);
            roots.extend(drop_roots);
            calls.extend(drop_calls);
    }
    // A function completes at its end, and one with named results returns
    // them.
    if (inferring && value_top > 0) {
        value := values[value_top - 1];
        return Body.Inferred({storage: value.storage, container: value.container, record: value.record});
    }
    points.append(PointAt(key, solid, FunctionRecord, meaning, true, declaration, declaration));
    code.append(PointCode(ops, length(points) - 1, declaration));
    if (callable.results > 0 && evaluating < 0) {
        at: Bases = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                     host: length(hosts), call: length(calls)};
        switch NamedResultsStep([], ops, target, params, callable, named, at, declaration) {
            case .Failed(diagnostic):
                return Body.Failed(diagnostic);
            case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                          added_calls, added_names, scheduled, popped, value, kept, marks):
                code.extend(added_code);
                slots.extend(added_slots);
                cells.extend(added_cells);
                hosts.extend(added_hosts);
        }
    }
    code.append(Instruction(ops.end, 0, 0, 0, 0, 0, declaration));
    code = Retargeted(code, retargets, retarget_starts);
    if (callable.result_container == ViewContainer && ReachesBodyEnd(code, ops)) {
        return Body.Failed(Diagnose(forest, callable.node, document,
                                    "view result requires an initialized value on every return path"));
    }
    if (!ops.debug) {
        code = WithoutDebug(ops, code);
        points = [];
    }
    return NumberPoints(forest, solid, undeclared, meaning, document_hash, declaration, ops, slots, locals, cells,
                        code, calls, hosts, roots, points, watches, semantic_effects, direct_write, facts);
}

// Follow both sides of each branch. A metadata-only view result header is
// never a live value, so a successful return must publish a value before END.
ReachesBodyEnd :: (code: Code[], ops: Ops) -> bool {
    visited := resize([false], length(code));
    pending: int[] = [int(0)];
    top: int = 1;
    while (top > 0) {
        top -= 1;
        at := pending[top];
        if (at >= 0 && at < length(code) && !visited[at]) {
            visited[at] = true;
            instruction := code[at];
            if (instruction.op == ops.end) {
                return true;
            }
            successors: int[] = [];
            if (instruction.op == ops.jump) {
                successors = [instruction.target];
            } else if (instruction.op == ops.branch_if) {
                successors = [instruction.target, at + 1];
            } else if (instruction.op != ops.finish) {
                successors = [at + 1];
            }
            for (successor in successors) {
                if (top < length(pending)) {
                    pending[top] = successor;
                } else {
                    pending.append(successor);
                }
                top += 1;
            }
        }
    }
    return false;
}

// A body's tables, with the points and watches the steps placed, each at its
// instruction's position. The runtime numbers each instruction that suspends,
// an invocation or a point, by its order, and a prepared module's bytes hold
// that number.
NumberPoints :: (forest: snapshot.SnapshotNode[], solid: int[], undeclared: u64, meaning: u64,
                 document_hash: u64, declaration: snapshot.SnapshotNode, ops: Ops, slots: Slot[], locals: Slot[],
                 cells: Cell[], code: Code[], calls: Invocation[], hosts: Host[], roots: Root[],
                 points: SourcePoint[], watches: SourceWatch[], effects: int, direct_write: int,
                 facts: SemanticFact[]) -> Body {
    numbered_code := code;
    numbered_points := points;
    numbered_watches := watches;
    suspension: int = 0;
    at_point: int = 0;
    while (at_point < length(numbered_code)) {
        op := numbered_code[at_point].op;
        if (op == ops.source_point && numbered_code[at_point].left < 0) {
            placed := numbered_code[at_point];
            occurrence := OccurrenceIn(document_hash, ExpressionRecord, solid[placed.start], solid[placed.end]);
            point_meaning: u64 = 0;
            point_kind := ExpressionRecord;
            if (placed.left == CompletionPoint) {
                occurrence = OccurrenceIn(document_hash, FunctionRecord, solid[declaration.start],
                                          solid[declaration.end]);
                point_meaning = meaning;
                point_kind = FunctionRecord;
            } else if (placed.left == SymbolPoint) {
                occurrence = SymbolOccurrence(forest, document_hash, solid, undeclared, placed.right);
                point_kind = SymbolRecord;
            } else if (placed.left == OccurrencePoint) {
                occurrence = placed.payload;
                point_kind = placed.right;
            }
            point: SourcePoint = {occurrence: occurrence, meaning: point_meaning, start: placed.start, end: placed.end,
                                  line: placed.line, column: placed.column, kind: point_kind,
                                  completion: placed.left == CompletionPoint};
            numbered_points.append(point);
            numbered_code[at_point] = {op: ops.source_point, type: 0, output: 0, left: length(numbered_points) - 1, right: 0,
                                       target: suspension, offset: 0, value_storage: 0, value_container: 0, value_record: -1,
                                       payload: 0, text: "", has_text: false, message: "", has_message: false,
                                       start: placed.start, end: placed.end, line: placed.line, column: placed.column};
            suspension += 1;
        } else if (op == ops.invoke || op == ops.source_point || op == ops.suspend) {
            numbered := numbered_code[at_point];
            numbered.target = suspension;
            numbered_code[at_point] = numbered;
            suspension += 1;
        } else if (op == ops.source_watch) {
            placed := numbered_code[at_point];
            // A default of another document carries its occurrence.
            occurrence := placed.payload;
            if (occurrence == 0) {
                occurrence = OccurrenceIn(document_hash, ExpressionRecord, solid[placed.start], solid[placed.end]);
            }
            watch: SourceWatch = {occurrence: occurrence,
                                  start: placed.start, end: placed.end, line: placed.line, column: placed.column,
                                  storage: placed.value_storage, container: placed.value_container,
                                  record: placed.value_record, ordinal: placed.right, output: placed.output == 1,
                                  reference: placed.offset == 1};
            numbered_watches.append(watch);
            numbered_code[at_point] = Instruction(ops.source_watch, placed.type, 0, placed.left, 0,
                                                  length(numbered_watches) - 1, Located(placed));
        }
        at_point += 1;
    }
    return Body.Emitted(slots, locals, cells, numbered_code, calls, hosts, roots, numbered_points, numbered_watches,
                        effects, direct_write, facts);
}
package package_compiler

import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"
import strings "core:strings"

// The steps EmitBody takes for nodes other than control flow. Each reads the
// body's tables, which calls share rather than copy, and returns only what it
// adds, numbered from the sizes in `at`.

// Whether an array of this element type may hold its elements inline, with a
// nonzero stride, as the runtime decides: scalars and records of scalars may,
// while strings, unions and records with a string field are always boxed.
Packable :: (storage: int, record: int, types: TypeDecl[], members: TypeMember[]) -> bool {
    if (storage == TextStorage || storage == UnionStorage) {
        return false;
    }
    if (storage != StructStorage) {
        return true;
    }
    at := types[record].first;
    while (at < types[record].first + types[record].count) {
        if (members[at].storage == TextStorage) {
            return false;
        }
        at += 1;
    }
    return true;
}
// The slots ElementRead numbers from its `first`: zero, the lower check, the
// count and the upper check, then the slots of ElementLoad.
ElementSlots :: (storage: int, packable: bool, target: Target) -> Slot[] {
    number: Slot = {storage: IntStorage, kind: ValueKind};
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    checks: Slot[] = [number, flag, number, flag];
    return extend(checks, LoadSlots(storage, packable, target));
}
// Reads the element of the array in slot `array` at the index in slot
// `position` into the last of ElementSlots, after checking 0 <= index < count
// as stage zero does. `pc` is where its code starts; a packable record element
// needs the local `local`.
ElementRead :: (array: int, position: int, storage: int, packable: bool, first: int, pc: int, local: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    constant := Instruction(ops.constant, IntStorage, first, 0, 0, 0, node);
    constant.value_storage = IntStorage;
    code.append(constant);
    code.append(Instruction(ops.ge, IntStorage, first + 1, position, first, -1, node));
    code.append(Instruction(ops.guard, 0, 0, first + 1, 0, target.argument_failure, node));
    code.append(Instruction(ops.guard, 0, 0, array, 0, target.argument_failure, node));
    count := Instruction(ops.load, IntStorage, first + 2, array, 0, 0, node);
    count.offset = target.count_offset;
    code.append(count);
    code.append(Instruction(ops.lt, IntStorage, first + 3, position, first + 2, -1, node));
    code.append(Instruction(ops.guard, 0, 0, first + 3, 0, target.argument_failure, node));
    return extend(code, ElementLoad(array, position, storage, packable, first + 4, pc + length(code), local, ops,
                                    target, node));
}
// The slots ElementLoad numbers from its `first`. For an element type that is
// never packed: the array's items, the item and the element. Otherwise: the
// array's items, data and stride, a zero word, whether the array is packed,
// the boxed and the actual element width, the index as a word, its byte
// offset, the base, the item, then for a record its boxed pointer and the
// element, and for any other element the payload offset, the offset to use,
// its address and the element.
LoadSlots :: (storage: int, packable: bool, target: Target) -> Slot[] {
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    word: Slot = {storage: target.pointer_storage, kind: ValueKind};
    element: Slot = {storage: SlotStorage(storage, 0, target), kind: SlotKind(storage, 0)};
    if (!packable) {
        return [address, address, element];
    }
    slots: Slot[] = [address, address, word, word, flag, word, word, word, word, address, address];
    if (storage == StructStorage) {
        return extend(slots, [address, element]);
    }
    return extend(slots, [word, word, address, element]);
}
// Loads the element at the index in slot `position`, already checked, into
// the last of LoadSlots, as stage zero does: a packed array (nonzero stride)
// holds elements inline in `data`, and any other holds value headers in
// `items`. An element type that is never packed reads `items` alone. A packed
// record is the element itself, so the boxed pointer is loaded only past a
// branch, through local `local`; `pc` is where the code starts.
ElementLoad :: (array: int, position: int, storage: int, packable: bool, first: int, pc: int, local: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    items := Instruction(ops.load, target.pointer_storage, first, array, 0, 0, node);
    items.offset = target.items_offset;
    code.append(items);
    if (!packable) {
        // The header's payload is the value, or a record's pointer.
        item := Instruction(ops.index, target.pointer_storage, first + 1, first, position, 0, node);
        item.offset = target.value_size;
        code.append(item);
        element := Instruction(ops.load, SlotStorage(storage, 0, target), first + 2, first + 1, 0, 0, node);
        element.offset = target.payload_offset;
        return append(code, element);
    }
    data := Instruction(ops.load, target.pointer_storage, first + 1, array, 0, 0, node);
    data.offset = target.data_offset;
    code.append(data);
    stride := Instruction(ops.load, target.pointer_storage, first + 2, array, 0, 0, node);
    stride.offset = target.stride_offset;
    code.append(stride);
    code.append(ConstantCode(ops, target.pointer_storage, 0, first + 3, node));
    code.append(Instruction(ops.ne, target.pointer_storage, first + 4, first + 2, first + 3, -1, node));
    code.append(ConstantCode(ops, target.pointer_storage, u64(target.value_size), first + 5, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 6, first + 4, first + 2, first + 5, node));
    code.append(CastCode(ops, target.pointer_storage, first + 7, position, 0, node));
    code.append(Instruction(ops.mul, target.pointer_storage, first + 8, first + 7, first + 6, -1, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 9, first + 4, first + 1, first, node));
    code.append(Instruction(ops.add, target.pointer_storage, first + 10, first + 9, first + 8, -1, node));
    if (storage == StructStorage) {
        code.append(Instruction(ops.save, target.pointer_storage, 0, first + 10, 0, local, node));
        code.append(Instruction(ops.branch_if, 0, 0, first + 4, 0, pc + length(code) + 3, node));
        pointer := Instruction(ops.load, target.pointer_storage, first + 11, first + 10, 0, 0, node);
        pointer.offset = target.payload_offset;
        code.append(pointer);
        code.append(Instruction(ops.save, target.pointer_storage, 0, first + 11, 0, local, node));
        return append(code, Instruction(ops.local, target.pointer_storage, first + 12, local, 0, 0, node));
    }
    code.append(ConstantCode(ops, target.pointer_storage, u64(target.payload_offset), first + 11, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 12, first + 4, first + 3, first + 11, node));
    code.append(Instruction(ops.add, target.pointer_storage, first + 13, first + 10, first + 12, -1, node));
    return append(code, Instruction(ops.load, SlotStorage(storage, 0, target), first + 14, first + 13, 0, 0, node));
}
// The locals ElementRead and ElementLoad need: one for a packable record
// element.
ElementLocals :: (storage: int, packable: bool, target: Target) -> Slot[] {
    if (storage == StructStorage && packable) {
        return [{storage: target.pointer_storage, kind: AddressKind}];
    }
    return [];
}

// An ownership boundary makes an independent value. Runtime copies retain
// immutable storage and pointer identity, and share mutable backing with CoW.
RetainStep :: (kept: Value, ops: Ops, target: Target, at: Bases, item: snapshot.SnapshotNode) -> Step {
    return CopyValueStep(kept, 0, ops, target, at, item);
}

// The cell a fresh value moves into instead of a copy, and the code that
// gives the cell's header its payload as it stands.
MovedCell :: (value: Value) -> Cell {
    return {storage: value.storage, container: value.container, record: value.record, constant: 0, variant: -1,
            kind: ValueKind};
}
AddressSlot :: (target: Target) -> Slot {
    return {storage: target.pointer_storage, kind: AddressKind};
}
MoveCode :: (value: Value, ops: Ops, target: Target, slot: int, cell: int, item: snapshot.SnapshotNode) -> Code[] {
    write := Instruction(ops.write, target.pointer_storage, 0, value.slot, slot, 0, item);
    write.offset = target.payload_offset;
    code: Code[] = [Instruction(ops.host_slot, target.pointer_storage, slot, cell, 0, 0, item), write];
    return extend(code, SchemaWriteCode(value, slot, ops, target, item));
}

// A runtime native record schema travels beside its payload pointer. These
// helpers add no cells or locals, and keep the original step's numbering.
SchemaWriteCode :: (value: Value, address: int, ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    if (value.storage != StructStorage || value.container != 0 || value.schema < 0) {
        return [];
    }
    write := Instruction(ops.write, target.pointer_storage, 0, value.schema, address, 0, node);
    write.offset = target.schema_offset;
    return [write];
}
ValueWriteCode :: (value: Value, cell: int, ops: Ops, target: Target, slot: int,
                   node: snapshot.SnapshotNode) -> Code[] {
    code := CellWrite(SlotStorage(value.storage, value.container, target), value.slot, cell, ops, target, slot, node);
    return extend(code, SchemaWriteCode(value, slot, ops, target, node));
}
CellSchemaStep :: (step: Step, cell: int, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks):
            body_code := code;
            body_slots := slots;
            value := produced;
            if (value.storage == StructStorage && value.container == 0) {
                first := at.slot + length(body_slots);
                body_code.append(Instruction(ops.host_slot, target.pointer_storage, first, cell, 0, 0, node));
                load := Instruction(ops.load, target.pointer_storage, first + 1, first, 0, 0, node);
                load.offset = target.schema_offset;
                body_code.append(load);
                body_slots.extend([AddressSlot(target), AddressSlot(target)]);
                value.schema = first + 1;
            }
            return Step.Emitted(body_code, body_slots, locals, cells, hosts, roots, calls, bound, next, popped, value, retained, marks);
    }
}
ArgumentSchemaStep :: (step: Step, argument: int, ops: Ops, target: Target, at: Bases,
                       node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks):
            body_code := code;
            body_slots := slots;
            value := produced;
            if (value.storage == StructStorage && value.container == 0) {
                first := at.slot + length(body_slots);
                bank := Instruction(ops.context, target.pointer_storage, first, 0, 0, 0, node);
                bank.offset = target.arguments_offset;
                body_code.append(bank);
                body_code.append(ConstantCode(ops, IntStorage, u64(argument), first + 1, node));
                header := Instruction(ops.index, target.pointer_storage, first + 2, first, first + 1, 0, node);
                header.offset = target.value_size;
                body_code.append(header);
                load := Instruction(ops.load, target.pointer_storage, first + 3, first + 2, 0, 0, node);
                load.offset = target.schema_offset;
                body_code.append(load);
                body_slots.extend([AddressSlot(target), ValueLocal(IntStorage), AddressSlot(target), AddressSlot(target)]);
                value.schema = first + 3;
            }
            return Step.Emitted(body_code, body_slots, locals, cells, hosts, roots, calls, bound, next, popped, value, retained, marks);
    }
}

// A literal without context takes its storage from its spelling, as stage zero
// does. Other expressions supply their own type. Hexadecimal e is a digit;
// only decimal spellings have an exponent.
InferredNumberStorage :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    literal := Unparenthesized(forest, node);
    digits := literal;
    if (Is(forest, digits, "unary_expression")) {
        digits = Field(forest, digits, "operand");
        operator := Text(forest, text, Field(forest, literal, "operator"));
        if (operator != "-" && operator != "+") {
            return 0;
        }
        if (operator == "+") {
            literal = digits;
        }
    }
    if (!Is(forest, digits, "number")) {
        return 0;
    }
    spelling := Text(forest, text, digits);
    size := strings.ByteLength(spelling);
    hexadecimal := size > 2 && strings.ByteAt(spelling, 0) == 48 &&
                   (strings.ByteAt(spelling, 1) == 120 || strings.ByteAt(spelling, 1) == 88);
    if (!hexadecimal) {
        index: int = 0;
        while (index < size) {
            character := strings.ByteAt(spelling, index);
            if (character == 46 || character == 101 || character == 69) {
                return FloatStorage;
            }
            index += 1;
        }
    }
    switch ParseNumber(forest, text, literal) {
        case .Number(negative, magnitude):
            if (Fits(negative, magnitude, IntStorage)) {
                return IntStorage;
            }
            if (Fits(negative, magnitude, Int64Storage)) {
                return Int64Storage;
            }
        case .Invalid:
            return WordStorage;
    }
    // The constant emitter diagnoses a value beyond uint64's range.
    return WordStorage;
}

// Statements: local declarations, assignments, expression statements and
// returns, from scheduling to the value's store.
// A function's named results are locals from `named` on.
StatementStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
                  params: Param[], table: ^(TypeDecl[]), members: TypeMember[], natives: ResolvedNative[], ports: ResolvedPort[],
                  identities: u64[], names: Name[], scope: int, package: int, values: Value[], top: int,
                  function: int, named: int, referenced: string[], mutated: string[], built: int[], addressed: string[],
                  generic_updates: int[], item: Work,
                  ops: Ops, target: Target, at: Bases) -> Step {
    types := table^;
    callable := callables[function];
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    popped: int = 0;
    produced := NoValue();
    retained := NoValue();
    // Mutating methods are calls on the shared root, with no assignment to
    // their receiver; `xs.append(x)` and `xs.extend(ys)` on a local array
    // push in place as `xs = append(xs, x)` does. A debug build keeps the
    // method call's own points.
    changing := item.phase == 0 && !ops.debug && kind == "expression_statement" &&
                LocalPush(forest, text, callables, natives, ports, identities, names, package, generic_updates,
                          item.node);
    if (item.phase == 0) {
        code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
        if (kind == "assignment" && QueryReadonlyDestination(forest, text, types, members, names,
                                                             StatementTarget(forest, item.node))) {
            return Fail(forest, item.node, document, "Query value bindings are read-only; use a component pointer to modify storage");
        }
        value := Field(forest, item.node, "value");
        if (kind == "expression_statement") {
            value = FirstMember(forest, item.node);
        }
        if (kind == "delete_statement" ||
            (kind == "expression_statement" && MapMethod(forest, text, names, value, "delete"))) {
            return MapDeleteStep(forest, text, document, types, names, item, ops, node);
        }
        if (kind == "assignment" && PointerDestination(forest, text, types, members, names,
                                                       StatementTarget(forest, item.node))) {
            return PointerAssignmentStart(forest, text, document, types, members, names, item, ops, target, at);
        }
        expected := Visit(value);
        if (kind == "local_declaration") {
            declared := Field(forest, item.node, "type");
            if (declared >= 0) {
                hidden := PrivateType(forest, text, types, names, package, declared);
                if (hidden >= 0) {
                    return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
                }
                resolved := ReadType(forest, text, table, names, package, declared);
                types = table^;
                if (resolved.storage == 0) {
                    return Fail(forest, declared, document, "local type is not supported yet");
                }
                if (value < 0) {
                    if (resolved.container == ViewContainer) {
                        return Fail(forest, item.node, document, "view local requires an initial value");
                    }
                    if (OptionalElement(types, Typed(-1, resolved.storage, resolved.container, resolved.record)).storage != 0) {
                        name_node := Field(forest, item.node, "name");
                        name := Text(forest, text, name_node);
                        if (Declared(names, scope, name)) {
                            return Fail(forest, name_node, document, format_text("Duplicate declaration '{}'", name));
                        }
                        cells.append(TypedCell(UnionStorage, 0, resolved.record));
                        code.append(SymbolCode(ops, name_node, node));
                        bound.append({owned: true, name: name, place: CellPlace, index: at.cell, storage: UnionStorage,
                                      container: 0, record: resolved.record, writable: true, node: name_node});
                        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                            0, NoValue(), NoValue(), marks);
                    }
                    if (resolved.storage != PointerStorage || resolved.container != 0 || resolved.record < 0 ||
                        types[resolved.record].key == 0) {
                        return Fail(forest, item.node, document, "non-null pointer local requires an initial value");
                    }
                    name_node := Field(forest, item.node, "name");
                    name := Text(forest, text, name_node);
                    if (Declared(names, scope, name)) {
                        return Fail(forest, name_node, document, format_text("Duplicate declaration '{}'", name));
                    }
                    constant := ConstantCode(ops, PointerStorage, 0, at.slot, node);
                    constant.value_record = resolved.record;
                    if (Holds(addressed, name)) {
                        EnsurePointer(table, {storage: PointerStorage, container: 0, record: resolved.record}, false, 0);
                        return PointerPrefix([constant], [{storage: PointerStorage, kind: ValueKind}],
                                             ManagedBoxStep(table^, members, Typed(at.slot, PointerStorage, 0, resolved.record),
                                                            name, name_node, 0, ops, target, SlotsPast(at, 1), node));
                    }
                    code.extend([constant, Instruction(ops.save, PointerStorage, 0, at.slot, 0, at.local, node),
                                 SymbolCode(ops, name_node, node)]);
                    binding: Name = {owned: false, name: name, place: LocalPlace, index: at.local, storage: PointerStorage,
                                     container: 0, record: resolved.record, writable: true, node: name_node};
                    return Step.Emitted(code, [{storage: PointerStorage, kind: ValueKind}],
                                        [ValueLocal(PointerStorage)], [], [], [], [], [binding], [], 0,
                                        NoValue(), NoValue(), []);
                }
                expected = Expect(value, resolved.storage, resolved.container, resolved.record);
            } else {
                inferred := InferredNumberStorage(forest, text, value);
                if (inferred > 0) {
                    expected = Expect(value, inferred, 0, -1);
                }
            }
        } else if (kind == "return_statement") {
            expected = Expect(value, callable.result, callable.result_container, callable.result_record);
        } else if (kind == "assignment" || changing) {
            destination := StatementTarget(forest, item.node);
            operator := CompoundOperator(Text(forest, text, Field(forest, item.node, "operator")));
            whole := SelfComponent(forest, text, types, names, destination);
            owned: int = -1;
            if (Is(forest, destination, "member_expression")) {
                owned = SelfComponent(forest, text, types, names, Field(forest, destination, "object"));
            }
            other := EntityComponent(forest, text, types, members, names, destination);
            other_owned: int = -1;
            if (Is(forest, destination, "member_expression")) {
                other_owned = EntityComponent(forest, text, types, members, names,
                                              Field(forest, destination, "object"));
            }
            if (Is(forest, destination, "identifier")) {
                found := Lookup(names, Text(forest, text, destination));
                if (found >= 0) {
                    binding := names[found];
                    expected = Expect(value, binding.storage, binding.container, binding.record);
                    // A compound write reads a managed target, with its points,
                    // before its value, as stage zero caches the target.
                    if (binding.place == ManagedPlace && operator != "") {
                        code.extend(NamePoints(forest, text, names, ops, destination));
                        read := PointerContinue(ManagedReadStep(types, binding, ops, target, at, node), expected);
                        return PointerPrefix(code, [], PointerContinue(read, Resume(item.node, PointerCompoundPhase,
                                                                                    found, 0)));
                    }
                    // `xs = append(xs, x)` and `xs = extend(xs, ys)` on a
                    // local array update it in place.
                    update: int = -1;
                    array: int = -1;
                    argument: int = -1;
                    // A method call updates in place only as its own statement;
                    // `xs = xs.append(x)` is an error CallStep reports.
                    if (operator == "" &&
                        (changing || !Is(forest, Field(forest, value, "function"), "member_expression"))) {
                        switch InPlaceUpdate(forest, text, callables, natives, ports, identities, names, package,
                                             found, destination, value) {
                            case .NotApplicable:
                                update = -1;
                            case .InPlace(mode, receiver, supplied, native):
                                // Preparation keeps contextual element typing, but no
                                // body is published before its WRITE proof closes.
                                next.append(RecordSemantic(item.node, UpdateFact, supplied));
                                next.append(RecordSemantic(value, NativeFact, native));
                                if (!generic_updates.contains(item.node)) {
                                    update = mode;
                                    array = receiver;
                                    argument = supplied;
                                }
                        }
                    }
                    if (update >= 0) {
                        // Stage zero evaluates the target, the call and the
                        // array it updates, as their points show; it writes a
                        // parameter through the reference the target reads.
                        if (Parameter(forest, binding)) {
                            code.extend(NamePoints(forest, text, names, ops, destination));
                        } else {
                            code.append(ExpressionCode(ops, forest[destination]));
                        }
                        code.append(ExpressionCode(ops, forest[value]));
                        code.extend(NamePoints(forest, text, names, ops, array));
                        address := AddressSlot(target);
                        slots.extend([address, address]);
                        code.extend(CellRead(target.pointer_storage, binding.index, ops, target, at.slot,
                                             forest[array]));
                        receiver: Root = {slot: at.slot + 1, storage: binding.storage, container: ArrayContainer,
                                          record: binding.record};
                        roots.append(receiver);
                        if (ops.debug) {
                            code.append(WatchCode(ops, at.slot + 1, binding.storage, ArrayContainer, binding.record,
                                                  0, true, forest[array], target));
                            code.append(WatchCode(ops, at.slot + 1, binding.storage, ArrayContainer, binding.record,
                                                  0, false, forest[value], target));
                        }
                        container: int = 0;
                        if (update == 1) {
                            container = ArrayContainer;
                        }
                        next.append(Expect(argument, binding.storage, container, binding.record));
                        finish := Resume(item.node, PushPhase, found, update);
                        finish.c = array;
                        next.append(finish);
                        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                            NoValue(), retained, marks);
                    }
                    if (operator != "" || Parameter(forest, binding) || binding.place == ManagedPlace) {
                        code.extend(NamePoints(forest, text, names, ops, destination));
                    }
                }
            } else if (whole >= 0) {
                code.extend(TargetPoints(forest, text, names, ops, destination));
                // The target's owner is watched as `self`, in a slot before
                // the component step's.
                code.extend(OwnerWatch(ops, at.slot, forest[TargetRoot(forest, destination)]));
                shifted := SlotsPast(at, 1);
                // `self.C op= v` combines the owner's component with the value
                // and writes the result through the reference it read.
                write := Resume(item.node, ComponentAssignPhase, shifted.slot + ComponentReferenceSlot, whole);
                if (operator == "") {
                    return PrefixSlots([ValueLocal(HandleStorage)],
                                       ComponentMakeStep(code, types, whole, -1, [Visit(value), write], ops, target,
                                                         shifted, node));
                }
                combine := Resume(item.node, CombinePhase, 0, 0);
                return PrefixSlots([ValueLocal(HandleStorage)],
                                   ComponentReadStep(code, types, whole, true, -1, [Visit(value), combine, write], ops,
                                                     target, shifted, node));
            } else if (owned >= 0) {
                // `self.C.f = v` on a component of the owner.
                code.extend(TargetPoints(forest, text, names, ops, destination));
                member := Text(forest, text, Field(forest, destination, "member"));
                field := FindField(types, members, owned, member);
                if (field < 0) {
                    return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                }
                if (members[field].c_string) {
                    message := CStringMessage(forest, text, value, members[field].name);
                    if (message != "") {
                        return Fail(forest, value, document, message);
                    }
                }
                if (!members[field].writable) {
                    return Fail(forest, destination, document, "Assignment requires a writable value");
                }
                code.extend(OwnerWatch(ops, at.slot, forest[TargetRoot(forest, destination)]));
                return PrefixSlots([ValueLocal(HandleStorage)],
                                   ComponentReferenceStep(code, types, members, owned, field, -1, value,
                                                          operator != "", item, ops, target, SlotsPast(at, 1), node));
            } else if (other >= 0 || other_owned >= 0) {
                // `e.C = v` and `e.C.f = v` on a component of another entity:
                // the entity, then the reference to its component.
                component := other;
                field: int = -1;
                entity := Field(forest, destination, "object");
                if (other_owned >= 0) {
                    component = other_owned;
                    entity = Field(forest, entity, "object");
                    member := Text(forest, text, Field(forest, destination, "member"));
                    field = FindField(types, members, component, member);
                    if (field < 0) {
                        return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                    }
                    if (members[field].c_string) {
                        message := CStringMessage(forest, text, value, members[field].name);
                        if (message != "") {
                            return Fail(forest, value, document, message);
                        }
                    }
                    if (!members[field].writable) {
                        return Fail(forest, destination, document, "Assignment requires a writable value");
                    }
                }
                // The members above the entity have points; the entity has
                // its own as it is evaluated.
                at_member := destination;
                while (at_member != entity) {
                    code.append(ExpressionCode(ops, forest[at_member]));
                    at_member = Field(forest, at_member, "object");
                }
                write := Resume(item.node, EntityComponentPhase, component, field);
                if (operator != "") {
                    write.c = 1;
                }
                next.extend([Visit(entity), write]);
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                    NoValue(), retained, marks);
            } else if (Is(forest, destination, "member_expression")) {
                // `x.f = v` on a local record, written as stage zero writes it.
                object := Field(forest, destination, "object");
                found: int = -1;
                if (Is(forest, object, "identifier")) {
                    found = Lookup(names, Text(forest, text, object));
                }
                if (found >= 0 && !names[found].writable) {
                    return Fail(forest, destination, document, "Assignment requires a writable value");
                }
                if (found < 0 || (names[found].place != CellPlace && names[found].place != ReferencePlace) ||
                    names[found].storage != StructStorage || names[found].container != 0) {
                    return Fail(forest, destination, document, "field assignment needs a local record");
                }
                member := Text(forest, text, Field(forest, destination, "member"));
                field := FindField(types, members, names[found].record, member);
                if (field < 0) {
                    return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                }
                if (members[field].c_string) {
                    message := CStringMessage(forest, text, value, members[field].name);
                    if (message != "") {
                        return Fail(forest, value, document, message);
                    }
                }
                code.extend(TargetPoints(forest, text, names, ops, destination));
                next.append(Expect(value, members[field].storage, 0, -1));
                write := Resume(item.node, FieldPhase, found, field);
                if (operator != "") {
                    write.c = 1;
                }
                next.append(write);
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                    NoValue(), retained, marks);
            } else if (Is(forest, destination, "index_expression")) {
                // `xs[i] = x` on a local array stores in place.
                object := Field(forest, destination, "object");
                found: int = -1;
                if (Is(forest, object, "identifier")) {
                    found = Lookup(names, Text(forest, text, object));
                }
                if (found >= 0 && names[found].container == MapContainer) {
                    return MapStoreStep(forest, text, document, types, names, found, item, ops, node);
                }
                if (found < 0 || names[found].place != CellPlace || names[found].container != ArrayContainer ||
                    !names[found].writable) {
                    return Fail(forest, destination, document, "element assignment needs a local array");
                }
                binding := names[found];
                compound: int = 0;
                code.append(ExpressionCode(ops, forest[destination]));
                if (operator != "") {
                    compound = 1;
                }
                if (operator != "" || Parameter(forest, binding)) {
                    code.extend(NamePoints(forest, text, names, ops, object));
                }
                next.append(Expect(Field(forest, destination, "index"), IntStorage, 0, -1));
                next.append(Expect(value, binding.storage, 0, binding.record));
                next.append(Resume(item.node, StorePhase, found, compound));
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                    NoValue(), retained, marks);
            }
        }
        if (kind == "return_statement" && callable.results > 0) {
            return NamedReturnStep(forest, document, code, params, callable, named, value, item, ops, target, at, node);
        }
        if (kind == "return_statement" && value < 0) {
            if (callable.result != 0) {
                return Fail(forest, item.node, document, "return needs a value");
            }
            code.append(CompletionCode(ops, node));
            code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
        } else {
            next.append(expected);
            next.append(Resume(item.node, ValuePhase, 0, 0));
        }
    } else if (item.phase == ValuePhase) {
        popped = 1;
        result := values[top - 1];
        if (result.storage < 0 && result.storage != NumberStorage && !Single(result, ResultsStorage) &&
            !Single(result, FunctionResultsStorage) && kind != "expression_statement") {
            return Fail(forest, item.node, document, "call has no value");
        }
        if (kind == "expression_statement" && result.storage == ResultsStorage) {
            return PointerPopped(DropNativeResultsStep(result, natives, ports, ops, target, at, node), 1);
        }
        if (kind == "expression_statement") {
            return PointerPopped(DropSequenceValues(Held(types, members, [result]), ops, target, at, node), 1);
        }
        // A union read from an array the function may change shares that
        // element's collections, which removing the element releases, so a
        // local takes its own copy.
        if (result.storage == UnionStorage && result.container == 0 && !result.owned &&
            length(Held(types, members, [result])) > 0 &&
            (kind == "local_declaration" ||
             (kind == "assignment" && Is(forest, StatementTarget(forest, item.node), "identifier"))) &&
            ChangingElement(forest, text, names, referenced, mutated, addressed, Field(forest, item.node, "value"))) {
            return PointerContinue(CopyValueStep(result, 1, ops, target, at, node), Resume(item.node, ValuePhase, 0, 0));
        }
        if (kind == "local_declaration") {
            declared := Field(forest, item.node, "type");
            local := result;
            if (declared < 0 && result.storage == NumberStorage) {
                return Fail(forest, Field(forest, item.node, "value"), document,
                            "local initializer has no concrete numeric type");
            }
            if (declared >= 0) {
                resolved := ReadType(forest, text, table, names, package, declared);
                types = table^;
                local = Typed(-1, resolved.storage, resolved.container, resolved.record);
            }
            if (result.container == 0 && local.container == 0 &&
                (Widens(result.storage, local.storage) || FloatWidens(result.storage, local.storage))) {
                widened: Slot = {storage: local.storage, kind: ValueKind};
                slots.append(widened);
                code.extend(NumberCode(ops, result.storage, local.storage, result.slot, at.slot + length(slots) - 1, node));
                result = Typed(at.slot + length(slots) - 1, local.storage, 0, -1);
            }
            if (!Accepts(types, local.storage, local.container, local.record, result)) {
                return Fail(forest, item.node, document, "local value differs from its type");
            }
            name := Text(forest, text, Field(forest, item.node, "name"));
            if (name == "") {
                return Fail(forest, Field(forest, item.node, "name"), document, "Invalid string or embedded NUL");
            }
            if (Declared(names, scope, name)) {
                return Fail(forest, Field(forest, item.node, "name"), document, format_text("Duplicate declaration '{}'", name));
            }
            if (Single(result, ResultsStorage) && !result.owned && declared < 0) {
                return PointerContinue(CopyNativeResultsStep(result, natives, ports, ops, target, at, node),
                                       Resume(item.node, ValuePhase, 0, 0));
            }
            if (Single(result, FunctionResultsStorage) && !result.owned && declared < 0) {
                return PointerContinue(CopyFunctionResultsStep(result, callables, params, ops, target, at, node),
                                       Resume(item.node, ValuePhase, 0, 0));
            }
            if ((Single(result, ResultsStorage) || Single(result, FunctionResultsStorage)) && declared < 0) {
                // Each binding owns an independent result bank.
                binding: Name = {owned: result.storage == ResultsStorage, name: name, place: ResultsPlace, index: result.slot, storage: result.storage,
                                 container: 0, record: result.record, writable: false,
                                 node: Field(forest, item.node, "name")};
                bound.append(binding);
            } else if (Holds(addressed, name)) {
                initial := result;
                initial.storage = local.storage;
                initial.container = local.container;
                initial.record = local.record;
                EnsurePointer(table, {storage: local.storage, container: local.container, record: local.record}, false, 0);
                return PointerPrefix(code, slots,
                                     ManagedBoxStep(table^, members, initial, name, Field(forest, item.node, "name"), 1,
                                                    ops, target, SlotsPast(at, length(slots)), node));
            } else if (Pointer(local.storage, local.container)) {
                // The local is the cell that holds its own copy, or the value
                // itself when it is fresh or a temporary it takes over, or
                // when neither it nor what it reads ever changes.
                code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
                // A lent element is read in place and never dropped.
                lent := LendsElement(forest, text, names, referenced, mutated, built, addressed,
                                     Field(forest, item.node, "value"));
                if (lent || result.owned || Fresh(forest, text, callables, natives, types, names, package, Field(forest, item.node, "value")) ||
                    (!Holds(mutated, name) &&
                     Unchanging(forest, text, callables, natives, types, names, package, mutated, Field(forest, item.node, "value")))) {
                    cells.append(MovedCell(result));
                    slots.append(AddressSlot(target));
                    code.extend(MoveCode(result, ops, target, at.slot + length(slots) - 1,
                                         at.cell + length(cells) - 1, node));
                    produced = result;
                    produced.cell = at.cell + length(cells) - 1;
                } else {
                    retained = result;
                }
                lending: int = 0;
                if (lent) {
                    lending = 1;
                }
                next.append(Resume(item.node, RetainedPhase, 0, lending));
            } else if (Holds(referenced, name) || (local.storage == UnionStorage && Holds(mutated, name))) {
                // A scoped argument lends it, or it is a union a write may
                // reach through its narrowed payload, so it lives in a data
                // cell.
                return BoxStep(forest, text, local, result, item, ops, target, at, node);
            } else {
                locals.append(ValueLocal(local.storage));
                code.append(Instruction(ops.save, local.storage, 0, result.slot, 0, at.local, node));
                code.append(SymbolCode(ops, Field(forest, item.node, "name"), node));
                binding: Name = {owned: false, name: name, place: LocalPlace, index: at.local, storage: local.storage, container: 0,
                                 record: local.record, writable: true, node: Field(forest, item.node, "name")};
                bound.append(binding);
            }
        } else if (kind == "assignment" || changing) {
            destination := StatementTarget(forest, item.node);
            found: int = -1;
            if (Is(forest, destination, "identifier")) {
                found = Lookup(names, Text(forest, text, destination));
            }
            if (found < 0 || names[found].place == ParameterPlace || Alias(names[found].place) ||
                names[found].place == SelfPlace) {
                return Fail(forest, destination, document, "assignment needs a local name");
            }
            if (names[found].place == ResultsPlace) {
                return Fail(forest, destination, document, "assigning a native's several results is not supported yet");
            }
            if (!names[found].writable) {
                return Fail(forest, destination, document, "Assignment requires a writable value");
            }
            binding := names[found];
            operator := CompoundOperator(Text(forest, text, Field(forest, item.node, "operator")));
            if (binding.container == 0 && MixedCompoundIntegers(operator, binding.storage, result)) {
                return Fail(forest, item.node, document,
                            format_text("Mismatched integer types {} and {}; convert one operand",
                                        TypeName(binding.storage), TypeName(result.storage)));
            }
            if (binding.place == NarrowedPlace) {
                if (operator != "") {
                    return Fail(forest, destination, document, "compound narrowed-value assignment is not supported yet");
                }
                element: ValueType = {storage: binding.storage, container: binding.container, record: binding.record};
                switch PayloadPlaceAfter(types, NamePlaceStep(forest, document, types, names[binding.index], destination,
                                                              ops, target, at),
                                         element, ops, target, at, node) {
                    case .Failed(diagnostic):
                        return Step.Failed(diagnostic);
                    case .Emitted(place_code, place_slots, place_locals, place_cells, place_hosts, place_roots,
                                  place_calls, place_bound, place_next, place_popped, place, place_retained,
                                  place_marks):
                        shifted: Bases = {pc: at.pc + length(place_code), slot: at.slot + length(place_slots),
                                          local: at.local, cell: at.cell + length(place_cells),
                                          host: at.host + length(place_hosts), call: at.call};
                        return SequenceJoined(Step.Emitted(place_code, place_slots, place_locals, place_cells,
                                                           place_hosts, place_roots, place_calls, place_bound,
                                                           place_next, 0, NoValue(), NoValue(), place_marks),
                                              IgnoreSequenceValue(SequenceCallStep([place, result],
                                                                                   ReferenceWriteIntrinsic, Typed(-1, BoolStorage, 0, -1),
                                                                                   u64(0), false, 1, ops, target, shifted, node)));
                }
            }
            if (binding.place == ManagedPlace) {
                return ManagedAssignStep(types, binding, result, ops, target, at, node);
            }
            if (binding.place == ReferencePlace || binding.place == BoxPlace) {
                return WriteStep(PlaceAssignStep(forest, text, document, binding, result, item, ops, target, at, node),
                                 item.node, binding.place == ReferencePlace);
            }
            stored := result;
            if (binding.container == 0 && result.container == 0 &&
                (Widens(result.storage, binding.storage) || FloatWidens(result.storage, binding.storage))) {
                widened: Slot = {storage: binding.storage, kind: ValueKind};
                slots.append(widened);
                code.extend(NumberCode(ops, result.storage, binding.storage, result.slot, at.slot + length(slots) - 1, node));
                result = Typed(at.slot + length(slots) - 1, binding.storage, 0, -1);
                stored = result;
            }
            if (operator != "") {
                op := BinaryOp(ops, operator);
                if (op < 0 || Comparison(ops, op) || !Numeric(binding.storage) || binding.container != 0 ||
                    !Single(result, binding.storage)) {
                    return Fail(forest, item.node, document, "compound assignment needs number operands of its type");
                }
                if (!Computes(ops, op, binding.storage)) {
                    return Fail(forest, item.node, document, "unsupported arithmetic type");
                }
                current: Slot = {storage: binding.storage, kind: ValueKind};
                slots.append(current);
                read := ops.local;
                if (binding.place == StatePlace) {
                    read = ops.variable;
                }
                code.append(Instruction(read, binding.storage, at.slot + length(slots) - 1, binding.index, 0,
                                        0, node));
                // Stage zero watches the target it reads and the value it
                // stores.
                code.append(ScalarWatch(ops, at.slot + length(slots) - 1, binding.storage, 0, true,
                                        forest[destination]));
                slots.append(current);
                code.append(Instruction(op, binding.storage, at.slot + length(slots) - 1,
                                        at.slot + length(slots) - 2, result.slot, -1, node));
                code.append(ScalarWatch(ops, at.slot + length(slots) - 1, binding.storage, 0, true,
                                        forest[destination]));
                stored = Typed(at.slot + length(slots) - 1, binding.storage, 0, -1);
            }
            if (!Accepts(types, binding.storage, binding.container, binding.record, stored)) {
                return Fail(forest, item.node, document, "assigned value differs from its local");
            }
            if (binding.place == CellPlace) {
                // A fresh value or a temporary replaces the cell's payload
                // without a copy.
                if (stored.owned || Fresh(forest, text, callables, natives, types, names, package, StatementValue(forest, item.node))) {
                    produced = stored;
                } else {
                    retained = stored;
                }
                next.append(Resume(item.node, RetainedPhase, binding.index, 0));
            } else if (binding.place == StatePlace) {
                next.append(RecordSemantic(item.node, WriteFact, 0));
                if (binding.storage == TextStorage) {
                    // STORE_VALUE snapshots the descriptor and its bytes into
                    // the instance's storage, beyond this invocation's arena.
                    initial: Cell = {storage: TextStorage, container: 0, record: -1, constant: 0,
                                     variant: -1, kind: ValueKind};
                    cells.append(initial);
                    slots.append(AddressSlot(target));
                    code.extend(CellWrite(TextStorage, stored.slot, at.cell, ops, target,
                                          at.slot + length(slots) - 1, node));
                    code.append(Instruction(ops.store_value, 0, 0, at.cell, 0, binding.index, node));
                } else {
                    code.append(Instruction(ops.store, binding.storage, 0, stored.slot, 0, binding.index, node));
                }
            } else {
                code.append(Instruction(ops.save, binding.storage, 0, stored.slot, 0, binding.index, node));
            }
            if (!Parameter(forest, binding)) {
                code.append(SymbolCode(ops, binding.node, node));
            }
        } else if (kind == "return_statement") {
            if (result.container == 0 && callable.result_container == 0 &&
                (Widens(result.storage, callable.result) || FloatWidens(result.storage, callable.result))) {
                widened: Slot = {storage: callable.result, kind: ValueKind};
                slots.append(widened);
                code.extend(NumberCode(ops, result.storage, callable.result, result.slot, at.slot + length(slots) - 1, node));
                result = Typed(at.slot + length(slots) - 1, callable.result, 0, -1);
            }
            if (!Returns(types, callable.result, callable.result_container, callable.result_record, result) &&
                !Accepts(types, callable.result, callable.result_container, callable.result_record, result)) {
                return Fail(forest, item.node, document, "returned value differs from the result type");
            }
            if (Pointer(result.storage, result.container) &&
                (result.owned ||
                 Fresh(forest, text, callables, natives, types, names, package, Field(forest, item.node, "value")))) {
                // A fresh value or a temporary is already the copy a return
                // would make, and a built local already lies in the caller's
                // storage.
                cells.append(MovedCell(result));
                slots.append(AddressSlot(target));
                code.extend(MoveCode(result, ops, target, at.slot + length(slots) - 1,
                                     at.cell + length(cells) - 1, node));
                produced = result;
                produced.cell = at.cell + length(cells) - 1;
                next.append(Resume(item.node, RetainedPhase, -1, 0));
            } else if (Pointer(result.storage, result.container)) {
                retained = result;
                next.append(Resume(item.node, RetainedPhase, -1, 0));
            } else {
                code.append(SymbolCode(ops, -1, forest[Field(forest, item.node, "value")]));
                code.append(CompletionCode(ops, node));
                code.append(Instruction(ops.result, result.storage, 0, result.slot, 0, 0, node));
                code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
            }
        }
    } else if (item.phase == FieldPhase) {
        popped = 1;
        binding := names[item.a];
        return WriteStep(EffectsStep(FieldStep(forest, text, document, binding, members[item.b], values[top - 1], item,
                                               ops, target, at, node), MemberEffects(types, binding.record)),
                         item.node, binding.place == ReferencePlace);
    } else if (item.phase == ComponentPhase) {
        return WriteStep(ComponentWriteStep(forest, text, document, members[item.b], values[top - 1], item, ops,
                                            target, at, node), item.node, true);
    } else if (item.phase == ComponentAssignPhase) {
        return WriteStep(ComponentAssignStep(forest, document, types, values[top - 1], item, ops, target, at, node),
                         item.node, true);
    } else if (item.phase == EntityComponentPhase) {
        return EntityComponentStep(forest, types, members, values[top - 1], item, ops, target, at, node);
    } else if (item.phase == ReturnsPhase) {
        return ResultsStep(forest, document, types, params, callable, named, values, top, item, ops, target, at, node);
    } else if (item.phase == MapStorePhase || item.phase == MapDeletePhase) {
        return MapUpdateStep(forest, text, document, types, names, values, top, item, ops, target, at, node);
    } else if (item.phase == RetainedPhase) {
        // A retained copy or a moved fresh value, in the last cell: bind it,
        // store it in a local's cell, or publish its header.
        popped = 1;
        kept := values[top - 1];
        address: Slot = {storage: target.pointer_storage, kind: AddressKind};
        if (kind == "local_declaration") {
            binding: Name = {owned: item.b == 0, name: Text(forest, text, Field(forest, item.node, "name")), place: CellPlace,
                             index: kept.cell, storage: kept.storage, container: kept.container, record: kept.record,
                             writable: true, node: Field(forest, item.node, "name")};
            bound.append(binding);
        } else if (kind == "assignment" || changing) {
            code.extend(CellRead(SlotStorage(kept.storage, kept.container, target), item.a,
                                 ops, target, at.slot, node));
            slots.extend([address, {storage: SlotStorage(kept.storage, kept.container, target),
                                    kind: SlotKind(kept.storage, kept.container)}]);
            old := Typed(at.slot + 1, kept.storage, kept.container, kept.record);
            old.owned = true;
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + 2, item.a, 0, 0, node));
            write := Instruction(ops.write, target.pointer_storage, 0, kept.slot, at.slot + 2, 0, node);
            write.offset = target.payload_offset;
            code.append(write);
            code.extend(SchemaWriteCode(kept, at.slot + 2, ops, target, node));
            emitted := Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                    popped, NoValue(), NoValue(), marks);
            return CleanupSequenceValues(emitted, Held(types, members, [old]), ops, target, at, node);
        } else {
            // Copy the cell's whole header, type name and layout included,
            // into result zero.
            code.append(SymbolCode(ops, -1, forest[Field(forest, item.node, "value")]));
            code.append(CompletionCode(ops, node));
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, kept.cell, 0, 0, node));
            slots.append(address);
            context := Instruction(ops.context, target.pointer_storage, at.slot + 1, 0, 0, 0, node);
            context.offset = target.results_offset;
            code.append(context);
            zero: Slot = {storage: IntStorage, kind: ValueKind};
            slots.append(zero);
            constant := Instruction(ops.constant, IntStorage, at.slot + 2, 0, 0, 0, node);
            constant.value_storage = IntStorage;
            code.append(constant);
            slots.append(address);
            element := Instruction(ops.index, target.pointer_storage, at.slot + 3, at.slot + 1, at.slot + 2, 0, node);
            element.offset = target.value_size;
            code.append(element);
            header: int[] = [target.type_offset, target.container_offset, target.name_offset,
                             target.record_offset, target.schema_offset, target.payload_offset];
            part: int = 0;
            while (part < 6) {
                loaded := address;
                if (part < 2) {
                    loaded = zero;
                }
                slots.append(loaded);
                load := Instruction(ops.load, loaded.storage, at.slot + length(slots) - 1, at.slot, 0, 0, node);
                load.offset = header[part];
                code.append(load);
                store := Instruction(ops.write, loaded.storage, 0, at.slot + length(slots) - 1, at.slot + 3, 0, node);
                store.offset = header[part];
                code.append(store);
                part += 1;
            }
            code.append(Instruction(ops.finish, 0, 0, 0, 0, 0, node));
        }
    } else {
        // An in-place update of the local array names[item.a]: a push or an
        // extension, or an element store (compound when item.b is 1).
        binding := names[item.a];
        item_value := NoValue();
        index_value := NoValue();
        intrinsic := ArrayStoreIntrinsic;
        item_container: int = 0;
        if (item.phase == PushPhase) {
            popped = 1;
            item_value = values[top - 1];
            intrinsic = ArrayPushIntrinsic;
            if (item.b == 1) {
                intrinsic = ArrayExtendIntrinsic;
                item_container = ArrayContainer;
            }
        } else if (item.b == 1) {
            // Read the element at the index already evaluated, then combine.
            popped = 2;
            index_value = values[top - 2];
            operand := values[top - 1];
            op := BinaryOp(ops, CompoundOperator(Text(forest, text, Field(forest, item.node, "operator"))));
            if (op < 0 || Comparison(ops, op) || binding.storage != IntStorage || !Single(operand, IntStorage)) {
                return Fail(forest, item.node, document, "compound assignment needs int operands");
            }
            if (!Single(index_value, IntStorage)) {
                return Fail(forest, item.node, document, "index needs an int");
            }
            address: Slot = {storage: target.pointer_storage, kind: AddressKind};
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, binding.index, 0, 0, node));
            slots.append(address);
            load := Instruction(ops.load, target.pointer_storage, at.slot + 1, at.slot, 0, 0, node);
            load.offset = target.payload_offset;
            code.append(load);
            root: Root = {slot: at.slot + 1, storage: IntStorage, container: ArrayContainer, record: -1};
            roots.append(root);
            slots.extend(ElementSlots(IntStorage, true, target));
            code.extend(ElementRead(at.slot + 1, index_value.slot, IntStorage, true, at.slot + 2,
                                    at.pc + length(code), -1, ops, target, node));
            element := at.slot + length(slots) - 1;
            code.append(ScalarWatch(ops, element, IntStorage, 0, true,
                                    forest[Field(forest, item.node, "target")]));
            combined: Slot = {storage: IntStorage, kind: ValueKind};
            slots.append(combined);
            code.append(Instruction(op, IntStorage, element + 1, element, operand.slot, -1, node));
            item_value = Typed(element + 1, IntStorage, 0, -1);
        } else {
            popped = 2;
            index_value = values[top - 2];
            item_value = values[top - 1];
        }
        if (intrinsic == ArrayStoreIntrinsic && !Single(index_value, IntStorage)) {
            return Fail(forest, item.node, document, "index needs an int");
        }
        if (!SameType(binding.storage, item_container, binding.record, item_value)) {
            return Fail(forest, item.node, document, "array item differs from the array's type");
        }
        // The intrinsic takes the local's header address, then the index of a
        // store, then the item; it returns a bool.
        address_cell: Cell = {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: AddressKind};
        cells.append(address_cell);
        sources: int[] = [-1];
        storages: int[] = [target.pointer_storage];
        if (intrinsic == ArrayStoreIntrinsic) {
            index_cell: Cell = {storage: IntStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
            cells.append(index_cell);
            sources.append(index_value.slot);
            storages.append(IntStorage);
        }
        item_cell: Cell = {storage: binding.storage, container: item_container, record: binding.record, constant: 0, variant: -1,
                           kind: ValueKind};
        cells.append(item_cell);
        sources.append(item_value.slot);
        storages.append(SlotStorage(item_value.storage, item_value.container, target));
        done: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
        cells.append(done);
        address: Slot = {storage: target.pointer_storage, kind: AddressKind};
        call := StatementValue(forest, item.node);
        if (item.phase == PushPhase && ops.debug) {
            code.append(WatchCode(ops, item_value.slot, item_value.storage, item_value.container,
                                  item_value.record, 1, false, forest[call], target));
        }
        slots.append(address);
        header_slot := at.slot + length(slots) - 1;
        code.append(Instruction(ops.host_slot, target.pointer_storage, header_slot, binding.index, 0, 0, node));
        sources[0] = header_slot;
        argument: int = 0;
        while (argument < length(sources)) {
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                                    at.cell + argument, 0, 0, node));
            write := Instruction(ops.write, storages[argument], 0, sources[argument], at.slot + length(slots) - 1, 0, node);
            write.offset = target.payload_offset;
            code.append(write);
            argument += 1;
        }
        // A local the function returns grows in its caller's storage.
        if (built.contains(binding.node)) {
            intrinsic += InResult;
        }
        host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                      result_count: 1, written: false};
        hosts.append(host);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        // The array a push leaves is the call's watched output.
        if (item.phase == PushPhase && ops.debug) {
            slots.append(address);
            reread := Instruction(ops.load, target.pointer_storage, at.slot + length(slots) - 1, header_slot, 0, 0, node);
            reread.offset = target.payload_offset;
            code.append(reread);
            code.append(WatchCode(ops, at.slot + length(slots) - 1, binding.storage, ArrayContainer,
                                  binding.record, 0, true, forest[call], target));
        }
        // A push or a plain element store stores a local array; a push then
        // evaluates it again.
        if ((item.phase == PushPhase || item.b == 0) && !Parameter(forest, binding)) {
            code.append(SymbolCode(ops, binding.node, node));
        }
        if (item.phase == PushPhase && !Parameter(forest, binding)) {
            code.extend(NamePoints(forest, text, names, ops, item.c));
        }
        // The array keeps its own copy of the item, so a temporary item is
        // dropped here rather than held until the function returns.
        return CleanupSequenceValues(Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                                  popped, produced, retained, marks),
                                     [item_value], ops, target, at, node);
    }
    return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks);
}

// Whether the statement `node` appends to or extends a local array by method,
// which updates it in place.
LocalPush :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], natives: ResolvedNative[],
              ports: ResolvedPort[], identities: u64[], names: Name[], package: int, generic_updates: int[],
              node: int) -> bool {
    value := StatementValue(forest, node);
    if (!Is(forest, value, "call_expression") || !Is(forest, Field(forest, value, "function"), "member_expression") ||
        generic_updates.contains(node)) {
        return false;
    }
    receiver := StatementTarget(forest, node);
    if (!Is(forest, receiver, "identifier")) {
        return false;
    }
    found := Lookup(names, Text(forest, text, receiver));
    if (found < 0) {
        return false;
    }
    switch InPlaceUpdate(forest, text, callables, natives, ports, identities, names, package, found, receiver, value) {
        case .NotApplicable:
            return false;
        case .InPlace(mode, array, argument, native):
            return true;
    }
}

// The existing integer-literal semantic decision, shared with the narrow scalar
// proof producer. Context chooses storage; parsing, range checking and exact
// bits have one implementation. This does not infer a type from spelling.
IntegerLiteralResult :: union {
    Rejected(diagnostic: syntax.Diagnostic) | Checked(bits: u64)
}
ReadIntegerLiteral :: (forest: snapshot.SnapshotNode[], text: string, document: int, node: int,
                       storage: int) -> IntegerLiteralResult {
    parsed := ParseNumber(forest, text, node);
    if (!Floating(storage) && InferredNumberStorage(forest, text, node) == FloatStorage) {
        // A whole decimal such as 2.0 or 1e3 is the integer it spells.
        digits := node;
        if (Is(forest, node, "unary_expression")) {
            digits = Field(forest, node, "operand");
        }
        switch IntegralOf(Text(forest, text, digits)) {
            case .Fraction:
                return IntegerLiteralResult.Rejected(Diagnose(forest, node, document,
                                                              format_text("Numeric literal has a fraction, which {} cannot hold", TypeName(storage))));
            case .Large:
                return IntegerLiteralResult.Rejected(Diagnose(forest, node, document,
                                                              format_text("Numeric literal is outside the range of {}", TypeName(storage))));
            case .Whole(whole):
                parsed = Literal.Number(digits != node && whole != 0, whole);
        }
    }
    switch parsed {
        case .Invalid:
            return IntegerLiteralResult.Rejected(Diagnose(forest, node, document,
                                                          "only integer literals of 64 bits are supported"));
        case .Number(negative, magnitude):
            if (!Fits(negative, magnitude, storage)) {
                return IntegerLiteralResult.Rejected(Diagnose(forest, node, document,
                                                              format_text("Numeric literal is outside the range of {}", TypeName(storage))));
            }
            return IntegerLiteralResult.Checked(Bits(negative, magnitude));
    }
}

// Literals, names, parentheses, field reads and element reads.
ValueStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
              params: Param[], types: TypeDecl[], members: TypeMember[], constants: ConstDecl[], natives: ResolvedNative[],
              ports: ResolvedPort[], native_calls: NativeCallFact[], names: Name[], package: int, referenced: string[],
              mutated: string[], built: int[], addressed: string[], values: Value[], top: int, item: Work, ops: Ops,
              target: Target, at: Bases) -> Step {
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    popped: int = 0;
    produced := NoValue();
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    if (kind == "nil" && item.container == ViewContainer) {
        return Fail(forest, item.node, document, "view requires an initialized value");
    }
    // `nil` where a pointer is expected; `null` for an entity is below.
    if (kind == "nil" && item.storage == PointerStorage) {
        if (item.container != 0 || item.record < 0 || types[item.record].key == 0) {
            return Fail(forest, item.node, document, "nil requires a nullable pointer type");
        }
        constant := ConstantCode(ops, PointerStorage, 0, at.slot, node);
        constant.value_record = item.record;
        return Step.Emitted([constant], [{storage: PointerStorage, kind: ValueKind}], [], [], [], [], [], [], [],
                            0, Typed(at.slot, PointerStorage, 0, item.record), NoValue(), []);
    }
    if (item.phase == 0 && kind == "member_expression") {
        hidden := PrivateAccess(forest, text, callables, types, constants, names, package, item.node);
        if (hidden >= 0) {
            return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
        }
    }
    if (kind == "nil" || (kind == "number" && item.storage == HandleStorage && item.container == 0)) {
        empty := kind == "nil" && Text(forest, text, item.node) == "null";
        if (kind == "number") {
            switch NumberBits(forest, text, item.node) {
                case .Finite(double_bits, float_fits, float_bits):
                    empty = (double_bits & 0x7fffffffffffffff) == 0;
                case .OutOfRange:
                    return Fail(forest, item.node, document, "Numeric literal is outside the range of its type");
            }
        }
        if (item.storage != HandleStorage || item.container != 0 || !empty) {
            if (kind == "number") {
                return Fail(forest, item.node, document, "entity value requires null or zero");
            }
            return Fail(forest, item.node, document, "unsupported nil or null value");
        }
        slots.append(ValueLocal(HandleStorage));
        code.append(ConstantCode(ops, HandleStorage, 0, at.slot, node));
        if (kind == "number") {
            code.extend(LiteralWatch(forest, ops, at.slot, HandleStorage, item.node));
        }
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                            Typed(at.slot, HandleStorage, 0, item.record), NoValue(), marks);
    }
    if (kind == "number" && Floating(item.storage)) {
        // A literal where a floating value is expected is one.
        return FloatConstantStep(forest, text, document, Typed(-1, NumberStorage, 0, item.node), item.storage, ops, at,
                                 node);
    }
    if (kind == "nil") {
        slots.append(ValueLocal(UnionStorage));
        code.append(ConstantCode(ops, UnionStorage, 0, at.slot, node));
        produced = Typed(at.slot, UnionStorage, 0, item.record);
    } else if (kind == "number" && !Integer(item.storage)) {
        // An untyped literal: its use gives it a type.
        produced = Typed(-1, NumberStorage, 0, item.node);
    } else if (kind == "number" || kind == "boolean" || kind == "string") {
        storage := item.storage;
        payload: u64 = 0;
        literal := "";
        if (kind == "number") {
            switch ReadIntegerLiteral(forest, text, document, item.node, storage) {
                case .Rejected(diagnostic):
                    return Step.Failed(diagnostic);
                case .Checked(bits):
                    payload = bits;
            }
        } else if (kind == "boolean") {
            storage = BoolStorage;
            if (Text(forest, text, item.node) == "true") {
                payload = 1;
            }
        } else {
            // String literals are JSON strings.
            storage = TextStorage;
            decoded := compiler_json_value_string(Text(forest, text, item.node));
            if (!decoded.valid) {
                return Fail(forest, item.node, document, "Invalid string literal");
            }
            literal = decoded.value;
        }
        slot: Slot = {storage: storage, kind: ValueKind};
        slots.append(slot);
        constant := ConstantCode(ops, storage, payload, at.slot, node);
        constant.text = literal;
        constant.has_text = kind == "string";
        code.append(constant);
        if (kind == "number") {
            code.extend(LiteralWatch(forest, ops, at.slot, storage, item.node));
        }
        produced = Typed(at.slot, storage, 0, -1);
    } else if (item.phase == 0 && (kind == "identifier" || kind == "member_expression") &&
               ConstantOf(forest, text, constants, names, package, item.node) >= 0) {
        // A package constant is its value.
        declared := constants[ConstantOf(forest, text, constants, names, package, item.node)];
        slot: Slot = {storage: declared.storage, kind: ValueKind};
        slots.append(slot);
        code.append(ConstantCode(ops, declared.storage, declared.bits, at.slot, node));
        produced = Typed(at.slot, declared.storage, 0, -1);
    } else if (kind == "identifier" && item.phase == NarrowedReadPhase) {
        // The payload of the optional a narrowed name just read, which stage
        // zero marks again as the payload.
        return PointerPrefix([ExpressionCode(ops, node)], [],
                             OptionalUnwrapStep(types, values[top - 1], 1, ops, target, at, node));
    } else if (kind == "identifier") {
        wanted := Text(forest, text, item.node);
        found := Lookup(names, wanted);
        if (item.phase == NarrowedOriginalPhase) {
            found = item.a;
        }
        if (found < 0 || Alias(names[found].place)) {
            return Fail(forest, item.node, document, format_text("Unknown name '{}'", wanted));
        }
        binding := names[found];
        if (binding.place == NarrowedPlace) {
            // A narrowed name reads its optional, then takes the payload,
            // each watched.
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound,
                                [Resume(item.node, NarrowedOriginalPhase, binding.index, 0),
                                 Resume(item.node, NarrowedReadPhase, 0, 0)],
                                0, NoValue(), NoValue(), marks);
        }
        if (binding.place == SystemStepPlace) {
            read := Instruction(ops.context, DoubleStorage, at.slot, 0, 0, 0, node);
            read.offset = binding.index;
            code := [read, Instruction(ops.convert, FloatStorage, at.slot + 1, at.slot, 0, 0, node)];
            slots := [ValueLocal(DoubleStorage), ValueLocal(FloatStorage)];
            if (binding.storage == DoubleStorage) {
                code.append(Instruction(ops.convert, DoubleStorage, at.slot + 2, at.slot + 1, 0, 0, node));
                slots.append(ValueLocal(DoubleStorage));
            }
            return Step.Emitted(code, slots, [], [], [], [], [], [], [], 0,
                                Typed(at.slot + length(slots) - 1, binding.storage, 0, -1), NoValue(), []);
        }
        if (binding.place == QuerySnapshotPlace) {
            return QuerySnapshotReadStep(binding, names, ops, target, at, node);
        }
        if (binding.place == QueryFieldPlace) {
            read := QueryFieldReadStep(binding, QueryFieldRow(types, members, binding.node),
                                       values, top, item, ops, target, at, node);
            if (item.phase != 0 && binding.storage == PointerStorage && binding.record >= 0 &&
                types[binding.record].key != 0 && QueryAccessPresent(forest, text, types, names, item.node)) {
                element := PointerElement(types, Typed(-1, PointerStorage, 0, binding.record));
                return PointerNarrow(read, FindPointer(types, element, false));
            }
            return read;
        }
        if (binding.place == LocalPlace && binding.storage == UnionStorage && binding.container == 0 &&
            binding.record >= 0 && types[binding.record].kind == TaskResultDecl &&
            TaskResultPresent(forest, text, binding, item.node)) {
            return TaskResultReadStep(types, binding, ops, target, at, node);
        }
        narrowed: int = -1;
        if (Single(Typed(-1, binding.storage, binding.container, binding.record), PointerStorage) &&
            binding.record >= 0 && types[binding.record].key != 0 &&
            (PointerPresent(forest, text, binding, item.node) || QueryAccessPresent(forest, text, types, names, item.node))) {
            element := PointerElement(types, Typed(-1, PointerStorage, 0, binding.record));
            narrowed = FindPointer(types, element, false);
        }
        if (binding.place == ResultsPlace) {
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                Typed(binding.index, binding.storage, 0, binding.record), NoValue(), marks);
        }
        if (binding.place == GlobalPlace) {
            return Fail(forest, item.node, document,
                        format_text("reading the global '{}' is not supported yet", wanted));
        }
        if (binding.place == ManagedPlace) {
            read := ManagedReadStep(types, binding, ops, target, at, node);
            if (narrowed >= 0) {
                return PointerNarrow(read, narrowed);
            }
            return read;
        }
        if (binding.place == ReferencePlace || binding.place == BoxPlace) {
            read := PlaceReadStep(binding, ops, target, at, node);
            if (binding.place == ReferencePlace) {
                read = CellSchemaStep(read, at.cell + 1, ops, target, at, node);
            }
            if (binding.place == BoxPlace) {
                read = CellSchemaStep(read, binding.index, ops, target, at, node);
            }
            if (narrowed >= 0) {
                return PointerNarrow(read, narrowed);
            }
            return read;
        }
        if (binding.place == LocalPlace || binding.place == StatePlace || binding.place == SelfPlace) {
            op := ops.local;
            if (binding.place == StatePlace) {
                op = ops.variable;
            } else if (binding.place == SelfPlace) {
                op = ops.owner;
            }
            slot: Slot = {storage: binding.storage, kind: ValueKind};
            slots.append(slot);
            code.append(Instruction(op, binding.storage, at.slot, binding.index, 0, 0, node));
        } else {
            slots.append(address);
            if (binding.place == CellPlace) {
                code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, binding.index, 0, 0, node));
                slots.append(address);
                load := Instruction(ops.load, target.pointer_storage, at.slot + 1, at.slot, 0, 0, node);
                load.offset = target.payload_offset;
                code.append(load);
            } else {
                read := Instruction(ops.array, target.pointer_storage, at.slot, binding.index, 0, ops.argument, node);
                read.value_storage = binding.storage;
                read.value_container = binding.container;
                read.value_record = binding.record;
                code.append(read);
            }
            root: Root = {slot: at.slot + length(slots) - 1, storage: binding.storage, container: binding.container,
                          record: binding.record};
            roots.append(root);
        }
        produced = Typed(at.slot + length(slots) - 1, binding.storage, binding.container, binding.record);
        if (narrowed >= 0) {
            produced.record = narrowed;
        }
        if (produced.storage == StructStorage && produced.container == 0) {
            read := Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, produced, NoValue(), marks);
            if (binding.place == CellPlace) {
                return CellSchemaStep(read, binding.index, ops, target, at, node);
            }
            if (binding.place == ParameterPlace) {
                return ArgumentSchemaStep(read, binding.index, ops, target, at, node);
            }
        }
    } else if (kind == "parenthesized_expression") {
        next.append(Expect(Field(forest, item.node, "expression"), item.storage, item.container, item.record));
    } else if (item.phase == 0 && kind == "member_expression" &&
               UnionOf(forest, text, types, names, package, item.node) >= 0) {
        // A variant without a payload: the constructor takes only its tag.
        sum_type := UnionOf(forest, text, types, names, package, item.node);
        member := Text(forest, text, Field(forest, item.node, "member"));
        variant := FindVariant(types, sum_type, member);
        if (variant < 0) {
            return Fail(forest, item.node, document, format_text("Unknown variant '{}'", member));
        }
        if (types[variant].count != 0) {
            return Fail(forest, item.node, document, format_text("variant '{}' needs its payload", member));
        }
        tag: Cell = {storage: WordStorage, container: 0, record: -1, constant: 0, variant: variant, kind: ValueKind};
        cells.append(tag);
        made: Cell = {storage: UnionStorage, container: 0, record: sum_type, constant: 0, variant: -1, kind: ValueKind};
        cells.append(made);
        host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: UnionMakeIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 1,
                      result_count: 1, written: false};
        hosts.append(host);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, at.cell + 1, 0, 0, node));
        value: Slot = {storage: UnionStorage, kind: ValueKind};
        slots.append(value);
        load := Instruction(ops.load, UnionStorage, at.slot + 1, at.slot, 0, 0, node);
        load.offset = target.payload_offset;
        code.append(load);
        produced = Typed(at.slot + 1, UnionStorage, 0, sum_type);
    } else if (item.phase == 0 && kind == "member_expression" &&
               KeyedMember(forest, text, types, members, names, item.node) >= 0) {
        // A global's keyed field, such as a scene binding, a native reads by
        // its key.
        field := members[KeyedMember(forest, text, types, members, names, item.node)];
        port := ports[natives[field.read].first];
        key: Value = {cell: -1, owned: false, place: false, newkey: false, slot: at.slot, storage: port.storage,
                      container: port.container, record: port.record, schema: -1};
        constant := ConstantCode(ops, key.storage, 0, at.slot, node);
        constant.text = field.read_key;
        constant.has_text = true;
        shifted: Bases = {pc: at.pc + 1, slot: at.slot + 1, local: at.local, cell: at.cell, host: at.host,
                          call: at.call};
        switch NativeReadStep(forest, document, item.node, types, natives, ports, key, field, ops, target, shifted) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(read_code, read_slots, read_locals, read_cells, read_hosts, read_roots, read_calls,
                          read_bound, read_next, read_popped, read_value, read_retain, read_marks):
                read := Typed(read_value.slot, read_value.storage, 0, field.record);
                read.schema = read_value.schema;
                return Step.Emitted(extend([constant], read_code), extend([ValueLocal(key.storage)], read_slots),
                                    read_locals, read_cells, read_hosts, read_roots, read_calls, read_bound,
                                    read_next, 0, read, NoValue(), read_marks);
        }
    } else if (item.phase == 0 && kind == "member_expression" &&
               ConstantMember(forest, text, types, members, names, item.node) >= 0) {
        // A constant member of a global, such as an input action, is its name.
        field := members[ConstantMember(forest, text, types, members, names, item.node)];
        slots.append(ValueLocal(field.storage));
        constant := ConstantCode(ops, field.storage, 0, at.slot, node);
        constant.text = field.name;
        constant.has_text = true;
        code.append(constant);
        produced = Typed(at.slot, field.storage, 0, field.record);
    } else if (item.phase == 0 && kind == "member_expression" &&
               SelfComponent(forest, text, types, names, item.node) >= 0) {
        return ComponentReadStep([], types, SelfComponent(forest, text, types, names, item.node), false, -1, [],
                                 ops, target, at, node);
    } else if (item.phase == 0) {
        next.append(Visit(Field(forest, item.node, "object")));
        // An index's type is a map's key type or an array's int.
        if (kind == "index_expression") {
            next.append(Resume(item.node, KeyPhase, 0, 0));
        } else {
            next.append(Resume(item.node, 1, 0, 0));
        }
    } else if (item.phase == KeyPhase) {
        // The object is ready, so the index takes a map's key type or an
        // array's int.
        index := Field(forest, item.node, "index");
        if (IsMap(values[top - 1])) {
            next.append(Expect(index, types[values[top - 1].record].key, 0, -1));
        } else {
            next.append(Expect(index, IntStorage, 0, -1));
        }
        next.append(Resume(item.node, 1, 0, 0));
    } else if (kind == "member_expression") {
        popped = 1;
        object := values[top - 1];
        member := Text(forest, text, Field(forest, item.node, "member"));
        if (Single(object, QueryStorage) && object.record >= 0) {
            if (types[object.record].kind != QueryDecl) {
                return Fail(forest, item.node, document, "Query description fields are available through iteration");
            }
            field := FindField(types, members, object.record, member);
            if (field < 0) {
                return Fail(forest, item.node, document, format_text("Unknown query row field '{}'", member));
            }
            declared := members[field];
            read := QueryGetStep(object, field - types[object.record].first,
                                 {storage: declared.storage, container: declared.container, record: declared.record},
                                 1, ops, target, at, node);
            if (declared.storage == PointerStorage && declared.record >= 0 && types[declared.record].key != 0 &&
                QueryAccessPresent(forest, text, types, names, item.node)) {
                element := PointerElement(types, Typed(-1, PointerStorage, 0, declared.record));
                return PointerNarrow(read, FindPointer(types, element, false));
            }
            return read;
        }
        if (Single(object, StructStorage) && object.record >= 0 && types[object.record].kind == OptionalComponentDecl) {
            if (!QueryAccessPresent(forest, text, types, names, Field(forest, item.node, "object"))) {
                return Fail(forest, item.node, document, "Optional component requires a presence guard before field access");
            }
            object.record = types[object.record].parent;
        }
        if (member == "") {
            return Fail(forest, Field(forest, item.node, "member"), document, "Invalid string or embedded NUL");
        }
        if (Single(object, PointerStorage)) {
            receiver := forest[Field(forest, item.node, "object")];
            return PointerPrefix([ExpressionCode(ops, receiver)], [],
                                 PointerContinue(PointerReadStep(types, object, 1, ops, target, at, receiver),
                                                 Resume(item.node, PointerMemberReadPhase, 0, 0)));
        }
        if (item.phase == PointerMemberReadPhase && ops.debug) {
            code.append(WatchCode(ops, object.slot, object.storage, object.container, object.record, 0, true,
                                  forest[Field(forest, item.node, "object")], target));
        }
        // A dereferenced pointer's member is its pointee's field, never the
        // name of the output that returned the pointer, as in stage zero.
        dereferenced := item.phase == PointerMemberReadPhase;
        source := ResultSourceCall(forest, text, names, Field(forest, item.node, "object"));
        called := ResultSourceCallable(forest, text, callables, natives, names, package, source);
        if (!dereferenced && called >= 0 && NamedResult(params, callables[called], member) == 0) {
            // A single named result is also an ordinary value. Its output
            // name projects that value before looking for a record field.
            named := params[callables[called].first + callables[called].count];
            projected := Typed(object.slot, named.storage, named.container, named.record);
            if (object.storage != named.storage) {
                slots = NumberSlots(object.storage, named.storage);
                code = NumberCode(ops, object.storage, named.storage, object.slot, at.slot, node);
                projected.slot = at.slot + length(slots) - 1;
            }
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, projected,
                                NoValue(), marks);
        }
        origin := FindNativeCall(native_calls, source.node);
        if (!dereferenced && origin >= 0 && FindResult(ports, natives[native_calls[origin].native], member) == 0) {
            // Naming the sole output projects the call's ordinary value.
            // A local can have widened it since the initializer was emitted.
            fact := native_calls[origin];
            projected := Typed(object.slot, fact.storage, fact.container, fact.record);
            if (!NativeTakes(types, projected, object)) {
                numeric := object.container == 0 && fact.container == 0 &&
                           object.record < 0 && fact.record < 0 &&
                           (Integer(object.storage) || Floating(object.storage)) &&
                           (Integer(fact.storage) || Floating(fact.storage));
                if (!numeric) {
                    return Fail(forest, item.node, document, "named result differs from its declared type");
                }
                slots = NumberSlots(object.storage, fact.storage);
                code = NumberCode(ops, object.storage, fact.storage, object.slot, at.slot, node);
                projected.slot = at.slot + length(slots) - 1;
            }
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, projected,
                                NoValue(), marks);
        }
        if (Single(object, ResultsStorage)) {
            // One of a native's results, read from its cell.
            called := natives[object.record];
            index := FindResult(ports, called, member);
            if (index == -2) {
                return Fail(forest, item.node, document, format_text("Ambiguous result '{}'", member));
            }
            if (index < 0) {
                return Fail(forest, item.node, document, format_text("Unknown result '{}'", member));
            }
            port := ports[called.first + called.parameters + index];
            slots.append(address);
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, object.slot + index, 0, 0,
                                    node));
            loaded: Slot = {storage: SlotStorage(port.storage, port.container, target),
                            kind: SlotKind(port.storage, port.container)};
            slots.append(loaded);
            read := Instruction(ops.load, loaded.storage, at.slot + 1, at.slot, 0, 0, node);
            read.offset = target.payload_offset;
            code.append(read);
            if (Pointer(port.storage, port.container)) {
                root: Root = {slot: at.slot + 1, storage: port.storage, container: port.container, record: port.record};
                roots.append(root);
            }
            emitted := CellSchemaStep(Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                                                   Typed(at.slot + 1, port.storage, port.container, port.record),
                                                   NoValue(), marks),
                                      object.slot + index, ops, target, at, node);
            return CleanupProjectionStep(emitted, object, natives, ports, ops, target, at, node);
        }
        if (Single(object, FunctionResultsStorage)) {
            // One of a function's named results, read from its cell.
            called := callables[object.record];
            index := NamedResult(params, called, member);
            if (index < 0) {
                return Fail(forest, item.node, document, format_text("Unknown result '{}'", member));
            }
            result := params[called.first + called.count + index];
            loaded: Slot = {storage: SlotStorage(result.storage, result.container, target),
                            kind: SlotKind(result.storage, result.container)};
            slots = [address, loaded];
            code = CellRead(loaded.storage, object.slot + index, ops, target, at.slot, node);
            if (Pointer(result.storage, result.container)) {
                root: Root = {slot: at.slot + 1, storage: result.storage, container: result.container,
                              record: result.record};
                roots.append(root);
            }
            return CellSchemaStep(Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1,
                                               Typed(at.slot + 1, result.storage, result.container, result.record),
                                               NoValue(), marks),
                                  object.slot + index, ops, target, at, node);
        }
        if (Single(object, HandleStorage) && OwnerHandle(types, names, object.record) &&
            Component(types, member) >= 0) {
            // A component of another entity, read as the owner's is.
            return ComponentReadStep([], types, Component(types, member), false, object.slot, [], ops, target, at,
                                     node);
        }
        if (Single(object, StructStorage) && MathKind(types, object.record) != 0) {
            return MathMemberStep(forest, document, types, members, object, member, ops, target, at, node);
        }
        found: int = -1;
        if (Single(object, StructStorage) ||
            (object.container == 0 && object.record >= 0 && types[object.record].kind == NativeDecl)) {
            found = FindField(types, members, object.record, member);
        }
        if (found < 0) {
            return Fail(forest, item.node, document, format_text("Unknown field '{}'", member));
        }
        field := members[found];
        read_effects := MemberEffects(types, object.record);
        if (field.read >= 0) {
            // A native reads the field, such as an input action's `pressed`.
            return EffectsStep(NativeReadStep(forest, document, item.node, types, natives, ports, object,
                                              field, ops, target, at), read_effects);
        }
        if (field.c_string) {
            return EffectsStep(NativeTextReadStep(object, field, ops, target, at, node), read_effects);
        }
        if (field.storage == StructStorage && field.record < 0) {
            return Fail(forest, item.node, document,
                        format_text("field '{}' has a type this compiler cannot read", member));
        }
        if (read_effects != 0) {
            next.append(RecordEffects(read_effects));
        }
        if (field.storage == StructStorage && field.container == 0) {
            // A native record's record field lies inside it.
            word: Slot = {storage: target.pointer_storage, kind: ValueKind};
            slots.append(word);
            offset := ConstantCode(ops, target.pointer_storage, u64(field.offset), at.slot, node);
            code.append(offset);
            slots.append(address);
            code.append(Instruction(ops.add, target.pointer_storage, at.slot + 1, object.slot, at.slot, -1,
                                    node));
            nested := Typed(at.slot + 1, StructStorage, 0, field.record);
            nested.schema = object.schema;
            emitted := Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 1, nested, NoValue(), marks);
            return CleanupProjectionStep(emitted, object, natives, ports, ops, target, at, node);
        }
        slot: Slot = {storage: SlotStorage(field.storage, field.container, target),
                      kind: SlotKind(field.storage, field.container)};
        slots.append(slot);
        read := Instruction(ops.load, slot.storage, at.slot, object.slot, 0, 0, node);
        read.offset = field.offset;
        code.append(read);
        produced = Typed(at.slot, field.storage, field.container, field.record);
    } else {
        popped = 2;
        array := values[top - 2];
        position := values[top - 1];
        if (IsMap(array)) {
            emitted := MapReadStep(forest, document, types, array, position, ops, target, at, item.node);
            return CleanupProjectionStep(emitted, array, natives, ports, ops, target, at, node);
        }
        if (array.container != ArrayContainer && array.container != ViewContainer) {
            return Fail(forest, Field(forest, item.node, "object"), document, "indexing needs an array");
        }
        if (!Single(position, IntStorage)) {
            return Fail(forest, Field(forest, item.node, "index"), document, "index needs an int");
        }
        element_type := SequenceElement(types, {storage: array.storage, container: array.container, record: array.record});
        read := SequenceGetIntrinsic;
        if (!array.owned && (BorrowsElement(forest, text, types, members, item.node, element_type) ||
                             LendsElement(forest, text, names, referenced, mutated, built, addressed, item.node))) {
            read = SequenceBorrowIntrinsic;
        }
        if (ReadsInPlace(array, element_type, read == SequenceBorrowIntrinsic)) {
            packable := Packable(array.storage, array.record, types, members);
            slots = ElementSlots(array.storage, packable, target);
            locals = ElementLocals(array.storage, packable, target);
            code = ElementRead(array.slot, position.slot, array.storage, packable, at.slot, at.pc, at.local, ops,
                               target, node);
            element := at.slot + length(slots) - 1;
            if (array.storage == StructStorage) {
                roots.append({slot: element, storage: StructStorage, container: 0, record: array.record});
            }
            emitted := Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped,
                                    Typed(element, array.storage, 0, array.record), NoValue(), marks);
            return CleanupProjectionStep(emitted, array, natives, ports, ops, target, at, node);
        }
        emitted := SequenceCallStep([array, position], read,
                                    Typed(-1, element_type.storage, element_type.container, element_type.record), u64(0), false,
                                    2, ops, target, at, node);
        return CleanupProjectionStep(emitted, array, natives, ports, ops, target, at, node);
    }
    emitted := Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, NoValue(), marks);
    if (produced.storage != 0 && popped > 0 && (kind == "member_expression" || kind == "index_expression")) {
        return CleanupProjectionStep(emitted, values[top - popped], natives, ports, ops, target, at, node);
    }
    return emitted;
}

// The count of the array in `array`'s slot, read in place. A debug build
// keeps the native call and its points.
ArrayLengthStep :: (array: Value, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    number: Slot = {storage: IntStorage, kind: ValueKind};
    count := Instruction(ops.load, IntStorage, at.slot, array.slot, 0, 0, node);
    count.offset = target.count_offset;
    code: Code[] = [Instruction(ops.guard, 0, 0, array.slot, 0, target.argument_failure, node), count];
    return Step.Emitted(code, [number], [], [], [], [], [], [], [], 1, Typed(at.slot, IntStorage, 0, -1), NoValue(),
                        []);
}
// Whether an element of `array` is loaded inline rather than by a host call:
// a number or bool, copied by the load, or a record read in place when it is
// `borrowed`. Views and nested collections go through the host.
ReadsInPlace :: (array: Value, element: ValueType, borrowed: bool) -> bool {
    if (array.container != ArrayContainer || array.place || element.container != 0 ||
        element.storage != array.storage || element.record != array.record) {
        return false;
    }
    if (element.storage == StructStorage) {
        return borrowed && element.record >= 0;
    }
    return element.storage >= BoolStorage && element.storage <= FloatStorage;
}
// Whether the element `node` reads is done with before its array can change,
// so it is read in place, as stage zero reads it: one of its scalar fields, or
// a text field compared at once with a name or a literal.
BorrowsElement :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                   node: int, element: ValueType) -> bool {
    member := forest[node].parent;
    if (!Is(forest, member, "member_expression") || Field(forest, member, "object") != node ||
        element.storage != StructStorage || element.container != 0 || element.record < 0) {
        return false;
    }
    found := FindField(types, members, element.record, Text(forest, text, Field(forest, member, "member")));
    if (found < 0 || members[found].container != 0 || members[found].read >= 0 || members[found].c_string) {
        return false;
    }
    storage := members[found].storage;
    if (storage != TextStorage) {
        return storage != StructStorage && storage != UnionStorage;
    }
    comparison := forest[member].parent;
    operator := Text(forest, text, Field(forest, comparison, "operator"));
    other := Field(forest, comparison, "right");
    if (other == member) {
        other = Field(forest, comparison, "left");
    }
    return Is(forest, comparison, "binary_expression") && (operator == "==" || operator == "!=") &&
           (Is(forest, other, "identifier") || Is(forest, other, "string"));
}
// Whether the element `node` reads initializes a local in place, as stage
// zero lends a declaration: nothing changes the local, nor the parameter or
// local whose array holds the element, so the element outlives every read of
// the local. A view's owner can still change the array under it.
LendsElement :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], referenced: string[],
                 mutated: string[], built: int[], addressed: string[], node: int) -> bool {
    declaration := forest[node].parent;
    if (!Is(forest, node, "index_expression") || !Is(forest, declaration, "local_declaration") ||
        Field(forest, declaration, "value") != node || built.contains(Field(forest, declaration, "name"))) {
        return false;
    }
    root := RootOf(forest, node);
    if (!Is(forest, root, "identifier")) {
        return false;
    }
    found := Lookup(names, Text(forest, text, root));
    return found >= 0 && (names[found].place == ParameterPlace || names[found].place == CellPlace) &&
           names[found].container != ViewContainer &&
           Fixed(referenced, mutated, addressed, Text(forest, text, Field(forest, declaration, "name"))) &&
           Fixed(referenced, mutated, addressed, names[found].name);
}
// Whether `node` reads an element of an array or map that something may
// change, that is not a name, or that a view's owner may change.
ChangingElement :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], referenced: string[],
                    mutated: string[], addressed: string[], node: int) -> bool {
    at := Unparenthesized(forest, node);
    if (!Is(forest, at, "index_expression")) {
        return false;
    }
    root := RootOf(forest, at);
    if (!Is(forest, root, "identifier")) {
        return true;
    }
    found := Lookup(names, Text(forest, text, root));
    return (found >= 0 && names[found].container == ViewContainer) ||
           !Fixed(referenced, mutated, addressed, Text(forest, text, root));
}
// Whether nothing assigns, changes in place or takes the address of `name`.
Fixed :: (referenced: string[], mutated: string[], addressed: string[], name: string) -> bool {
    return !Holds(referenced, name) && !Holds(mutated, name) && !Holds(addressed, name);
}
// The phase of an array literal whose element type its first item gives.
InferPhase: int : 2;
// Struct and array literals, built by the construct intrinsic: the value's
// header, then each array item, or each field as an offset cell and a value
// cell; it returns the new value.
LiteralStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, table: ^(TypeDecl[]),
                members: TypeMember[], values: Value[], top: int, built: int[], item: Work, ops: Ops, target: Target,
                at: Bases) -> Step {
    types := table^;
    node := forest[item.node];
    array := node.kind == "array_expression";
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    if (array && item.container != ArrayContainer) {
        // With no type expected, the first item's type is the element type,
        // as in stage zero, and the other items take it.
        if (item.storage != 0) {
            return Fail(forest, item.node, document, "Array literal needs an explicit array type");
        }
        first := FirstMember(forest, item.node);
        if (item.phase == 0) {
            if (first < 0) {
                return Fail(forest, item.node, document, "Empty arrays need an explicit element type");
            }
            next.append(Visit(first));
            next.append(Resume(first, CopyValuePhase, 0, 0));
            next.append(Resume(item.node, InferPhase, 0, 0));
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(),
                                marks);
        }
        element := values[top - 1];
        if (element.storage == NumberStorage) {
            return Fail(forest, first, document, "an untyped number needs a type; give the array an integer type");
        }
        if (element.storage <= 0) {
            return Fail(forest, first, document, "array item has no value type");
        }
        element_type: ValueType = {storage: element.storage, container: element.container, record: element.record};
        if (element.container != 0 || OptionalElement(types, element).storage != 0) {
            EnsureSequenceCollection(table, element_type, 0);
            types = table^;
        }
        array_type := SequenceArrayType(types, element_type);
        count: int = 1;
        member := NextMember(forest, first);
        while (member >= 0) {
            next.append(Expect(member, element.storage, element.container, element.record));
            next.append(Resume(member, CopyValuePhase, 0, 0));
            count += 1;
            member = NextMember(forest, member);
        }
        rest := Expect(item.node, array_type.storage, ArrayContainer, array_type.record);
        rest.phase = 1;
        rest.a = count;
        next.append(rest);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
    }
    if (!array && (item.storage != StructStorage || item.container != 0)) {
        return Fail(forest, item.node, document, "Struct literal needs an explicit record type");
    }
    record := item.record;
    if (item.phase == 0) {
        count: int = 0;
        member := FirstMember(forest, item.node);
        while (member >= 0) {
            if (array) {
                element := SequenceElement(types, {storage: item.storage, container: item.container, record: record});
                next.append(Expect(member, element.storage, element.container, element.record));
            } else {
                name := Text(forest, text, Field(forest, member, "name"));
                if (name == "") {
                    return Fail(forest, Field(forest, member, "name"), document, "Invalid string or embedded NUL");
                }
                if (FindField(types, members, record, name) < 0) {
                    return Fail(forest, member, document, format_text("Unknown field '{}'", name));
                }
                earlier := FirstMember(forest, item.node);
                while (earlier != member) {
                    if (Text(forest, text, Field(forest, earlier, "name")) == name) {
                        return Fail(forest, member, document, format_text("Duplicate literal member '{}'", name));
                    }
                    earlier = NextMember(forest, earlier);
                }
                field := members[FindField(types, members, record, name)];
                if (field.c_string) {
                    message := CStringMessage(forest, text, Field(forest, member, "value"), field.name);
                    if (message != "") {
                        return Fail(forest, Field(forest, member, "value"), document, message);
                    }
                }
                next.append(Expect(Field(forest, member, "value"), field.storage, field.container, field.record));
            }
            next.append(Resume(member, CopyValuePhase, 0, 0));
            count += 1;
            member = NextMember(forest, member);
        }
        if (!array && count != types[record].count) {
            field_index := types[record].first;
            while (field_index < types[record].first + types[record].count) {
                field := members[field_index];
                provided := false;
                for (given in Members(forest, item.node)) {
                    if (Text(forest, text, Field(forest, given, "name")) == field.name) {
                        provided = true;
                    }
                }
                if (!provided && (field.storage != PointerStorage || field.record < 0 || types[field.record].key == 0)) {
                    return Fail(forest, item.node, document, "Struct literal needs every field");
                }
                field_index += 1;
            }
        }
        rest := Expect(item.node, item.storage, item.container, record);
        rest.phase = 1;
        rest.a = count;
        next.append(rest);
        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
    }
    header: Cell = {storage: item.storage, container: item.container, record: record, constant: 0, variant: -1, kind: ValueKind};
    cells.append(header);
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    member := FirstMember(forest, item.node);
    index: int = 0;
    while (member >= 0) {
        value := values[top - item.a + index];
        if (array) {
            element := SequenceElement(types, {storage: item.storage, container: item.container, record: record});
            if (!Accepts(types, element.storage, element.container, element.record, value)) {
                return Fail(forest, member, document, "array item differs from the array's type");
            }

        }
        if (!array) {
            found := FindField(types, members, record, Text(forest, text, Field(forest, member, "name")));
            field := members[found];
            if (!Accepts(types, field.storage, field.container, field.record, value)) {
                return Fail(forest, member, document, "field value differs from its type");
            }
            // Each field's value is watched as the literal's input, numbered
            // by the field's place in the record.
            code.append(WatchCode(ops, value.slot, value.storage, value.container, value.record,
                                  found - types[record].first, false, forest[item.node], target));
            offset: Cell = {storage: WordStorage, container: 0, record: -1, constant: u64(field.offset), variant: -1,
                            kind: ValueKind};
            cells.append(offset);
        }
        content: Cell = {storage: value.storage, container: value.container, record: value.record, constant: 0, variant: -1, kind: ValueKind};
        cells.append(content);
        slots.append(address);
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                                at.cell + length(cells) - 1, 0, 0, forest[member]));
        write := Instruction(ops.write, SlotStorage(value.storage, value.container, target), 0, value.slot,
                             at.slot + length(slots) - 1, 0, forest[member]);
        write.offset = target.payload_offset;
        code.append(write);
        code.extend(SchemaWriteCode(value, at.slot + length(slots) - 1, ops, target, forest[member]));
        index += 1;
        member = NextMember(forest, member);
    }
    cells.append(header);
    // A literal the function returns, or one that starts a local it returns,
    // is built in the caller's storage.
    intrinsic := ConstructIntrinsic;
    if ((array && BuiltLiteral(forest, built, item.node)) || Returned(forest, item.node)) {
        intrinsic += InResult;
    }
    host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + length(cells) - 1,
                  result_count: 1, written: false};
    hosts.append(host);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    slots.append(address);
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + length(slots) - 1,
                            at.cell + length(cells) - 1, 0, 0, node));
    slots.append(address);
    made := at.slot + length(slots) - 1;
    load := Instruction(ops.load, target.pointer_storage, made, made - 1, 0, 0, node);
    load.offset = target.payload_offset;
    code.append(load);
    root: Root = {slot: made, storage: item.storage, container: item.container, record: record};
    roots.append(root);
    result := Typed(made, item.storage, item.container, record);
    result.cell = at.cell + length(cells) - 1;
    result.owned = true;
    emitted := CellSchemaStep(Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, item.a,
                                           result, NoValue(), marks),
                              at.cell + length(cells) - 1, ops, target, at, node);
    return CleanupSequenceValues(emitted, Held(types, members, slice(values, top - item.a, item.a)), ops, target, at,
                                 node);
}

// `node` without the parentheses around it.
Unparenthesized :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    at := node;
    while (Is(forest, at, "parenthesized_expression")) {
        at = Field(forest, at, "expression");
    }
    return at;
}
// A provable literal at an explicit foreign C-string boundary.
CStringMessage :: (forest: snapshot.SnapshotNode[], text: string, node: int, boundary: string) -> string {
    at := Unparenthesized(forest, node);
    if (Is(forest, at, "named_argument")) {
        at = Unparenthesized(forest, Field(forest, at, "value"));
    }
    if (!Is(forest, at, "string")) {
        return "";
    }
    decoded := compiler_json_value_string(Text(forest, text, at));
    if (!decoded.valid) {
        return "";
    }
    return CStringTextMessage(decoded.value, boundary);
}
CStringTextMessage :: (text: string, boundary: string) -> string {
    index: int = 0;
    while (index < strings.ByteLength(text)) {
        if (strings.ByteAt(text, index) == 0) {
            return format_text("C-string boundary '{}' cannot accept NUL at byte {}", boundary, index);
        }
        index += 1;
    }
    return "";
}
// Supplied expressions keep their source order. Their parameter positions
// determine only the cells assembled after every expression is evaluated.
NativeArgument :: struct {
    node: int;
    parameter: int;
}
NativeBinding :: union {
    Failed(node: int, message: string) | Bound(arguments: NativeArgument[], total: int)
}
NativeValues :: union {
    Failed(node: int, message: string)
    | Bound(code: Code[], slots: Slot[], arguments: Value[], owners: Work[])
}
NativeNameStorage: int : 12;
NativeSources :: (forest: snapshot.SnapshotNode[], call: int, method: bool) -> int[] {
    sources: int[] = [];
    if (method) {
        sources.append(Field(forest, Field(forest, call, "function"), "object"));
    }
    argument := FirstMember(forest, Field(forest, call, "arguments"));
    while (argument >= 0) {
        sources.append(argument);
        argument = NextMember(forest, argument);
    }
    return sources;
}
NativeParameter :: (ports: ResolvedPort[], called: ResolvedNative, name: string, supplied: int) -> int {
    found: int = -1;
    index: int = 0;
    while (index < called.parameters) {
        candidate := ports[called.first + index].name;
        if (candidate == name) {
            return index;
        }
        if (NameMatches(candidate, name)) {
            if (found == -1) {
                found = index;
            } else {
                found = -2;
            }
        }
        index += 1;
    }
    if (found != -1 || !called.variadic || called.parameters == 0) {
        return found;
    }
    // A variadic Value0 also accepts Value1, Value2, ... as stage zero does.
    end := strings.ByteLength(name);
    digits := end;
    while (digits > 0 && strings.ByteAt(name, digits - 1) >= 48 && strings.ByteAt(name, digits - 1) <= 57) {
        digits -= 1;
    }
    if (digits == end) {
        return -1;
    }
    ordinal: int = 0;
    at := digits;
    while (at < end) {
        digit := strings.ByteAt(name, at) - 48;
        if (ordinal > supplied / 10 || digit > supplied - ordinal * 10) {
            return -1;
        }
        ordinal = ordinal * 10 + digit;
        at += 1;
    }
    first := format_text("{}0", strings.Slice(name, 0, digits));
    if (!NameMatches(ports[called.first + called.parameters - 1].name, first)) {
        return -1;
    }
    return called.parameters - 1 + ordinal;
}
NativeProvided :: (arguments: NativeArgument[], parameter: int) -> int {
    index: int = 0;
    while (index < length(arguments)) {
        if (arguments[index].parameter == parameter) {
            return index;
        }
        index += 1;
    }
    return -1;
}
BindNative :: (forest: snapshot.SnapshotNode[], text: string, call: int, sources: int[],
               called: ResolvedNative, ports: ResolvedPort[]) -> NativeBinding {
    arguments: NativeArgument[] = [];
    total := called.parameters;
    if (called.variadic && total > 0) {
        total -= 1;
    }
    ordinal: int = 0;
    for (source in sources) {
        value := source;
        parameter := ordinal;
        if (Is(forest, source, "named_argument")) {
            if (Field(forest, source, "type") >= 0) {
                return NativeBinding.Failed(source, "typed native arguments are not supported yet");
            }
            name := Text(forest, text, Field(forest, source, "name"));
            parameter = NativeParameter(ports, called, name, length(sources));
            if (parameter < 0) {
                problem := format_text("Unknown argument '{}'", name);
                if (parameter == -2) {
                    problem = format_text("Ambiguous argument '{}'", name);
                }
                return NativeBinding.Failed(source, problem);
            }
            value = Field(forest, source, "value");
            if (value < 0) {
                value = Field(forest, source, "source");
            }
        }
        if (value < 0 || parameter < 0 ||
            (parameter >= called.parameters && (!called.variadic || called.parameters == 0))) {
            return NativeBinding.Failed(source, "Too many arguments");
        }
        if (NativeProvided(arguments, parameter) >= 0) {
            return NativeBinding.Failed(source, "Argument supplied more than once");
        }
        argument: NativeArgument = {node: value, parameter: parameter};
        arguments.append(argument);
        if (parameter >= total) {
            total = parameter + 1;
        }
        ordinal += 1;
    }
    if (called.variadic && called.parameters > 0 && total < called.parameters &&
        ports[called.first + called.parameters - 1].has_default) {
        total = called.parameters;
    }
    index: int = 0;
    while (index < total) {
        port := ports[NativePort(called, index)];
        if (NativeProvided(arguments, index) < 0 && !port.has_default) {
            return NativeBinding.Failed(call, format_text("Missing argument '{}'", port.name));
        }
        index += 1;
    }
    return NativeBinding.Bound(arguments, total);
}
// Numeric overload arguments retain their inferred literal type and watch;
// selection converts the value afterward. Other literals are contextual only
// when every viable overload declares the same type at their source position.
NativeExpectation :: (forest: snapshot.SnapshotNode[], text: string, call: int, sources: int[],
                      natives: ResolvedNative[], ports: ResolvedPort[], name: string, ordinal: int) -> Work {
    source := sources[ordinal];
    if (Is(forest, source, "named_argument")) {
        source = Field(forest, source, "value");
        if (source < 0) {
            source = Field(forest, sources[ordinal], "source");
        }
    }
    expected := Visit(source);
    first := true;
    exact := ExactNativeKind(natives, name, NativeFunctionKind) >= 0;
    for (candidate in natives) {
        if (NativeCandidate(candidate, name, NativeFunctionKind, exact)) {
            switch BindNative(forest, text, call, sources, candidate, ports) {
                case .Failed(problem, message):
                    continue;
                case .Bound(arguments, total):
                    port := ports[NativePort(candidate, arguments[ordinal].parameter)];
                    if (first) {
                        expected = Expect(source, port.storage, port.container, port.record);
                        first = false;
                    } else if (expected.storage != port.storage || expected.container != port.container ||
                               expected.record != port.record) {
                        return Visit(source);
                    }
            }
        }
    }
    if (expected.storage <= 0 || Numeric(expected.storage)) {
        return Visit(source);
    }
    return expected;
}
// Only constant syntax is inspected. A local whose runtime value happens to
// be zero remains an explicit entity argument.
NativeOwnerZero :: (forest: snapshot.SnapshotNode[], text: string, document: int, constants: ConstDecl[],
                    callables: Callable[], names: Name[], package: int, node: int) -> bool {
    at := Unparenthesized(forest, node);
    remaining := length(forest);
    while (at >= 0 && remaining > 0 && Is(forest, at, "call_expression")) {
        callee := Field(forest, at, "function");
        spelling := Text(forest, text, callee);
        converted := ScalarStorage(spelling);
        if (!Is(forest, callee, "identifier") || FindCallable(callables, package, spelling) >= 0 ||
            Lookup(names, spelling) >= 0 || !Integer(converted)) {
            return false;
        }
        argument := FirstMember(forest, Field(forest, at, "arguments"));
        if (argument < 0 || NextMember(forest, argument) >= 0) {
            return false;
        }
        if (Is(forest, argument, "named_argument")) {
            label := Text(forest, text, Field(forest, argument, "name"));
            if (label != "wrap" && label != "clamp") {
                return false;
            }
            argument = Field(forest, argument, "value");
        }
        at = Unparenthesized(forest, argument);
        remaining -= 1;
    }
    if (Is(forest, at, "nil")) {
        return Text(forest, text, at) == "null";
    }
    numeric := Is(forest, at, "number");
    if (Is(forest, at, "unary_expression")) {
        operator := Text(forest, text, Field(forest, at, "operator"));
        numeric = (operator == "+" || operator == "-") && Is(forest, Field(forest, at, "operand"), "number");
    }
    if (numeric) {
        switch NumberBits(forest, text, at) {
            case .Finite(bits, fits, single):
                return (bits & 0x7fffffffffffffff) == 0;
            case .OutOfRange:
                return false;
        }
    }
    switch FoldConstant(forest, text, document, constants, names, package, at, Int64Storage) {
        case .Folded(bits):
            return bits == 0;
        case .Failed(diagnostic):
            return false;
        case .Waiting:
            return false;
    }
}
NativeOwner :: (types: TypeDecl[], names: Name[], port: ResolvedPort) -> Value {
    owner := Lookup(names, "self");
    if (port.storage != HandleStorage || port.container != 0 || port.record < 0 || owner < 0 ||
        names[owner].place != SelfPlace || names[owner].record < 0) {
        return NoValue();
    }
    value := Typed(-1, names[owner].storage, names[owner].container, names[owner].record);
    if (!NativeTakes(types, NativePortType(port), value)) {
        return NoValue();
    }
    return NativePortType(port);
}
// Reorder evaluated values, then emit omitted values in parameter order.
NativeBoundValues :: (forest: snapshot.SnapshotNode[], text: string, document: int, call: int,
                      constants: ConstDecl[], callables: Callable[], types: TypeDecl[], names: Name[], package: int,
                      called: ResolvedNative, ports: ResolvedPort[], supplied: NativeArgument[], total: int,
                      values: Value[], first: int, ops: Ops, at: Bases) -> NativeValues {
    code: Code[] = [];
    slots: Slot[] = [];
    arguments: Value[] = [];
    sources: int[] = [];
    owners: Work[] = [];
    index: int = 0;
    while (index < total) {
        given := NativeProvided(supplied, index);
        argument := NoValue();
        source: int = -1;
        if (given >= 0) {
            argument = values[first + given];
            source = supplied[given].node;
        }
        arguments.append(argument);
        sources.append(source);
        index += 1;
    }
    // Provided literal retyping and owner substitution follow source order.
    for (given in supplied) {
        port := ports[NativePort(called, given.parameter)];
        argument := arguments[given.parameter];
        if (argument.storage == NumberStorage && port.storage <= 0) {
            return NativeValues.Failed(argument.record, "a number needs an integer type here");
        }
        if (argument.storage == NumberStorage && port.storage > 0 && port.container == 0) {
            if (port.storage == HandleStorage) {
                if (!NativeOwnerZero(forest, text, document, constants, callables, names, package, given.node)) {
                    return NativeValues.Failed(given.node, "entity value requires null or zero");
                }
                argument = NativePortType(port);
                argument.slot = at.slot + length(slots);
                slots.append(ValueLocal(HandleStorage));
                constant := ConstantCode(ops, HandleStorage, 0, argument.slot, forest[given.node]);
                constant.value_record = port.record;
                code.append(constant);
                watch := ScalarWatch(ops, argument.slot, HandleStorage, 0, true, forest[given.node]);
                watch.value_record = port.record;
                owner := Lookup(names, "self");
                if (port.default_owner && owner >= 0) {
                    watch.value_record = names[owner].record;
                }
                code.append(watch);
            } else {
                if (!Integer(port.storage) && !Floating(port.storage)) {
                    return NativeValues.Failed(given.node, "argument differs from its parameter type");
                }
                shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots), local: at.local,
                                  cell: at.cell, host: at.host, call: at.call};
                // Stage zero types an untyped literal at the parameter's type.
                switch NumberLiteralStep(forest, text, document, constants, names, package, argument, port.storage,
                                         ops, shifted, forest[given.node]) {
                    case .Failed(diagnostic):
                        return NativeValues.Failed(given.node, diagnostic.message);
                    case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                  added_calls, added_names, next, popped, value, retained, marks):
                        code.extend(added_code);
                        slots.extend(added_slots);
                        argument = value;
                }
            }
        }
        if (port.default_owner && argument.storage == HandleStorage && argument.container == 0 &&
            NativeTakes(types, NativePortType(port), argument) &&
            NativeOwnerZero(forest, text, document, constants, callables, names, package, given.node)) {
            owner := NativeOwner(types, names, port);
            if (owner.storage == 0) {
                return NativeValues.Failed(given.node, "native owner argument requires a compatible self");
            }
            owner.slot = argument.slot;
            declared_owner := names[Lookup(names, "self")];
            owners.append(RecordOwnerArgument(given.node, argument.slot, declared_owner.record));
            code.append(SymbolCode(ops, declared_owner.node, forest[given.node]));
            argument = owner;
        }
        arguments[given.parameter] = argument;
    }
    index = 0;
    while (index < total) {
        port := ports[NativePort(called, index)];
        source := sources[index];
        if (source >= 0) {
            if (port.c_string) {
                message := CStringMessage(forest, text, source, port.name);
                if (message != "") {
                    return NativeValues.Failed(source, message);
                }
            }
        } else {
            site := Field(forest, call, "arguments");
            if (!port.has_default || !port.default_supported || port.storage <= 0 || port.container != 0 ||
                port.storage == StructStorage || port.storage == UnionStorage) {
                return NativeValues.Failed(call, format_text("default argument '{}' is not supported yet", port.name));
            }
            if (port.c_string) {
                message := CStringTextMessage(port.default_text, port.name);
                if (message != "") {
                    return NativeValues.Failed(call, message);
                }
            }
            value := NativePortType(port);
            value.slot = at.slot + length(slots);
            slots.append(ValueLocal(port.storage));
            code.append(ExpressionCode(ops, forest[site]));
            constant := ConstantCode(ops, port.storage, port.default_bits, value.slot, forest[site]);
            constant.value_record = port.record;
            constant.text = port.default_text;
            constant.has_text = port.storage == TextStorage || port.storage == NativeNameStorage;
            if (port.default_owner) {
                owner := NativeOwner(types, names, port);
                if (owner.storage == 0) {
                    return NativeValues.Failed(call, "native owner default requires a compatible self");
                }
                code.append(SymbolCode(ops, names[Lookup(names, "self")].node, forest[site]));
                constant = Instruction(ops.owner, HandleStorage, value.slot, 0, 0, 0, forest[site]);
            }
            code.append(constant);
            watch := DefaultWatch(ops, value.slot, port.storage, u64(0), forest[site]);
            watch.value_record = port.record;
            if (port.default_owner) {
                watch.value_record = names[Lookup(names, "self")].record;
            }
            code.append(watch);
            arguments[index] = value;
        }
        index += 1;
    }
    return NativeValues.Bound(code, slots, arguments, owners);
}
NativeCallPrefix :: (code: Code[], slots: Slot[], before: Work[], step: Step, popped: int) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next, count, value,
                      retained, marks):
            return Step.Emitted(extend(code, added_code), extend(slots, added_slots), locals, cells, hosts,
                                roots, calls, bound, extend(before, next), popped, value, retained, marks);
    }
}
// Calls of the package's functions and of natives. Arguments go to fresh data
// cells and the result comes back in one. A native's inferred ports all take
// the one type its arguments give them.
CallStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
             params: Param[], table: ^(TypeDecl[]), members: TypeMember[], constants: ConstDecl[], natives: ResolvedNative[], ports: ResolvedPort[],
             makes: NativeMake[], make_fields: int[], names: Name[], package: int, values: Value[], top: int,
             built: int[], item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    types := table^;
    node := forest[item.node];
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    if (item.phase == 1 && item.c == MathCall) {
        return MathConstructStep(forest, text, document, types, members, constants, names, package,
                                 slice(values, top - item.b, item.b), item.a, item.b, ops, target, at, node);
    }
    if (item.phase == 1 && item.c == MathFunctionCall) {
        name := Text(forest, text, Field(forest, item.node, "function"));
        return MathFunctionStep(forest, text, document, types, members, constants, names, package,
                                name, slice(values, top - item.b, item.b), item.b, ops, target, at, node);
    }
    if (item.phase == 0) {
        callee := Field(forest, item.node, "function");
        hidden := PrivateAccess(forest, text, callables, types, constants, names, package, callee);
        if (hidden >= 0) {
            return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
        }
        sum_type: int = -1;
        if (Is(forest, callee, "member_expression")) {
            sum_type = UnionOf(forest, text, types, names, package, callee);
        }
        if (sum_type >= 0) {
            // A variant with a payload: each argument is a payload field, in order.
            member := Text(forest, text, Field(forest, callee, "member"));
            variant := FindVariant(types, sum_type, member);
            if (variant < 0) {
                return Fail(forest, callee, document, format_text("Unknown variant '{}'", member));
            }
            count: int = 0;
            argument := FirstMember(forest, Field(forest, item.node, "arguments"));
            while (argument >= 0) {
                if (Is(forest, argument, "named_argument")) {
                    return Fail(forest, argument, document, "named payload arguments are not supported yet");
                }
                if (count >= types[variant].count) {
                    break;
                }
                field := members[types[variant].first + count];
                next.append(Expect(argument, field.storage, field.container, field.record));
                next.append(Resume(argument, CopyValuePhase, 0, 0));
                count += 1;
                argument = NextMember(forest, argument);
            }
            if (argument >= 0 || count != types[variant].count) {
                return Fail(forest, item.node, document, "variant payload needs one value per field");
            }
            finish := Resume(item.node, 1, variant, count);
            finish.c = 2;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
        // An unbound prefix names a native namespace. An import alias or a
        // local receiver keeps its package or array-method meaning.
        qualified_native: bool = false;
        native_name: string = "";
        if (Is(forest, callee, "member_expression")) {
            prefix := Field(forest, callee, "object");
            if (Is(forest, prefix, "identifier") && Lookup(names, Text(forest, text, prefix)) < 0 &&
                QualifierOf(forest, text, names, package, prefix) < 0) {
                qualified_native = true;
                native_name = format_text("{}.{}", Text(forest, text, prefix),
                                          Text(forest, text, Field(forest, callee, "member")));
            }
        }
        // `xs.f(...)` calls the array function f with xs first. A method that
        // changes its array is a statement on the array's name.
        method: int = -1;
        if (!qualified_native && Is(forest, callee, "member_expression") &&
            QualifierOf(forest, text, names, package, Field(forest, callee, "object")) < 0) {
            method = ArrayMethod(natives, ports, Text(forest, text, Field(forest, callee, "member")));
        }
        if (method >= 0) {
            if (ArrayChanger(natives, method) &&
                ChangedArray(forest, text, names, natives, ports, forest[item.node].parent) < 0) {
                return Fail(forest, callee, document,
                            format_text("{} changes the array; call it as a statement on a name",
                                        Text(forest, text, Field(forest, callee, "member"))));
            }
            if (!natives[method].direct) {
                return Fail(forest, callee, document, "native binding cannot be called directly as data");
            }
            if (!Supported(ports, natives[method])) {
                return Fail(forest, callee, document,
                            format_text("native '{}' is not supported yet", natives[method].name));
            }
            sources := NativeSources(forest, item.node, true);
            switch BindNative(forest, text, item.node, sources, natives[method], ports) {
                case .Failed(problem, message):
                    return Fail(forest, problem, document, message);
                case .Bound(arguments, total):
                    for (argument in arguments) {
                        port := ports[NativePort(natives[method], argument.parameter)];
                        expected := Visit(argument.node);
                        if (port.storage > 0) {
                            expected = Expect(argument.node, port.storage, port.container, port.record);
                        }
                        next.append(expected);
                        next.extend(NativeArgumentWork(forest, text, names, item.node, argument.node));
                    }
            }
            finish := Resume(item.node, 1, method, length(sources));
            finish.c = 7;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
        // `F(...)` calls this package's F or a native; a bound alias calls an
        // imported package's F; an unbound prefix qualifies a native's name.
        qualifier: int = -1;
        if (Is(forest, callee, "member_expression")) {
            qualifier = Field(forest, callee, "object");
            callee = Field(forest, callee, "member");
        }
        home := QualifierOf(forest, text, names, package, qualifier);
        if ((!qualified_native && home < 0) || !Is(forest, callee, "identifier")) {
            return Fail(forest, Field(forest, item.node, "function"), document, "call needs a function name");
        }
        callee_name := Text(forest, text, callee);
        found := CalledFunction(forest, text, callables, natives, names, package, item.node);
        if (qualified_native) {
            callee_name = native_name;
        }
        math_kind := MathName(callee_name);
        if (qualifier < 0 && found == -1 && math_kind != 0) {
            count: int = 0;
            for (argument in Members(forest, Field(forest, item.node, "arguments"))) {
                if (Is(forest, argument, "named_argument") || Is(forest, argument, "typed_argument") ||
                    Is(forest, argument, "reference_argument")) {
                    return Fail(forest, argument, document, "built-in math constructors take positional arguments");
                }
                next.extend([Visit(argument), Resume(argument, MathCapturePhase, 0, 0)]);
                count += 1;
            }
            finish := Resume(item.node, 1, MathRecord(types, math_kind), count);
            finish.c = MathCall;
            next.append(finish);
            return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
