// An instruction that names a command node. One literal holds the u64:
// storing it into a local record's field would make every caller copy its
// arguments, as ConstantCode notes.
CommandCode :: (op: int, target: int, command_node: u64, node: snapshot.SnapshotNode) -> Code {
    return {op: op, type: 0, output: 0, left: 0, right: 0, target: target, offset: 0, value_storage: 0,
            value_container: 0, value_record: -1, payload: command_node, text: "", has_text: false, message: "",
            has_message: false, start: node.start, end: node.end, line: node.row + 1, column: node.column + 1};
