    index: Cell = {storage: IntStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    whole: Cell = {storage: BoolStorage, container: 0, record: -1, constant: 0, variant: -1, kind: ValueKind};
    result: Cell = {storage: element.storage, container: element.container, record: element.record,
                    constant: 0, variant: -1, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    payload: Slot = {storage: SlotStorage(element.storage, element.container, target),
                     kind: SlotKind(element.storage, element.container)};
    slots: Slot[] = [address, address, payload];
    code: Code[] = [Instruction(ops.host_slot, target.pointer_storage, at.slot, at.cell, 0, 0, node)];
    put := Instruction(ops.write, UnionStorage, 0, value.slot, at.slot, 0, node);
    put.offset = target.payload_offset;
    code.append(put);
    host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: UnionGetIntrinsic, linked: -1, first: at.cell,
                  result_first: at.cell + 4, result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + 1, at.cell + 4, 0, 0, node));
    take := Instruction(ops.load, payload.storage, at.slot + 2, at.slot + 1, 0, 0, node);
    take.offset = target.payload_offset;
    code.append(take);
    roots: Root[] = [];
    if (Pointer(element.storage, element.container)) {
        root: Root = {slot: at.slot + 2, storage: element.storage,
                      container: element.container, record: element.record};
        roots.append(root);
    }
    return Step.Emitted(code, slots, [], [held, tag, index, whole, result], [host], roots, [], [], [], popped,
                        Typed(at.slot + 2, element.storage, element.container, element.record), NoValue(), []);
}
// The place of the payload of the present optional at `place`, which holds
// `element`.
PayloadPlaceStep :: (types: TypeDecl[], place: Value, element: ValueType, ops: Ops, target: Target, at: Bases,
                     node: snapshot.SnapshotNode) -> Step {
    tag := TypedCell(WordStorage, 0, -1);
    tag.constant = OptionalTag(types, element);
    cells: Cell[] = [ReferenceCell(target), tag, TypedCell(IntStorage, 0, -1),
                     TypedCell(element.storage, element.container, element.record), ReferenceCell(target)];
    code := CellWrite(target.pointer_storage, place.slot, at.cell, ops, target, at.slot, node);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(target.pointer_storage, at.cell + 4, ops, target, at.slot + 1, node));
    hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: ReferenceUnionIntrinsic, linked: -1, first: at.cell,
                      result_first: at.cell + 4, result_count: 1, written: false}];
    result := Typed(at.slot + 2, element.storage, element.container, element.record);
    result.place = true;
    return Step.Emitted(code, [AddressSlot(target), AddressSlot(target), DescriptorSlot(target)], [], cells, hosts,
                        [], [], [], [], 0, result, NoValue(), []);
}
NarrowedPlace: int : 17;
NarrowedOriginalPhase: int : 50;
NarrowedReadPhase: int : 51;
// The place of the payload of the optional place `step` gives.
PayloadPlaceAfter :: (types: TypeDecl[], step: Step, element: ValueType, ops: Ops, target: Target, at: Bases,
                      node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, place, retained, marks):
            shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots), local: at.local + length(locals),
                              cell: at.cell + length(cells), host: at.host + length(hosts), call: at.call + length(calls)};
            return SequenceJoined(Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped,
                                               NoValue(), retained, marks),
                                  PayloadPlaceStep(types, place, element, ops, target, shifted, node));
    }
}
// The successful path of `if name` / `while name` shadows the optional with
// its payload. The body's scope removes that proof before the next iteration
// or the alternative branch; the declaration outside that scope stays optional.
// As stage zero unwraps it, each use reads the optional, through the shadow's
// `index` naming it, and takes the payload, or its place, from it.
OptionalConditionNames :: (types: TypeDecl[], names: Name[], forest: snapshot.SnapshotNode[], text: string,
                           condition: int, value: Value) -> Name[] {
    subject := condition;
    while (Is(forest, subject, "parenthesized_expression")) {
        subject = Field(forest, subject, "expression");
    }
    element := OptionalElement(types, value);
    found: int = -1;
    if (Is(forest, subject, "identifier")) {
        found = Lookup(names, Text(forest, text, subject));
    }
    if (element.storage == 0 || found < 0) {
        return [];
    }
    original := names[found];
    binding: Name = {owned: false, name: original.name, place: NarrowedPlace, index: found, storage: element.storage,
                     container: element.container, record: element.record, writable: original.writable,
                     node: original.node};
    return [binding];
}
package package_compiler

import snapshot "project:source_snapshot"

SequenceSliceIntrinsic: int : 51;
SequenceViewIntrinsic: int : 52;
SequenceCloneIntrinsic: int : 53;
ArrayMutateIntrinsic: int : 54;
SequenceGetIntrinsic: int : 55;
SequenceLengthIntrinsic: int : 56;
SequenceBorrowIntrinsic: int : 62;

// Ranges occur only as an index or a sequence method's argument. They never
// become runtime values. Existing slice(start, count) calls stay native calls.
SequenceOperation :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], package: int, node: int) -> int {
    if (Is(forest, node, "index_expression") && Is(forest, Field(forest, node, "index"), "range_expression")) {
        return 0;
    }
    if (!Is(forest, node, "call_expression")) {
        return -1;
    }
    callee := Field(forest, node, "function");
    if (!Is(forest, callee, "member_expression") ||
        QualifierOf(forest, text, names, package, Field(forest, callee, "object")) >= 0) {
        return -1;
    }
    receiver := Field(forest, callee, "object");
    if (Is(forest, receiver, "identifier") && Lookup(names, Text(forest, text, receiver)) < 0) {
        return -1;
    }
    member := Text(forest, text, Field(forest, callee, "member"));
    argument := FirstMember(forest, Field(forest, node, "arguments"));
    if (member == "clone" && argument < 0) {
        return 2;
    }
    if (member == "length" && argument < 0) {
        return 3;
    }
    if (member == "view") {
        return 1;
    }
    if (member == "slice" && Is(forest, argument, "range_expression")) {
        return 0;
    }
    return -1;
}

// Emits one intrinsic call with typed cells. A literal tag, when present,
// follows the evaluated arguments. No argument is copied implicitly.
SequenceCallStep :: (arguments: Value[], intrinsic: int, result: Value, tag: u64, tagged: bool,
                     popped: int, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    cells: Cell[] = [];
    roots: Root[] = [];
    index: int = 0;
    for (argument in arguments) {
        cell := MovedCell(argument);
        written := SlotStorage(argument.storage, argument.container, target);
        if (argument.place || argument.storage == ReferenceStorage) {
            cell = ReferenceCell(target);
            written = target.pointer_storage;
        }
        cells.append(cell);
        slots.append(AddressSlot(target));
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + index, at.cell + index, 0, 0, node));
        write := Instruction(ops.write, written, 0,
                             argument.slot, at.slot + index, 0, node);
        write.offset = target.payload_offset;
        code.append(write);
        if (!argument.place) {
            code.extend(SchemaWriteCode(argument, at.slot + index, ops, target, node));
        }
        index += 1;
    }
    if (tagged) {
        cells.append({storage: WordStorage, container: 0, record: -1, constant: tag, variant: -1, kind: ValueKind});
    }
    output := at.cell + length(cells);
    cells.append(MovedCell(result));
    hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: output,
                      result_count: 1, written: false}];
    // An index outside the sequence is an argument failure, as stage zero
    // reports it.
    failure := target.data_failure;
    if (intrinsic == SequenceGetIntrinsic || intrinsic == SequenceBorrowIntrinsic) {
        failure = target.argument_failure;
    }
    code.append(Instruction(ops.host_call, 0, 0, failure, 0, at.host, node));
    slots.append(AddressSlot(target));
    address := at.slot + length(slots) - 1;
    code.append(Instruction(ops.host_slot, target.pointer_storage, address, output, 0, 0, node));
    slots.append({storage: SlotStorage(result.storage, result.container, target),
                  kind: SlotKind(result.storage, result.container)});
    result.slot = at.slot + length(slots) - 1;
    read := Instruction(ops.load, SlotStorage(result.storage, result.container, target), result.slot, address, 0, 0, node);
    read.offset = target.payload_offset;
    code.append(read);
    if (Pointer(result.storage, result.container)) {
        roots.append({slot: result.slot, storage: result.storage, container: result.container, record: result.record});
    }
    result.cell = output;
    result.owned = intrinsic == ValueCopyIntrinsic || intrinsic == SequenceSliceIntrinsic ||
                   intrinsic == SequenceCloneIntrinsic || intrinsic == SequenceViewIntrinsic;
    return CellSchemaStep(Step.Emitted(code, slots, [], cells, hosts, roots, [], [], [], popped, result, NoValue(), []),
                          output, ops, target, at, node);
}

SequenceStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, table: ^(TypeDecl[]),
                 values: Value[], top: int, item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    types := table^;
    node := forest[item.node];
    index := node.kind == "index_expression";
    receiver := Field(forest, item.node, "object");
    range := Field(forest, item.node, "index");
    operation: int = 0;
    if (!index) {
        callee := Field(forest, item.node, "function");
        receiver = Field(forest, callee, "object");
        range = FirstMember(forest, Field(forest, item.node, "arguments"));
        member := Text(forest, text, Field(forest, callee, "member"));
        if (member == "view") {
            operation = 1;
        } else if (member == "clone") {
            operation = 2;
        } else if (member == "length") {
            operation = 3;
        }
    }
    count: int = 1;
    ranged := operation == 0 || operation == 1;
    if (ranged) {
        count = 3;
        if (!Is(forest, range, "range_expression") || (!index && NextMember(forest, range) >= 0)) {
            return Fail(forest, item.node, document, "sequence slice or view needs one half-open range");
        }
    }
    if (item.phase == 0) {
        next: Work[] = [Visit(receiver)];
        if (ranged) {
            next.append(Expect(Field(forest, range, "start"), IntStorage, 0, -1));
            next.append(Expect(Field(forest, range, "end"), IntStorage, 0, -1));
        }
        next.append(Resume(item.node, 1, 0, 0));
        return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
    }
    object := values[top - count];
    element: ValueType = {storage: object.storage, container: object.container, record: object.record};
    if (operation == 1 && Single(object, PointerStorage)) {
        element = PointerElement(types, object);
        if (element.container != ArrayContainer || types[object.record].key != 0) {
            return Fail(forest, receiver, document, "mutable view needs a present pointer to an array");
        }
    } else if (operation == 1 && !Single(object, TextStorage)) {
        return Fail(forest, receiver, document, "mutable view needs a pointer to an array");
    } else if (object.container != ArrayContainer && object.container != ViewContainer && !Single(object, TextStorage)) {
        return Fail(forest, receiver, document, "slice, view and clone need a string or array");
    }
    if (operation == 3) {
        emitted := SequenceCallStep([object], SequenceLengthIntrinsic, Typed(-1, IntStorage, 0, -1),
                                    u64(0), false, 1, ops, target, at, node);
        return CleanupSequenceValues(emitted, [object], ops, target, at, node);
    }
    if (element.container != 0) {
        element.container = ArrayContainer;
        if (operation == 1) {
            element.container = ViewContainer;
        }
    }
    result := Typed(-1, element.storage, element.container, element.record);
    intrinsic := SequenceCloneIntrinsic;
    if (ranged) {
        if (!Single(values[top - 2], IntStorage) || !Single(values[top - 1], IntStorage)) {
            return Fail(forest, range, document, "range bounds need int values");
        }
        optional := EnsureOptional(table, element, 0);
        types = table^;
        result = Typed(-1, UnionStorage, 0, optional);
        intrinsic = SequenceSliceIntrinsic;
        if (operation == 1) {
            intrinsic = SequenceViewIntrinsic;
        }
    }
    arguments := slice(values, top - count, count);
    emitted := SequenceCallStep(arguments, intrinsic, result, OptionalTag(types, element),
                                ranged, count, ops, target, at, node);
    return CleanupSequenceValues(emitted, arguments, ops, target, at, node);
}

ArrayMutation :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], natives: ResolvedNative[],
                  ports: ResolvedPort[], package: int, node: int) -> int {
    // A method that changes its array is a statement of its own; the call
    // step rejects one used as a value.
    if (!Is(forest, node, "call_expression") || !Is(forest, forest[node].parent, "expression_statement")) {
        return 0;
    }
    callee := Field(forest, node, "function");
    if (!Is(forest, callee, "member_expression") ||
        QualifierOf(forest, text, names, package, Field(forest, callee, "object")) >= 0) {
        return 0;
    }
    receiver := Field(forest, callee, "object");
    if (Is(forest, receiver, "identifier") && Lookup(names, Text(forest, text, receiver)) < 0) {
        return 0;
    }
    method := Text(forest, text, Field(forest, callee, "member"));
    native := ArrayMethod(natives, ports, method);
    if (native < 0 || !ArrayChanger(natives, native)) {
        return 0;
    }
    changers: string[] = ["append", "add_unique", "extend", "set_array_elem", "insert", "remove_index",
                          "remove_item", "clear", "reverse", "swap", "resize"];
    operation: int = 1;
    for (changer in changers) {
        if (NameMatches(method, changer)) {
            return operation;
        }
        operation += 1;
    }
    return 0;
}

MutationStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], members: TypeMember[],
                 natives: ResolvedNative[], ports: ResolvedPort[], names: Name[], values: Value[], top: int,
                 item: Work, operation: int, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    receiver := Field(forest, Field(forest, item.node, "function"), "object");
    first := FirstMember(forest, Field(forest, item.node, "arguments"));
    if (item.phase == 0) {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [PlaceVisit(receiver), Resume(item.node, 1, 0, 0)], 0, NoValue(), NoValue(), []);
    }
    if (item.phase == 1) {
        object := values[top - 1];
        if (object.place && Single(object, PointerStorage)) {
            return PointerContinue(ReadSequencePlace(object, 1, ops, target, at, node),
                                   Resume(item.node, PlacePointerPhase, 1, 0));
        }
        if (object.container != ArrayContainer && object.container != ViewContainer) {
            return Fail(forest, receiver, document, "mutating method needs an array or view");
        }
        if (object.container == ViewContainer && operation != 4 && operation != 9 && operation != 10) {
            return Fail(forest, item.node, document, "a view has fixed length");
        }
        next: Work[] = [];
        argument := first;
        count: int = 0;
        element := SequenceElement(types, {storage: object.storage, container: object.container, record: object.record});
        if (operation == 11 && NeedsPointerValue(types, members, element.storage, element.container, element.record)) {
            return Fail(forest, item.node, document, "resize cannot create missing initialized values");
        }
        native := ArrayMethod(natives, ports, Text(forest, text, Field(forest, Field(forest, item.node, "function"),
                                                                       "member")));
        while (argument >= 0) {
            // A named argument binds as stage zero binds it; this step takes
            // the arguments in parameter order.
            value := argument;
            if (Is(forest, argument, "named_argument")) {
                value = Field(forest, argument, "value");
                if (value < 0) {
                    value = Field(forest, argument, "source");
                }
                parameter := NativeParameter(ports, natives[native], Text(forest, text, Field(forest, argument, "name")),
                                             count + 2);
                if (parameter != count + 1) {
                    return Fail(forest, argument, document, "name an array update's arguments in parameter order");
                }
            }
            storage := element.storage;
            container := element.container;
            record := element.record;
            if (operation == 3) {
                storage = object.storage;
                container = ArrayContainer;
                record = object.record;
            } else if (operation == 6 || operation == 10 || operation == 11 ||
                       ((operation == 4 || operation == 5) && count == 0)) {
                storage = IntStorage;
                container = 0;
                record = -1;
            }
            next.append(Expect(value, storage, container, record));
            next.append(Resume(value, CopyValuePhase, 0, 0));
            count += 1;
            argument = NextMember(forest, argument);
        }
        expected: int = 1;
        if (operation == 4 || operation == 5 || operation == 10) {
            expected = 2;
        } else if (operation == 8 || operation == 9) {
            expected = 0;
        }
        if (count != expected) {
            return Fail(forest, item.node, document, "mutating method has the wrong number of arguments");
        }
        next.append(Resume(item.node, 2, count, 0));
        // Stage zero watches a named array, not a pointer it follows, where
        // it evaluates it, before the arguments, which can invoke another body.
        found: int = -1;
        if (Is(forest, receiver, "identifier")) {
            found = Lookup(names, Text(forest, text, receiver));
        }
        if (!ops.debug || found < 0 || (names[found].storage == PointerStorage && names[found].container == 0)) {
            return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
        }
        switch ReadSequencePlace(object, 0, ops, target, at, node) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, scheduled, popped, value, retained,
                          marks):
                watches: Code[] = [WatchCode(ops, value.slot, value.storage, value.container, value.record, 0, true,
                                             forest[receiver], target),
                                   WatchCode(ops, value.slot, value.storage, value.container, value.record, 0, false,
                                             node, target)];
                return Step.Emitted(extend(code, watches), slots, locals, cells, hosts, roots, calls, bound, next,
                                    0, NoValue(), retained, marks);
        }
    }
    count := item.a + 1;
    arguments := slice(values, top - count, count);
    object := arguments[0];
    element := SequenceElement(types, {storage: object.storage, container: object.container, record: object.record});
    index: int = 1;
    while (index < count) {
        expected := Typed(-1, element.storage, element.container, element.record);
        if (operation == 3) {
            expected = Typed(-1, object.storage, ArrayContainer, object.record);
        } else if (operation == 6 || operation == 10 || operation == 11 ||
                   ((operation == 4 || operation == 5) && index == 1)) {
            expected = Typed(-1, IntStorage, 0, -1);
        }
        if (!Accepts(types, expected.storage, expected.container, expected.record, arguments[index])) {
            return Fail(forest, item.node, document, "argument differs from the mutating method's parameter type");
        }
        index += 1;
    }
    // Each argument is the call's next watched input, as stage zero watches it.
    watches: Code[] = [];
    index = 1;
    while (ops.debug && index < count) {
        argument := arguments[index];
        watches.append(WatchCode(ops, argument.slot, argument.storage, argument.container, argument.record, index,
                                 false, node, target));
        index += 1;
    }
    // Runtime accepts the operation as its second, int-typed argument.
    operation_slot := at.slot;
    operation_code := ConstantCode(ops, IntStorage, u64(operation), operation_slot, node);
    watches.append(operation_code);
    operation_value := Typed(operation_slot, IntStorage, 0, -1);
    arguments = insert(arguments, 1, operation_value);
    shifted: Bases = {pc: at.pc + length(watches), slot: at.slot + 1, local: at.local, cell: at.cell, host: at.host,
                      call: at.call};
    switch SequenceCallStep(arguments, ArrayMutatePlaceIntrinsic, Typed(-1, BoolStorage, 0, -1), u64(0), false,
                            count, ops, target, shifted, node) {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, names, next, popped, result, retained, marks):
            emitted := Step.Emitted(extend(watches, code), extend([ValueLocal(IntStorage)], slots),
                                    locals, cells, hosts, roots, calls, names, next, popped, result, retained, marks);
            return CleanupSequenceValues(emitted, Held(types, members, arguments), ops, target, at, node);
    }
}

ArrayElementAssignment :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], node: int) -> bool {
    if (!Is(forest, node, "assignment")) {
        return false;
    }
    destination := Field(forest, node, "target");
    if (Is(forest, destination, "index_expression")) {
        return true;
    }
    if (!Is(forest, destination, "member_expression")) {
        return false;
    }
    root := RootOf(forest, destination);
    if (Is(forest, root, "identifier")) {
        named := Lookup(names, Text(forest, text, root));
        // A name the body may not write reports as stage zero does, and
        // `e.C.f = v` on a handle writes the entity's component instead.
        return named >= 0 && names[named].writable && names[named].place != SelfPlace &&
               names[named].place != AliasPlace &&
               (names[named].storage != HandleStorage || names[named].container != 0);
    }
    return Is(forest, root, "dereference_expression");
}

ElementAssignStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                      values: Value[], top: int, item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    destination := Field(forest, item.node, "target");
    operator := CompoundOperator(Text(forest, text, Field(forest, item.node, "operator")));
    compound := operator != "";
    if (item.phase == 0) {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [DestinationVisit(destination), Resume(item.node, 1, 0, 0)],
                            0, NoValue(), NoValue(), []);
    }
    if (item.phase == 1) {
        place := values[top - 1];
        next: Work[] = [Expect(Field(forest, item.node, "value"), place.storage, place.container, place.record),
                        Resume(Field(forest, item.node, "value"), CopyValuePhase, 0, 0),
                        Resume(item.node, 2, 0, 0)];
        if (place.newkey && compound) {
            return Fail(forest, item.node, document, "compound map assignment is not supported yet");
        }
        if (place.newkey) {
            return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
        }
        // Validate the destination before evaluating the right side. The
        // eventual write resolves the path again after any authored calls.
        switch ReadSequencePlace(place, 0, ops, target, at, node) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, scheduled,
                          popped, value, retained, marks):
                kept := value;
                if (!compound) {
                    kept = NoValue();
                }
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                    0, kept, NoValue(), marks);
        }
    }
    count: int = 2;
    if (compound) {
        count = 3;
    }
    place := values[top - count];
    value := values[top - 1];
    code: Code[] = [];
    slots: Slot[] = [];
    if (place.container == 0 && MixedCompoundIntegers(operator, place.storage, value)) {
        return Fail(forest, item.node, document,
                    format_text("Mismatched integer types {} and {}; convert one operand",
                                TypeName(place.storage), TypeName(value.storage)));
    }
    // A number converts to the destination's type, as stage zero converts it.
    if (place.container == 0 && value.container == 0 && value.storage != place.storage &&
        Converts(value.storage, place.storage)) {
        slots.extend(NumberSlots(value.storage, place.storage));
        code.extend(NumberCode(ops, value.storage, place.storage, value.slot, at.slot, node));
        value = Typed(at.slot + length(slots) - 1, place.storage, 0, -1);
    }
    if (!Accepts(types, place.storage, place.container, place.record, value)) {
        return Fail(forest, destination, document, "assigned value differs from its destination");
    }
    if (compound) {
        before := values[top - 2];
        operation := BinaryOp(ops, operator);
        if (!Numeric(place.storage) || place.container != 0 || !Computes(ops, operation, place.storage)) {
            return Fail(forest, destination, document, "compound assignment needs numeric operands");
        }
        // The destination's current value is watched at it, as stage zero
        // does, except an array or view element, which it updates in place.
        if (ops.debug && (!Is(forest, destination, "index_expression") || place.newkey)) {
            code.append(WatchCode(ops, before.slot, before.storage, before.container, before.record, 0, true,
                                  forest[destination], target));
        }
        slots.append(ValueLocal(place.storage));
        code.append(Instruction(operation, place.storage, at.slot + length(slots) - 1, before.slot, value.slot, -1,
                                node));
        value.slot = at.slot + length(slots) - 1;
    }
    shifted := SlotsPast(at, length(slots));
    emitted := PointerPrefix(code, slots, IgnoreSequenceValue(SequenceCallStep([place, value], ReferenceWriteIntrinsic,
                                                                               Typed(-1, BoolStorage, 0, -1), u64(0), false, count,
                                                                               ops, target, shifted, node)));
    return CleanupSequenceValues(emitted, [value], ops, target, at, node);
}
IgnoreSequenceValue :: (step: Step) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, value, retained, marks):
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                popped, NoValue(), retained, marks);
    }
}

ValueCopyIntrinsic: int : 57;
ValueDropIntrinsic: int : 58;
ArrayMutatePlaceIntrinsic: int : 59;
PlacePhase: int : 41;
PlaceFieldPhase: int : 42;
PlaceIndexPhase: int : 43;
PlaceIndexDonePhase: int : 44;
PlacePointerPhase: int : 45;
CopyValuePhase: int : 46;
ReferenceKeyIntrinsic: int : 35;
ReferenceUnionIntrinsic: int : 60;
PlaceComponentPhase: int : 49;

// A record, union or collection its consumer keeps: a temporary passes as it
// is, since nothing else holds it, and anything else is copied.
CopyValueStep :: (value: Value, popped: int, ops: Ops, target: Target, at: Bases,
                  node: snapshot.SnapshotNode) -> Step {
    if (value.owned || value.place || value.storage <= 0 ||
        (value.container == 0 && value.storage != StructStorage && value.storage != UnionStorage)) {
        return Step.Emitted([], [], [], [], [], [], [], [], [], popped, value, NoValue(), []);
    }
    return SequenceCallStep([value], ValueCopyIntrinsic, Typed(-1, value.storage, value.container, value.record),
                            u64(0), false, popped, ops, target, at, node);
}

PlaceVisit :: (node: int) -> Work {
    return Resume(node, PlacePhase, 0, 0);
}
// The place an assignment writes, which as an array element has no point of its own.
DestinationVisit :: (node: int) -> Work {
    return Resume(node, PlacePhase, 0, 1);
}
PlaceResult :: (step: Step, element: ValueType) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, value, retained, marks):
            result := value;
            result.storage = element.storage;
            result.container = element.container;
            result.record = element.record;
            result.place = true;
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                popped, result, retained, marks);
    }
}
ReadSequencePlace :: (place: Value, popped: int, ops: Ops, target: Target, at: Bases,
                      node: snapshot.SnapshotNode) -> Step {
    return SequenceCallStep([place], ReferenceReadIntrinsic,
                            Typed(-1, place.storage, place.container, place.record), u64(0), false,
                            popped, ops, target, at, node);
}
// A place carries only a rooted logical location. Projections preserve the
// owner and their evaluated indices; they never retain a backing data pointer.
SequencePlaceStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                      members: TypeMember[], names: Name[], values: Value[], top: int, item: Work,
                      ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    if (item.phase == PlaceComponentPhase) {
        entity := values[top - 1];
        if (!Single(entity, HandleStorage)) {
            return Fail(forest, item.node, document, "component place requires an entity");
        }
        return SequenceComponentPlace(types, item.a, entity.slot, 1, ops, target, at, node);
    }
    if (item.phase == PlacePointerPhase) {
        pointer := values[top - 1];
        element := PointerElement(types, pointer);
        if (element.storage == 0 || (pointer.record >= 0 && types[pointer.record].key != 0)) {
            return Fail(forest, item.node, document, "place requires a present pointer");
        }
        step := PlaceResult(PointerReferenceStep(pointer, ops, target, at, node), element);
        if (item.a != 0) {
            return PointerContinue(step, Resume(item.node, item.a, 0, 0));
        }
        return step;
    }
    if (item.phase == PlaceFieldPhase) {
        base := values[top - 1];
        if (base.storage == PointerStorage && base.container == 0) {
            resumed := Resume(item.node, PlacePointerPhase, PlaceFieldPhase, 0);
            return PointerContinue(ReadSequencePlace(base, 1, ops, target, at, node), resumed);
        }
        if (!base.place || base.storage != StructStorage || base.container != 0) {
            return Fail(forest, item.node, document, "field mutation requires a writable record");
        }
        field := FindField(types, members, base.record, Text(forest, text, Field(forest, item.node, "member")));
        if (field < 0) {
            return Fail(forest, item.node, document, "Unknown field");
        }
        part := members[field];
        element: ValueType = {storage: part.storage, container: part.container, record: part.record};
        offset := TypedCell(WordStorage, 0, -1);
        offset.constant = u64(part.offset);
        cells: Cell[] = [ReferenceCell(target), TypedCell(part.storage, part.container, part.record),
                         offset, TypedCell(BoolStorage, 0, -1), ReferenceCell(target)];
        code := CellWrite(target.pointer_storage, base.slot, at.cell, ops, target, at.slot, node);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        code.extend(CellRead(target.pointer_storage, at.cell + 4, ops, target, at.slot + 1, node));
        hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: ReferenceFieldIntrinsic, linked: -1, first: at.cell,
                          result_first: at.cell + 4, result_count: 1, written: false}];
        result := Typed(at.slot + 2, part.storage, part.container, part.record);
        result.place = true;
        // A component-typed record's field reads it, as stage zero records.
        return EffectsStep(Step.Emitted(code, [AddressSlot(target), AddressSlot(target), DescriptorSlot(target)], [],
                                        cells, hosts, [], [], [], [], 1, result, NoValue(), []),
                           MemberEffects(types, base.record));
    }
    if (item.phase == PlaceIndexPhase) {
        base := values[top - 1];
        storage := IntStorage;
        if (IsMap(base)) {
            storage = types[base.record].key;
        }
        if (!base.place || (base.container != ArrayContainer && base.container != ViewContainer && !IsMap(base))) {
            return Fail(forest, item.node, document, "indexed mutation requires a writable array or map");
        }
        // A map entry an assignment writes keeps its point, as stage zero
        // marks a key it stores.
        points: Code[] = [];
        if (item.b == 1 && IsMap(base)) {
            points = [ExpressionCode(ops, node)];
        }
        return Step.Emitted(points, [], [], [], [], [], [], [],
                            [Expect(Field(forest, item.node, "index"), storage, 0, -1),
                             Resume(item.node, PlaceIndexDonePhase, 0, 0)],
                            0, NoValue(), NoValue(), []);
    }
    if (item.phase == PlaceIndexDonePhase) {
        base := values[top - 2];
        index := values[top - 1];
        element := SequenceElement(types, {storage: base.storage, container: base.container, record: base.record});
        intrinsic := ReferenceFieldIntrinsic;
        if (IsMap(base)) {
            map := types[base.record];
            element = {storage: map.value_storage, container: map.value_container, record: map.value_record};
            intrinsic = ReferenceKeyIntrinsic;
        }
        cells: Cell[] = [ReferenceCell(target), TypedCell(element.storage, element.container, element.record),
                         TypedCell(index.storage, index.container, index.record)];
        if (intrinsic == ReferenceFieldIntrinsic) {
            selected := TypedCell(BoolStorage, 0, -1);
            selected.constant = 1;
            cells.append(selected);
        }
        output := at.cell + length(cells);
        cells.append(ReferenceCell(target));
        code := CellWrite(target.pointer_storage, base.slot, at.cell, ops, target, at.slot, node);
        code.extend(CellWrite(index.storage, index.slot, at.cell + 2, ops, target, at.slot + 1, node));
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        code.extend(CellRead(target.pointer_storage, output, ops, target, at.slot + 2, node));
        hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: output,
                          result_count: 1, written: false}];
        result := Typed(at.slot + 3, element.storage, element.container, element.record);
        result.place = true;
        result.newkey = IsMap(base);
        return Step.Emitted(code, [AddressSlot(target), AddressSlot(target), AddressSlot(target), DescriptorSlot(target)],
                            [], cells, hosts, [], [], [], [], 2, result, NoValue(), []);
    }
    if (node.kind == "parenthesized_expression") {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [PlaceVisit(Field(forest, item.node, "expression"))], 0, NoValue(), NoValue(), []);
    }
    if (node.kind == "dereference_expression") {
        operand := Unparenthesized(forest, Field(forest, item.node, "operand"));
        if (Is(forest, operand, "identifier")) {
            scoped := Lookup(names, Text(forest, text, operand));
            if (scoped >= 0 && names[scoped].place == ReferencePlace) {
                return Step.Emitted([], [], [], [], [], [], [], [], [PlaceVisit(operand)],
                                    0, NoValue(), NoValue(), []);
            }
        }
        // Stage zero marks a pointer it follows to reach an element or field.
        points: Code[] = [];
        if (Is(forest, node.parent, "index_expression") || Is(forest, node.parent, "member_expression")) {
            points = [ExpressionCode(ops, node)];
        }
        return Step.Emitted(points, [], [], [], [], [], [], [],
                            [Visit(Field(forest, item.node, "operand")), Resume(item.node, PlacePointerPhase, 0, 0)],
                            0, NoValue(), NoValue(), []);
    }
    if (node.kind == "member_expression") {
        component := SelfComponent(forest, text, types, names, item.node);
        if (component >= 0) {
            return SequenceComponentPlace(types, component, -1, 0, ops, target, at, node);
        }
        object := Field(forest, item.node, "object");
        found: int = -1;
        if (Is(forest, object, "identifier")) {
            found = Lookup(names, Text(forest, text, object));
        }
        component = Component(types, Text(forest, text, Field(forest, item.node, "member")));
        if (component >= 0 && found >= 0 && names[found].storage == HandleStorage) {
            return Step.Emitted([], [], [], [], [], [], [], [],
                                [Visit(object), Resume(item.node, PlaceComponentPhase, component, 0)],
                                0, NoValue(), NoValue(), []);
        }
    }
    if (node.kind == "member_expression" || node.kind == "index_expression") {
        // As stage zero marks a place: each field and element, outermost
        // first, then the name it starts from.
        phase := PlaceFieldPhase;
        points: Code[] = [ExpressionCode(ops, node)];
        root := PlaceVisit(Field(forest, item.node, "object"));
        if (node.kind == "index_expression") {
            phase = PlaceIndexPhase;
        }
        if (node.kind == "index_expression" && item.b == 1) {
            points = [];
            // Stage zero stores an element of a local array in place: it
            // marks the element, and the array's name at the statement.
            if (StoresLocalElement(forest, text, names, item.node)) {
                points = [ExpressionCode(ops, node)];
                root.b = 2;
            }
        }
        return Step.Emitted(points, [], [], [], [], [], [], [], [root, Resume(item.node, phase, 0, item.b)],
                            0, NoValue(), NoValue(), []);
    }
    found := Lookup(names, Text(forest, text, item.node));
    if (node.kind != "identifier" || found < 0 || !names[found].writable) {
        return Fail(forest, item.node, document, "mutation requires a writable place");
    }
    points := NamePoints(forest, text, names, ops, item.node);
    binding := names[found];
    if (item.b == 2) {
        points = [SymbolCode(ops, binding.node, forest[forest[node.parent].parent])];
    }
    if (binding.place == NarrowedPlace) {
        // The payload's place in the optional's, which stage zero marks
        // again as the payload.
        points.append(ExpressionCode(ops, node));
        element: ValueType = {storage: binding.storage, container: binding.container, record: binding.record};
        return PointerPrefix(points, [], PayloadPlaceAfter(types, NamePlaceStep(forest, document, types, names[binding.index],
                                                                                item.node, ops, target, at),
                                                           element, ops, target, at, node));
    }
    return PointerPrefix(points, [], NamePlaceStep(forest, document, types, binding, item.node, ops, target, at));
}
// Whether the assignment target `node` is an element of a local array that
// stage zero stores in place: a plain assignment to a writable local's
// element, not a parameter's.
StoresLocalElement :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], node: int) -> bool {
    object := Field(forest, node, "object");
    statement := forest[node].parent;
    if (!Is(forest, object, "identifier") || !Is(forest, statement, "assignment") ||
        CompoundOperator(Text(forest, text, Field(forest, statement, "operator"))) != "") {
        return false;
    }
    found := Lookup(names, Text(forest, text, object));
    return found >= 0 && names[found].place == CellPlace && names[found].container == ArrayContainer &&
           names[found].writable && !Parameter(forest, names[found]);
}
// The place of the local `binding` that the name `name` reads.
NamePlaceStep :: (forest: snapshot.SnapshotNode[], document: int, types: TypeDecl[], binding: Name, name: int, ops: Ops,
                  target: Target, at: Bases) -> Step {
    node := forest[name];
    element: ValueType = {storage: binding.storage, container: binding.container, record: binding.record};
    if (binding.place == ManagedPlace) {
        pointer := FindPointer(types, element, false);
        code := CellRead(PointerStorage, binding.index, ops, target, at.slot, node);
        slots: Slot[] = [AddressSlot(target), {storage: PointerStorage, kind: ValueKind}];
        return PlaceResult(PointerPrefix(code, slots, PointerPopped(PointerReferenceStep(
            Typed(at.slot + 1, PointerStorage, 0, pointer), ops, target, SlotsPast(at, 2), node), 0)), element);
    }
    if (binding.place == LocalPlace && Single(Typed(-1, binding.storage, binding.container, binding.record),
                                              PointerStorage)) {
        // A pointer local writes through to its target, whose place it is;
        // stage zero marks and watches the pointer as the value it
        // dereferences.
        pointer := Typed(at.slot, PointerStorage, 0, binding.record);
        target_type := PointerElement(types, pointer);
        if (target_type.storage == 0 || types[binding.record].key != 0) {
            return Fail(forest, name, document, "place requires a present pointer");
        }
        code: Code[] = [ExpressionCode(ops, node), Instruction(ops.local, PointerStorage, at.slot, binding.index, 0, 0, node)];
        if (ops.debug) {
            code.append(WatchCode(ops, at.slot, PointerStorage, 0, binding.record, 0, true, node, target));
        }
        return PlaceResult(PointerPrefix(code, [ValueLocal(PointerStorage)],
                                         PointerPopped(PointerReferenceStep(
                                             pointer, ops, target, SlotsPast(at, 1), node), 0)), target_type);
    }
    if (binding.place != CellPlace && binding.place != BoxPlace && binding.place != ReferencePlace) {
        return Fail(forest, name, document, "mutation requires a local value");
    }
    code: Code[] = [];
    slots: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    descriptor := at.slot;
    if (binding.place == ReferencePlace) {
        slots.append(DescriptorSlot(target));
        code.append(DescriptorCode(ops, target, binding.index, descriptor, node));
    } else {
        cells = MakeValueCells(target, binding.storage, binding.container, binding.record);
        slots = MakeValueSlots(target);
        code.extend(MakeValueCode(ops, target, binding.index, at.cell, at.host, at.slot, node));
        hosts = [MakeValueHost(at.cell)];
        descriptor = at.slot + 5;
    }
    result := Typed(descriptor, binding.storage, binding.container, binding.record);
    result.place = true;
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], 0, result, NoValue(), []);
}

SequenceJoined :: (prefix: Step, suffix: Step) -> Step {
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, value, retained, marks):
            switch suffix {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(tail_code, tail_slots, tail_locals, tail_cells, tail_hosts, tail_roots,
                              tail_calls, tail_bound, tail_next, tail_popped, tail_value, tail_retained, tail_marks):
                    return Step.Emitted(extend(code, tail_code), extend(slots, tail_slots), extend(locals, tail_locals),
                                        extend(cells, tail_cells), extend(hosts, tail_hosts), extend(roots, tail_roots),
                                        extend(calls, tail_calls), extend(bound, tail_bound), extend(next, tail_next),
                                        popped + tail_popped, tail_value, tail_retained, extend(marks, tail_marks));
            }
    }
}
// Whether a value of record or union type `record` can hold a collection,
// which is all a drop releases. A record reaches one only through a union
// field. A type met again on the way may hold one.
HoldsCollection :: (types: TypeDecl[], members: TypeMember[], record: int, visiting: int[]) -> bool {
    for (seen in visiting) {
        if (seen == record) {
            return true;
        }
    }
    declared := types[record];
    within := extend(visiting, [record]);
    if (declared.kind == UnionDecl) {
        variant := declared.first;
        while (variant < declared.first + declared.count) {
            if (HoldsCollection(types, members, variant, within)) {
                return true;
            }
            variant += 1;
        }
        return false;
    }
    if (declared.kind != RecordDecl && declared.kind != VariantDecl && declared.kind != MathDecl) {
        return true;
    }
    index := declared.first;
    while (index < declared.first + declared.count) {
        field := members[index];
        if (field.container != 0 ||
            ((field.storage == StructStorage || field.storage == UnionStorage) &&
             HoldsCollection(types, members, field.record, within))) {
            return true;
        }
        index += 1;
    }
    return false;
}
// The values a drop could release anything from: collections, and records
// and unions that can hold one. Dropping any other value does nothing.
Held :: (types: TypeDecl[], members: TypeMember[], values: Value[]) -> Value[] {
    held: Value[] = [];
    for (value in values) {
        if (value.container != 0 || value.record < 0 || value.record >= length(types) ||
            (value.storage != StructStorage && value.storage != UnionStorage) ||
            HoldsCollection(types, members, value.record, [])) {
            held.append(value);
        }
    }
    return held;
}
// Release only values whose producer handed ownership to this expression.
// Plain reads and logical places never own the value they temporarily expose.
DropSequenceValues :: (values: Value[], ops: Ops, target: Target, at: Bases,
                       node: snapshot.SnapshotNode) -> Step {
    result := Step.Emitted([], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
    shifted := at;
    for (value in values) {
        if (value.owned && value.storage > 0) {
            step := IgnoreSequenceValue(SequenceCallStep([value], ValueDropIntrinsic,
                                                         Typed(-1, BoolStorage, 0, -1), u64(0), false,
                                                         0, ops, target, shifted, node));
            switch step {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(code);
                    shifted.slot += length(slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            result = SequenceJoined(result, step);
        }
    }
    return result;
}
CleanupSequenceValues :: (prefix: Step, values: Value[], ops: Ops, target: Target, at: Bases,
                          node: snapshot.SnapshotNode) -> Step {
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots),
                              local: at.local + length(locals), cell: at.cell + length(cells),
                              host: at.host + length(hosts), call: at.call + length(calls)};
            joined := SequenceJoined(prefix, DropSequenceValues(values, ops, target, shifted, node));
            switch joined {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                              all_calls, all_bound, all_next, all_popped, dropped, all_retained, all_marks):
                    return Step.Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                                        all_calls, all_bound, all_next, all_popped, produced, retained, all_marks);
            }
    }
}

DropNamesStep :: (names: Name[], first: int, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target, at: Bases,
                  node: snapshot.SnapshotNode) -> Step {
    prefix := Step.Emitted([], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
    shifted := at;
    index := first;
    while (index < length(names)) {
        binding := names[index];
        if (binding.owned && binding.place == ResultsPlace && binding.storage == ResultsStorage) {
            dropped := DropNativeResultsStep(Typed(binding.index, ResultsStorage, 0, binding.record),
                                             natives, ports, ops, target, shifted, node);
            switch dropped {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(added_code);
                    shifted.slot += length(added_slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            prefix = SequenceJoined(prefix, dropped);
        }
        if (binding.owned && binding.place == CellPlace) {
            value := Typed(shifted.slot + 1, binding.storage, binding.container, binding.record);
            value.owned = true;
            code := CellRead(SlotStorage(binding.storage, binding.container, target), binding.index,
                             ops, target, shifted.slot, node);
            slots: Slot[] = [AddressSlot(target),
                             {storage: SlotStorage(binding.storage, binding.container, target),
                              kind: SlotKind(binding.storage, binding.container)}];
            read := Step.Emitted(code, slots, [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
            dropped := CleanupSequenceValues(read, [value], ops, target, shifted, node);
            switch dropped {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(added_code);
                    shifted.slot += length(added_slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            prefix = SequenceJoined(prefix, dropped);
        }
        index += 1;
    }
    return prefix;
}
DropBeforeFinish :: (step: Step, names: Name[], natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target, at: Bases,
                     node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            if (length(code) == 0 || code[length(code) - 1].op != ops.finish) {
                return step;
            }
            finish := code[length(code) - 1];
            prefix := Step.Emitted(slice(code, 0, length(code) - 1), slots, locals, cells, hosts, roots,
                                   calls, bound, next, popped, produced, retained, marks);
            shifted: Bases = {pc: at.pc + length(code) - 1, slot: at.slot + length(slots),
                              local: at.local + length(locals), cell: at.cell + length(cells),
                              host: at.host + length(hosts), call: at.call + length(calls)};
            dropped := DropNamesStep(names, 0, natives, ports, ops, target, shifted, node);
            suffix := Step.Emitted([finish], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
            return SequenceJoined(SequenceJoined(prefix, dropped), suffix);
    }
}

DropNativeResultsStep :: (bundle: Value, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target,
                          at: Bases, node: snapshot.SnapshotNode) -> Step {
    prefix := Step.Emitted([], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
    shifted := at;
    called := natives[bundle.record];
    index: int = 0;
    while (index < called.results) {
        port := ports[called.first + called.parameters + index];
        if (Pointer(port.storage, port.container)) {
            value := Typed(shifted.slot + 1, port.storage, port.container, port.record);
            value.owned = true;
            code := CellRead(SlotStorage(port.storage, port.container, target), bundle.slot + index,
                             ops, target, shifted.slot, node);
            slots: Slot[] = [AddressSlot(target),
                             {storage: SlotStorage(port.storage, port.container, target),
                              kind: SlotKind(port.storage, port.container)}];
            read := Step.Emitted(code, slots, [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
            dropped := CleanupSequenceValues(read, [value], ops, target, shifted, node);
            switch dropped {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(added_code);
                    shifted.slot += length(added_slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            prefix = SequenceJoined(prefix, dropped);
        }
        index += 1;
    }
    return prefix;
}

SequenceComponentPlace :: (types: TypeDecl[], component: int, entity: int, popped: int, ops: Ops,
                           target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code := OwnerCode(ops, target, at.cell, entity, at.slot, node);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(target.pointer_storage, at.cell + 9, ops, target, at.slot + 4, node));
    slots := extend(OwnerSlots(target), [AddressSlot(target), DescriptorSlot(target)]);
    cells := MakeCells(target, component, ComponentFacts(types[component]));
    hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: ReferenceMakeIntrinsic, linked: -1, first: at.cell,
                      result_first: at.cell + 9, result_count: 1, written: true}];
    result := Typed(at.slot + 5, StructStorage, 0, component);
    result.place = true;
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], popped, result, NoValue(), []);
}

SequenceKept :: (prefix: Step, suffix: Step) -> Step {
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            joined := SequenceJoined(prefix, suffix);
            switch joined {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                              all_calls, all_bound, all_next, all_popped, dropped, all_retained, all_marks):
                    return Step.Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                                        all_calls, all_bound, all_next, all_popped, produced, retained, all_marks);
            }
    }
}
// A projection from a temporary must keep its selected value before the
// temporary's owner is released. Projections from named values stay borrowed.
CleanupProjectionStep :: (prefix: Step, owner: Value, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops,
                          target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    if (!owner.owned) {
        return prefix;
    }
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots),
                              local: at.local + length(locals), cell: at.cell + length(cells),
                              host: at.host + length(hosts), call: at.call + length(calls)};
            copied := SequenceJoined(prefix, CopyValueStep(produced, 0, ops, target, shifted, node));
            if (owner.storage != ResultsStorage) {
                return CleanupSequenceValues(copied, [owner], ops, target, at, node);
            }
            switch copied {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                              all_calls, all_bound, all_next, all_popped, value, held, all_marks):
                    cleanup_at: Bases = {pc: at.pc + length(all_code), slot: at.slot + length(all_slots),
                                         local: at.local + length(all_locals), cell: at.cell + length(all_cells),
                                         host: at.host + length(all_hosts), call: at.call + length(all_calls)};
                    return SequenceKept(copied, DropNativeResultsStep(owner, natives, ports, ops, target, cleanup_at, node));
            }
    }
}

CopyResultCellsStep :: (bundle: Value, result_types: Value[], ops: Ops, target: Target,
                        at: Bases, node: snapshot.SnapshotNode) -> Step {
    output_cells: Cell[] = [];
    index: int = 0;
    while (index < length(result_types)) {
        port := result_types[index];
        output_cells.append(TypedCell(port.storage, port.container, port.record));
        index += 1;
    }
    prefix := Step.Emitted([], [], [], output_cells, [], [], [], [], [], 0, NoValue(), NoValue(), []);
    index = 0;
    while (index < length(result_types)) {
        port := result_types[index];
        switch prefix {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                          popped, produced, retained, marks):
                shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots),
                                  local: at.local + length(locals), cell: at.cell + length(cells),
                                  host: at.host + length(hosts), call: at.call + length(calls)};
                value := Typed(shifted.slot + 1, port.storage, port.container, port.record);
                read_code := CellRead(SlotStorage(port.storage, port.container, target), bundle.slot + index,
                                      ops, target, shifted.slot, node);
                read_slots: Slot[] = [AddressSlot(target),
                                      {storage: SlotStorage(port.storage, port.container, target),
                                       kind: SlotKind(port.storage, port.container)}];
                read := Step.Emitted(read_code, read_slots, [], [], [], [], [], [], [], 0, value, NoValue(), []);
                copy_at := SlotsPast(shifted, 2);
                copied := SequenceJoined(read, CopyValueStep(value, 0, ops, target, copy_at, node));
                switch copied {
                    case .Failed(diagnostic):
                        return Step.Failed(diagnostic);
                    case .Emitted(copy_code, copy_slots, copy_locals, copy_cells, copy_hosts, copy_roots,
                                  copy_calls, copy_bound, copy_next, copy_popped, result, copy_retained, copy_marks):
                        store_code := CellWrite(SlotStorage(port.storage, port.container, target), result.slot,
                                                at.cell + index, ops, target, shifted.slot + length(copy_slots), node);
                        store := Step.Emitted(store_code, [AddressSlot(target)], [], [], [], [], [], [], [],
                                              0, NoValue(), NoValue(), []);
                        prefix = SequenceJoined(prefix, SequenceJoined(copied, store));
                }
        }
        index += 1;
    }
    result := Typed(at.cell, bundle.storage, 0, bundle.record);
    result.cell = at.cell;
    result.owned = true;
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                1, result, NoValue(), marks);
    }
}

CopyNativeResultsStep :: (bundle: Value, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target,
                          at: Bases, node: snapshot.SnapshotNode) -> Step {
    called := natives[bundle.record];
    result_types: Value[] = [];
    index: int = 0;
    while (index < called.results) {
        port := ports[called.first + called.parameters + index];
        result_types.append(Typed(-1, port.storage, port.container, port.record));
        index += 1;
    }
    return CopyResultCellsStep(bundle, result_types, ops, target, at, node);
}
CopyFunctionResultsStep :: (bundle: Value, callables: Callable[], params: Param[], ops: Ops, target: Target,
                            at: Bases, node: snapshot.SnapshotNode) -> Step {
    called := callables[bundle.record];
    result_types: Value[] = [];
    index: int = 0;
    while (index < called.results) {
        param := params[called.first + called.count + index];
        result_types.append(Typed(-1, param.storage, param.container, param.record));
        index += 1;
    }
    return CopyResultCellsStep(bundle, result_types, ops, target, at, node);
}
package package_compiler

import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"
import binding "project:lexical_binding"
import writer "project:prepared_writer"
import strings "core:strings"

// A query description and its rows have one runtime representation. Their
// nominal declaration keeps row fields typed without inventing a record ABI.
QueryStorage: int : 20;
QueryDecl: int : 7;
RelationshipDecl: int : 8;
OptionalComponentDecl: int : 9;
QueryDescriptorDecl: int : 10;
QueryFieldPlace: int : 11;
QueryVariablePlace: int : 12;
QuerySnapshotPlace: int : 13;
QuerySnapshotHeaderPlace: int : 14;
QueryMakeIntrinsic: int : 80;
QueryBeginIntrinsic: int : 81;
QueryNextIntrinsic: int : 82;
QueryEndIntrinsic: int : 83;
QueryGetIntrinsic: int : 84;
ComponentPointerIntrinsic: int : 85;
QueryCurrentIntrinsic: int : 86;
QueryTestIntrinsic: int : 87;
ComponentSnapshotIntrinsic: int : 88;
QueryMakePhase: int : 60;
QueryBindPhase: int : 61;
QueryGuardPhase: int : 62;
QueryFinishPhase: int : 63;
QueryReturnPhase: int : 64;
QueryIteratorPhase: int : 65;
QueryIteratorEndPhase: int : 66;
QueryProviderPhase: int : 69;
QueryMembershipPhase: int : 70;

QueryField :: struct {
    name: string;
    node: int;
    storage: int;
    container: int;
    record: int;
    component: int;
    variable: int;
    source: int;
    source_relationship: u64;
    source_traversal: int;
    optional: bool;
}
QueryTerm :: struct {
    kind: int;
    required: bool;
    node: int;
    left: int;
    right: int;
    root: bool;
    component: u64;
    source_variable: int;
    target_variable: int;
    source_relationship: u64;
    source_traversal: int;
}
QueryProvider :: struct {
    variable: int;
    relation: u64;
    traversal: int;
    valid: bool;
}
// One literal holds `relation`: storing a u64 into a local record's field
// would make every caller copy its arguments, as ConstantCode notes.
QueryProviderOf :: (variable: int, relation: u64, traversal: int, valid: bool) -> QueryProvider {
    return {variable: variable, relation: relation, traversal: traversal, valid: valid};
}
QuerySource :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], fields: QueryField[], source: int) -> QueryProvider {
    provider: QueryProvider = {variable: 0, relation: 0, traversal: 0, valid: true};
    if (source < 0 || Text(forest, text, source) == "self") {
        return provider;
    }
    name := Text(forest, text, source);
    if (Is(forest, source, "identifier")) {
        previous := QueryFieldIndex(fields, name);
        if (previous >= 0 && fields[previous].variable != 0) {
            provider.variable = fields[previous].variable;
            return provider;
        }
    } else if (Is(forest, source, "member_expression")) {
        owner := Text(forest, text, Field(forest, source, "object"));
        if (owner != "self") {
            previous := QueryFieldIndex(fields, owner);
            if (previous < 0 || fields[previous].variable == 0) {
                provider.valid = false;
                return provider;
            }
            provider.variable = fields[previous].variable;
        }
        name = Text(forest, text, Field(forest, source, "member"));
    } else if (Is(forest, source, "call_expression")) {
        function := Text(forest, text, Field(forest, source, "function"));
        if (function != "ancestor" && function != "self_or_ancestor") {
            provider.valid = false;
            return provider;
        }
        argument := FirstMember(forest, Field(forest, source, "arguments"));
        if (argument < 0 || NextMember(forest, argument) >= 0) {
            provider.valid = false;
            return provider;
        }
        name = Text(forest, text, argument);
        provider.traversal = 1;
        if (function == "self_or_ancestor") {
            provider.traversal = 2;
        }
    } else {
        provider.valid = false;
        return provider;
    }
    if (name == "ChildOf") {
        return QueryProviderOf(provider.variable, 0x84771d550890f1a1, provider.traversal, true);
    }
    relation := Relationship(types, name);
    if (relation < 0 || (types[relation].key & 1) == 0 ||
        (provider.traversal != 0 && (types[relation].key & 4) == 0)) {
        provider.valid = false;
        return provider;
    }
    return QueryProviderOf(provider.variable, types[relation].component, provider.traversal, true);
}
QuerySpec :: struct {
    node: int;
    evaluator: int;
    row: int;
    description: int;
    variables: int;
    first_capture: int;
    capture_count: int;
}
QueryDeclarations :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Collected(types: TypeDecl[], members: TypeMember[], callables: Callable[], params: Param[], queries: QuerySpec[])
}
QueryDispatch :: union {
    Handled(step: Step) | Ordinary
}
// Query evaluation is one expression-emission seam. Keeping it here also
// keeps ordinary body dispatch within the verifier's definition budget.
QueryStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], members: TypeMember[],
              params: Param[], queries: QuerySpec[], evaluating: int, names: Name[], values: Value[], top: int,
              item: Work, ops: Ops, target: Target, at: Bases) -> QueryDispatch {
    node := forest[item.node];
    kind := node.kind;
    if (evaluating >= 0 && (item.node == queries[evaluating].node || kind == "query_binding" ||
                            kind == "query_guard" || kind == "query_generator" || kind == "parameter" ||
                            item.phase == QueryReturnPhase)) {
        return QueryDispatch.Handled(QueryEvaluateStep(forest, text, document, types, queries, queries[evaluating],
                                                       members, names, values, top, item, ops, target, at));
    }
    if (kind == "query_expression") {
        return QueryDispatch.Handled(QueryExpressionStep(forest, document, params, queries, values, top, item, ops, target, at));
    }
    if (!item.capture && evaluating >= 0 && (item.phase == QueryMembershipPhase ||
                                             ((kind == "identifier" || kind == "member_expression" ||
                                               (kind == "call_expression" && Text(forest, text, Field(forest, item.node, "function")) == "has")) &&
                                              QueryBooleanPosition(forest, text, item.node)))) {
        term := QueryMembership(forest, text, types, members, params, queries[evaluating], item.node);
        if (term.kind >= 0) {
            return QueryDispatch.Handled(QueryMembershipStep(term, values, top, item, ops, target, at, node));
        }
    }
    if (!item.capture && kind == "member_expression" &&
        (item.phase == QueryPresencePhase || QueryPresence(forest, text, types, names, item.node) >= 0)) {
        component := item.a;
        if (item.phase == 0) {
            component = QueryPresence(forest, text, types, names, item.node);
        }
        return QueryDispatch.Handled(QueryPresenceStep(forest, types, component, values, top, item, ops, target, at));
    }
    if (kind == "call_expression" && Text(forest, text, Field(forest, item.node, "function")) == "changed") {
        return QueryDispatch.Handled(QueryChangedStep(forest, text, document, types, members, params, queries, item, ops, target, at));
    }
    return QueryDispatch.Ordinary;
}

// Query-only field metadata uses the existing flattened type-member bank:
// read is its syntax node, offset its source variable, c_string its optional
// flag. Query rows never interpret these as physical record offsets/getters.
QueryFields :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                described: QuerySpec) -> QueryField[] {
    fields: QueryField[] = [];
    declared := types[described.row];
    index: int = 0;
    variables: int = 0;
    while (index < declared.count) {
        member := members[declared.first + index];
        component: int = -1;
        variable: int = 0;
        provider: QueryProvider = {variable: member.offset, relation: 0, traversal: 0, valid: true};
        if (Is(forest, member.read, "query_generator")) {
            variables += 1;
            variable = variables;
        } else if (Is(forest, member.read, "parameter")) {
            provider = QuerySource(forest, text, types, fields, Field(forest, member.read, "source"));
            component = member.record;
            if (member.storage == PointerStorage) {
                component = PointerElement(types, Typed(-1, PointerStorage, 0, member.record)).record;
            }
            if (component >= 0 && types[component].kind == OptionalComponentDecl) {
                component = types[component].parent;
            }
        }
        field: QueryField = {name: member.name, node: member.read, storage: member.storage, container: member.container,
                             record: member.record, component: component, variable: variable, source: member.offset,
                             source_relationship: provider.relation, source_traversal: provider.traversal,
                             optional: member.c_string};
        fields.append(field);
        index += 1;
    }
    return fields;
}
QueryLeaf :: (kind: int, component: u64, source: int, target: int, relation: u64,
              traversal: int, node: int) -> QueryTerm {
    return {kind: kind, required: false, node: node, left: -1, right: -1, root: false, component: component,
            source_variable: source, target_variable: target, source_relationship: relation, source_traversal: traversal};
}
QueryGuardTerms :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], fields: QueryField[],
                    captured: string[], node: int) -> QueryTerm[] {
    expression := Unparenthesized(forest, node);
    kind := forest[expression].kind;
    operator := Text(forest, text, Field(forest, expression, "operator"));
    if (kind == "call_expression") {
        function := Text(forest, text, Field(forest, expression, "function"));
        if (function == "has" || function == "all" || function == "any" || function == "not") {
            arguments := Members(forest, Field(forest, expression, "arguments"));
            if ((function == "has" || function == "not") && length(arguments) != 1) {
                return [QueryLeaf(6, 0, 0, 0, 0, 0, expression)];
            }
            terms: QueryTerm[] = [];
            for (argument in arguments) {
                added := QueryGuardTerms(forest, text, types, fields, captured, argument);
                previous := length(terms) - 1;
                offset := length(terms);
                for (original in added) {
                    moved := original;
                    if (moved.left >= 0) {
                        moved.left += offset;
                    }
                    if (moved.right >= 0) {
                        moved.right += offset;
                    }
                    terms.append(moved);
                }
                if (previous >= 0) {
                    group := QueryLeaf(1, 0, 0, 0, 0, 0, expression);
                    if (function == "any") {
                        group.kind = 2;
                    }
                    group.left = previous;
                    group.right = length(terms) - 1;
                    terms.append(group);
                }
            }
            if (function == "has" && length(terms) == 1) {
                leaf := terms[0];
                leaf.node = expression;
                return [leaf];
            }
            if (function == "not" || length(terms) == 0) {
                group := QueryLeaf(1, 0, 0, 0, 0, 0, expression);
                if (function == "not") {
                    group.kind = 3;
                    group.left = length(terms) - 1;
                }
                if (function == "any") {
                    group.kind = 2;
                }
                terms.append(group);
            }
            return terms;
        }
    }
    if ((kind == "unary_expression" && (operator == "!" || operator == "not")) ||
        (kind == "binary_expression" && (operator == "&&" || operator == "and" || operator == "||" || operator == "or"))) {
        child := Field(forest, expression, "left");
        if (kind == "unary_expression") {
            child = Field(forest, expression, "operand");
        }
        terms := QueryGuardTerms(forest, text, types, fields, captured, child);
        group := QueryLeaf(3, 0, 0, 0, 0, 0, expression);
        group.left = length(terms) - 1;
        if (kind == "binary_expression") {
            group.kind = 1;
            if (operator == "||" || operator == "or") {
                group.kind = 2;
            }
            right := QueryGuardTerms(forest, text, types, fields, captured, Field(forest, expression, "right"));
            offset := length(terms);
            for (original in right) {
                moved := original;
                if (moved.left >= 0) {
                    moved.left += offset;
                }
                if (moved.right >= 0) {
                    moved.right += offset;
                }
                terms.append(moved);
            }
            group.right = length(terms) - 1;
        }
        terms.append(group);
        return terms;
    }
    changed := kind == "call_expression" && Text(forest, text, Field(forest, expression, "function")) == "changed";
    tested := expression;
    if (changed) {
        tested = FirstMember(forest, Field(forest, expression, "arguments"));
    }
    component: int = -1;
    relation: int = -1;
    provider: QueryProvider = {variable: 0, relation: 0, traversal: 0, valid: true};
    if (Is(forest, tested, "identifier")) {
        name := Text(forest, text, tested);
        field := QueryFieldIndex(fields, name);
        if (field >= 0) {
            component = fields[field].component;
            provider = QueryProviderOf(fields[field].source, fields[field].source_relationship,
                                       fields[field].source_traversal, true);
        } else if (!Holds(captured, name)) {
            component = Component(types, name);
        }
    } else if (Is(forest, tested, "member_expression")) {
        name := Text(forest, text, Field(forest, tested, "member"));
        component = Component(types, name);
        relation = Relationship(types, name);
        object := Field(forest, tested, "object");
        provider = QuerySource(forest, text, types, fields, object);
        if (Is(forest, object, "identifier") && Holds(captured, Text(forest, text, object))) {
            provider.valid = false;
        }
    }
    if (provider.valid && component >= 0) {
        leaf_kind: int = 0;
        if (changed) {
            leaf_kind = 7;
        }
        return [QueryLeaf(leaf_kind, types[component].component, provider.variable, 0,
                          provider.relation, provider.traversal, expression)];
    }
    if (provider.valid && relation >= 0 && !changed && provider.relation == 0) {
        return [QueryLeaf(4, types[relation].component, provider.variable, 0, 0, 0, expression)];
    }
    return [QueryLeaf(6, 0, 0, 0, 0, 0, expression)];
}
QueryTerms :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
               params: Param[], described: QuerySpec) -> QueryTerm[] {
    terms: QueryTerm[] = [];
    captured: string[] = [];
    capture := described.first_capture;
    while (capture < described.first_capture + described.capture_count) {
        captured.append(params[capture].name);
        capture += 1;
    }
    fields := QueryFields(forest, text, types, members, described);
    prior: QueryField[] = [];
    for (clause in Members(forest, Field(forest, described.node, "parameters"))) {
        if (Is(forest, clause, "query_guard")) {
            guards := QueryGuardTerms(forest, text, types, prior, captured, Field(forest, clause, "condition"));
            offset := length(terms);
            index: int = 0;
            for (original in guards) {
                moved := original;
                if (moved.left >= 0) {
                    moved.left += offset;
                }
                if (moved.right >= 0) {
                    moved.right += offset;
                }
                moved.root = index == length(guards) - 1;
                terms.append(moved);
                index += 1;
            }
            continue;
        }
        field := fields[length(prior)];
        prior.append(field);
        if (field.variable != 0) {
            source := Field(forest, field.node, "source");
            relation := Relationship(types, Text(forest, text, Field(forest, source, "member")));
            term := QueryLeaf(5, types[relation].component, field.source, field.variable, 0, 0, field.node);
            term.root = true;
            terms.append(term);
        } else if (field.component >= 0 && !field.optional) {
            term := QueryLeaf(0, types[field.component].component, field.source, 0, field.source_relationship,
                              field.source_traversal, field.node);
            term.root = true;
            term.required = true;
            terms.append(term);
        } else if (Is(forest, field.node, "query_binding")) {
            // Computation stays in the ordered evaluator; this marker keeps
            // later membership tests from being hoisted ahead of it.
            term := QueryLeaf(6, 0, 0, 0, 0, 0, field.node);
            term.root = true;
            terms.append(term);
        }
    }
    return terms;
}
QueryPointers :: (types: TypeDecl[], members: TypeMember[]) -> TypeDecl[] {
    declared := types;
    for (native in types) {
        if (native.kind != NativeDecl || native.component == 0) {
            continue;
        }
        index := native.first;
        while (index < native.first + native.count) {
            field := members[index];
            EnsurePointer(&declared, {storage: field.storage, container: field.container, record: field.record}, false, 0);
            index += 1;
        }
    }
    return declared;
}
QueryRowName :: (types: TypeDecl[], fields: QueryField[], start: int) -> string {
    shape: u64 = 14695981039346656037;
    for (field in fields) {
        nominal: u64 = 0;
        layout: u64 = 0;
        component_layout: u64 = 0;
        flags: int = 0;
        if (field.optional) {
            flags = 2;
        }
        if (field.record >= 0) {
            nominal = types[field.record].id;
            layout = types[field.record].layout;
            if ((field.storage == PointerStorage && types[field.record].key != 0) ||
                types[field.record].kind == OptionalComponentDecl) {
                flags = flags | 2;
            }
            if (types[field.record].kind == QueryDecl) {
                flags = flags | 8192;
            }
            if (types[field.record].kind == QueryDescriptorDecl) {
                flags = flags | 4096;
            }
        }
        if (field.component >= 0) {
            component_layout = types[field.component].layout;
        }
        signature := format_text("{}:{}:{}:0:0:{}:{}:{}", field.storage, field.container, nominal, flags,
                                 layout, component_layout);
        shape = (shape ^ binding.ID(field.name, signature)) * 1099511628211;
    }
    return format_text("__query_row_0_{}_{}", start, shape);
}

FindQuery :: (queries: QuerySpec[], node: int) -> int {
    index: int = 0;
    while (index < length(queries)) {
        if (queries[index].node == node) {
            return index;
        }
        index += 1;
    }
    return -1;
}
QueryFieldIndex :: (fields: QueryField[], name: string) -> int {
    index: int = 0;
    while (index < length(fields)) {
        if (fields[index].name == name) {
            return index;
        }
        index += 1;
    }
    return -1;
}
Relationship :: (types: TypeDecl[], name: string) -> int {
    index: int = 0;
    while (index < length(types)) {
        if (types[index].kind == RelationshipDecl && NameMatches(types[index].name, name)) {
            return index;
        }
        index += 1;
    }
    return -1;
}
Ancestor :: (forest: snapshot.SnapshotNode[], ancestor: int, node: int) -> bool {
    at := node;
    while (at >= 0) {
        if (at == ancestor) {
            return true;
        }
        at = forest[at].parent;
    }
    return false;
}
QueryType :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], names: Name[], entity: u64,
              node: int) -> ValueType {
    if (node < 0) {
        return {storage: 0, container: 0, record: -1};
    }
    if (Text(forest, text, node) == "entity") {
        return {storage: HandleStorage, container: 0, record: TypeWithId(types, entity)};
    }
    if (Text(forest, text, node) == "s") {
        return {storage: FloatStorage, container: 0, record: -1};
    }
    if (TypePointerNode(forest, node) < 0 && HasToken(forest, node, "?")) {
        component := Component(types, Text(forest, text, Field(forest, node, "name")));
        index: int = 0;
        while (index < length(types)) {
            if (types[index].kind == OptionalComponentDecl && types[index].parent == component) {
                return {storage: StructStorage, container: 0, record: index};
            }
            index += 1;
        }
    }
    table := types;
    return ReadType(forest, text, &table, names, 0, node);
}
// Type query expressions through the ordinary body emitter. It performs no
// execution; its inferred result follows exactly the same operators, calls,
// indexing, dereferences and aggregate rules as an ordinary local initializer.
QueryValueType :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], members: TypeMember[],
                   callables: Callable[], params: Param[], natives: ResolvedNative[], ports: ResolvedPort[], queries: QuerySpec[],
                   names: Name[], entity: u64, node: int, ops: Ops, target: Target) -> ValueType {
    none: ValueType = {storage: 0, container: 0, record: -1};
    if (node < 0) {
        return none;
    }
    if (Is(forest, node, "query_expression")) {
        found := FindQuery(queries, node);
        if (found >= 0) {
            return {storage: QueryStorage, container: 0, record: queries[found].description};
        }
        return none;
    }
    if (Is(forest, node, "number")) {
        return {storage: StateNumberStorage(forest, text, node), container: 0, record: -1};
    }
    expression: Callable = {name: "", package: document, document: document, node: node, first: 0, count: 0,
                            result: 0, result_container: 0, result_record: -1, results: 0, waits: false};
    functions := append(callables, expression);
    expressions := ops;
    expressions.debug = false;
    table := types;
    switch EmitBody(forest, text, document, functions, params, &table, members, [], natives, ports, [], [], [], [], names,
                    "", SolidOffsets(text), 0, 0, length(functions) - 1, [], [], [], BodyContext.Unknown, [],
                    expressions, target, queries) {
        case .Inferred(value):
            if (value.storage == NumberStorage) {
                return {storage: StateNumberStorage(forest, text, node), container: 0, record: -1};
            }
            return value;
        case .Failed(diagnostic):
            return none;
        case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                      direct_write, facts):
            return none;
    }
}

// QueryScope reconstructs types, not runtime locations. Actual captures use
// the emitter's live names when the description is created.
QueryScopeName :: (forest: snapshot.SnapshotNode[], text: string, node: int, value: ValueType) -> Name {
    return {owned: false, name: Text(forest, text, node), place: LocalPlace, index: 0, storage: value.storage,
            container: value.container, record: value.record, writable: false, node: node};
}
// A positive payload pattern is visible in its matching body and in the
// right side of && after the pattern has matched. It never enters an else.
QueryPatternScope :: (forest: snapshot.SnapshotNode[], text: string, pattern: int, node: int) -> bool {
    if (Field(forest, pattern, "negated") >= 0) {
        return false;
    }
    current := pattern;
    while (forest[current].parent >= 0) {
        parent := forest[current].parent;
        if (Is(forest, parent, "parenthesized_expression")) {
            current = parent;
            continue;
        }
        if (Is(forest, parent, "binary_expression")) {
            operator := Text(forest, text, Field(forest, parent, "operator"));
            if (operator != "&&" && operator != "and") {
                return false;
            }
            if (Ancestor(forest, Field(forest, parent, "left"), current) &&
                Ancestor(forest, Field(forest, parent, "right"), node)) {
                return true;
            }
            current = parent;
            continue;
        }
        if (Field(forest, parent, "condition") != current) {
            return false;
        }
        if (Is(forest, parent, "if_statement")) {
            return Ancestor(forest, Field(forest, parent, "consequence"), node);
        }
        if (Is(forest, parent, "while_statement")) {
            return Ancestor(forest, Field(forest, parent, "body"), node);
        }
        return false;
    }
    return false;
}
QueryPatternNames :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                      names: Name[], subject: ValueType, pattern: int) -> Name[] {
    if (subject.storage != UnionStorage || subject.container != 0 || subject.record < 0 ||
        !Is(forest, pattern, "variant_pattern")) {
        return names;
    }
    variant := FindVariant(types, subject.record, Text(forest, text, Field(forest, pattern, "name")));
    if (variant < 0) {
        return names;
    }
    scoped := names;
    index: int = 0;
    for (binding_node in Members(forest, Field(forest, pattern, "bindings"))) {
        if (index >= types[variant].count) {
            break;
        }
        member := members[types[variant].first + index];
        scoped.append(QueryScopeName(forest, text, binding_node,
                                     {storage: member.storage, container: member.container, record: member.record}));
        index += 1;
    }
    return scoped;
}
// The root of `node`'s source. Each source's nodes follow its root in source
// order, and offsets restart in every source, so a scan for what precedes
// `node` starts here.
QuerySourceRoot :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    root := node;
    while (forest[root].parent >= 0) {
        root = forest[root].parent;
    }
    return root;
}
// Names visible at the query's creation site, in declaration order. Only
// lexical ancestors contribute, so sibling blocks, loops and arms stay out.
QueryScope :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], members: TypeMember[],
               callables: Callable[], params: Param[], natives: ResolvedNative[], ports: ResolvedPort[], queries: QuerySpec[],
               globals: Name[], entity: u64, node: int, ops: Ops, target: Target) -> Name[] {
    names := globals;
    for (callable in callables) {
        if (!Ancestor(forest, Field(forest, callable.node, "body"), node)) {
            continue;
        }
        index: int = 0;
        while (index < callable.count) {
            param := params[callable.first + index];
            name: Name = {owned: false, name: param.name, place: ParameterPlace, index: index, storage: param.storage,
                          container: param.container, record: param.record, writable: false, node: param.node};
            names.append(name);
            index += 1;
        }
    }
    for (described in queries) {
        if (!Is(forest, described.node, "system") || !Ancestor(forest, Field(forest, described.node, "body"), node)) {
            continue;
        }
        for (field in QueryFields(forest, text, types, members, described)) {
            name: Name = {owned: false, name: field.name, place: QueryFieldPlace, index: 0, storage: field.storage,
                          container: field.container, record: field.record, writable: false, node: field.node};
            names.append(name);
        }
    }
    index := QuerySourceRoot(forest, node);
    while (index < length(forest) && forest[index].start < forest[node].start) {
        if (Is(forest, index, "local_declaration") && !Ancestor(forest, index, node)) {
            if (Ancestor(forest, forest[index].parent, node)) {
                value := QueryType(forest, text, types, names, entity, Field(forest, index, "type"));
                if (value.storage == 0) {
                    value = QueryValueType(forest, text, document, types, members, callables, params, natives, ports, queries, names,
                                           entity, Field(forest, index, "value"), ops, target);
                }
                names.append(QueryScopeName(forest, text, Field(forest, index, "name"), value));
            }
        } else if (Is(forest, index, "for_statement") && Ancestor(forest, Field(forest, index, "body"), node)) {
            if (Field(forest, index, "first") >= 0) {
                names.append(QueryScopeName(forest, text, Field(forest, index, "name"),
                                            {storage: IntStorage, container: 0, record: -1}));
            } else {
                iterable := QueryValueType(forest, text, document, types, members, callables, params, natives, ports, queries,
                                           names, entity, Field(forest, index, "value"), ops, target);
                if (iterable.container == MapContainer && iterable.record >= 0) {
                    map := types[iterable.record];
                    names.append(QueryScopeName(forest, text, Field(forest, index, "name"),
                                                {storage: map.value_storage, container: map.value_container, record: map.value_record}));
                    if (Field(forest, index, "key") >= 0) {
                        names.append(QueryScopeName(forest, text, Field(forest, index, "key"),
                                                    {storage: map.key, container: 0, record: -1}));
                    }
                } else if (iterable.container == ArrayContainer) {
                    names.append(QueryScopeName(forest, text, ItemField(forest, index),
                                                {storage: iterable.storage, container: 0, record: iterable.record}));
                    if (Field(forest, index, "key") >= 0) {
                        names.append(QueryScopeName(forest, text, Field(forest, index, "name"),
                                                    {storage: IntStorage, container: 0, record: -1}));
                    }
                } else if (Single(Typed(-1, iterable.storage, iterable.container, iterable.record), QueryStorage)) {
                    if (iterable.record >= 0 && types[iterable.record].kind == QueryDescriptorDecl) {
                        iterable.record = types[iterable.record].parent;
                    }
                    names.append(QueryScopeName(forest, text, Field(forest, index, "name"), iterable));
                }
            }
        } else if (Is(forest, index, "is_expression") && QueryPatternScope(forest, text, index, node)) {
            subject := QueryValueType(forest, text, document, types, members, callables, params, natives, ports, queries, names,
                                      entity, Field(forest, index, "value"), ops, target);
            names = QueryPatternNames(forest, text, types, members, names, subject, Field(forest, index, "type"));
        } else if (Is(forest, index, "switch_arm") && Ancestor(forest, Field(forest, index, "body"), node)) {
            selection := forest[index].parent;
            subject := QueryValueType(forest, text, document, types, members, callables, params, natives, ports, queries, names,
                                      entity, Field(forest, selection, "value"), ops, target);
            names = QueryPatternNames(forest, text, types, members, names, subject, Field(forest, index, "value"));
        }
        index += 1;
    }
    return names;
}

// Header evaluation may read values, but cannot change external storage or
// start work. Follow authored helper calls as well as their immediate native
// calls so moving an effect behind a helper does not evade this restriction.
QueryHelperLocal :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                     name: string, node: int) -> bool {
    owner: int = -1;
    index: int = 0;
    for (callable in callables) {
        if (Ancestor(forest, Field(forest, callable.node, "body"), node) &&
            (owner < 0 || forest[callable.node].start > forest[callables[owner].node].start)) {
            owner = index;
        }
        index += 1;
    }
    if (owner < 0) {
        return false;
    }
    callable := callables[owner];
    index = callable.first;
    while (index < callable.first + callable.count + callable.results) {
        if (params[index].name == name) {
            return true;
        }
        index += 1;
    }
    enclosing := forest[node].parent;
    while (enclosing >= 0) {
        if (Is(forest, enclosing, "query_expression")) {
            if (name == "self") {
                return true;
            }
            for (clause in Members(forest, Field(forest, enclosing, "parameters"))) {
                if (forest[clause].end <= forest[node].start &&
                    Text(forest, text, Field(forest, clause, "name")) == name) {
                    return true;
                }
            }
        }
        enclosing = forest[enclosing].parent;
    }
    index = QuerySourceRoot(forest, node);
    while (index < length(forest) && forest[index].start < forest[node].start) {
        if (Is(forest, index, "local_declaration") &&
            Ancestor(forest, Field(forest, callable.node, "body"), index) &&
            Ancestor(forest, forest[index].parent, node) && !Ancestor(forest, index, node) &&
            Text(forest, text, Field(forest, index, "name")) == name) {
            return true;
        }
        if (Is(forest, index, "for_statement") && Ancestor(forest, Field(forest, index, "body"), node) &&
            (Text(forest, text, Field(forest, index, "name")) == name ||
             Text(forest, text, Field(forest, index, "key")) == name)) {
            return true;
        }
        index += 1;
    }
    return false;
}
QueryImpure :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                natives: ResolvedNative[], names: Name[], root: int, system_header: bool) -> int {
    pending: int[] = [root];
    visited: int[] = [];
    while (length(pending) > 0) {
        node := pending[length(pending) - 1];
        pending = slice(pending, 0, length(pending) - 1);
        if (node < 0) {
            continue;
        }
        if (Is(forest, node, "type") || Is(forest, node, "argument_name")) {
            continue;
        }
        if (Is(forest, node, "identifier") && !Ancestor(forest, root, node) &&
            forest[node].field != "member" && forest[node].field != "function" && forest[node].field != "name") {
            spelling := Text(forest, text, node);
            found := Lookup(names, spelling);
            if (found >= 0 && names[found].place != AliasPlace &&
                !QueryHelperLocal(forest, text, callables, params, spelling, node)) {
                return node;
            }
        }
        if (Is(forest, node, "assignment")) {
            destination := StatementTarget(forest, node);
            base := RootOf(forest, destination);
            name := Text(forest, text, base);
            found := Lookup(names, name);
            own_local := !Ancestor(forest, root, node) && QueryHelperLocal(forest, text, callables, params, name, node);
            if (name == "self" || (found >= 0 && names[found].place == StatePlace && !own_local)) {
                return node;
            }
            for (callable in callables) {
                if (!Ancestor(forest, Field(forest, callable.node, "body"), node)) {
                    continue;
                }
                index: int = 0;
                while (index < callable.count) {
                    param := params[callable.first + index];
                    if (param.name == name && (param.reference || param.storage == PointerStorage)) {
                        return node;
                    }
                    index += 1;
                }
            }
        }
        if (Is(forest, node, "reference_argument")) {
            return node;
        }
        // Literal nested headers validate independently. A helper's nested
        // description can still hide reads, so follow its captures here.
        if (Is(forest, node, "query_expression") && Ancestor(forest, root, node)) {
            continue;
        }
        if (Is(forest, node, "call_expression")) {
            spelling := Text(forest, text, Field(forest, node, "function"));
            for (native in natives) {
                if (NameMatches(native.name, spelling) &&
                    ((native.effects & 62) != 0 || (system_header && (native.effects & 64) != 0))) {
                    return node;
                }
            }
            index: int = 0;
            for (callable in callables) {
                if (callable.name == spelling && Position(visited, index) < 0) {
                    visited.append(index);
                    pending.append(Field(forest, callable.node, "body"));
                }
                index += 1;
            }
        }
        for (child in Members(forest, node)) {
            pending.append(child);
        }
    }
    return -1;
}
QueryExcludes :: (forest: snapshot.SnapshotNode[], text: string, condition: int, membership: string, truth: bool) -> bool {
    node := Unparenthesized(forest, condition);
    if (Is(forest, node, "member_expression")) {
        return !truth && Text(forest, text, node) == membership;
    }
    if (Is(forest, node, "call_expression")) {
        function := Text(forest, text, Field(forest, node, "function"));
        arguments := Members(forest, Field(forest, node, "arguments"));
        if (function == "has" && length(arguments) == 1) {
            return QueryExcludes(forest, text, arguments[0], membership, truth);
        }
        if (function == "not" && length(arguments) == 1) {
            return QueryExcludes(forest, text, arguments[0], membership, !truth);
        }
        if (function != "all" && function != "any") {
            return false;
        }
        either := (truth && function == "all") || (!truth && function == "any");
        result := !either && length(arguments) > 0;
        for (argument in arguments) {
            excluded := QueryExcludes(forest, text, argument, membership, truth);
            if (either) {
                result = result || excluded;
            } else {
                result = result && excluded;
            }
        }
        return result;
    }
    if (Is(forest, node, "unary_expression")) {
        operator := Text(forest, text, Field(forest, node, "operator"));
        return (operator == "!" || operator == "not") &&
               QueryExcludes(forest, text, Field(forest, node, "operand"), membership, !truth);
    }
    if (!Is(forest, node, "binary_expression")) {
        return false;
    }
    operator := Text(forest, text, Field(forest, node, "operator"));
    conjunction := operator == "&&" || operator == "and";
    disjunction := operator == "||" || operator == "or";
    if (!conjunction && !disjunction) {
        return false;
    }
    left := QueryExcludes(forest, text, Field(forest, node, "left"), membership, truth);
    right := QueryExcludes(forest, text, Field(forest, node, "right"), membership, truth);
    if ((truth && conjunction) || (!truth && disjunction)) {
        return left || right;
    }
    return left && right;
}

// A description can construct another description from values bound earlier
// in its header. Collect those dependencies before inferring its row fields.
// Each declaration pass extends copies of its inputs: assigning to a
// parameter would make every caller copy its arguments.
CollectQuery :: (forest: snapshot.SnapshotNode[], text: string, identity: string, document: int, input_types: TypeDecl[],
                 input_members: TypeMember[], input_callables: Callable[], input_params: Param[], natives: ResolvedNative[],
                 ports: ResolvedPort[], input_queries: QuerySpec[], globals: Name[], enclosing: Name[], entity: u64,
                 node: int, system_header: bool, target: Target, ops: Ops) -> QueryDeclarations {
    types := input_types;
    members := input_members;
    callables := input_callables;
    params := input_params;
    queries := input_queries;
    if (FindQuery(queries, node) >= 0) {
        return QueryDeclarations.Collected(types, members, callables, params, queries);
    }
    names := QueryScope(forest, text, document, types, members, callables, params, natives, ports, queries, globals, entity, node, ops, target);
    names.extend(enclosing);
    creation_names := names;
    fields: QueryField[] = [];
    captures: int[] = [];
    variables: int = 0;
    list := Field(forest, node, "parameters");
    for (clause in Members(forest, list)) {
        expression := Field(forest, clause, "value");
        if (Is(forest, clause, "query_guard")) {
            expression = Field(forest, clause, "condition");
        }
        if (expression >= 0) {
            pending: int[] = [expression];
            while (length(pending) > 0) {
                nested := pending[length(pending) - 1];
                pending = slice(pending, 0, length(pending) - 1);
                if (Is(forest, nested, "query_expression")) {
                    scope := enclosing;
                    for (field in fields) {
                        named: Name = {owned: false, name: field.name, place: LocalPlace, index: 0,
                                       storage: field.storage, container: field.container, record: field.record,
                                       writable: false, node: Field(forest, field.node, "name")};
                        scope.append(named);
                    }
                    switch CollectQuery(forest, text, identity, document, types, members, callables, params, natives, ports,
                                        queries, globals, scope, entity, nested, system_header, target, ops) {
                        case .Failed(diagnostic):
                            return QueryDeclarations.Failed(diagnostic);
                        case .Collected(next_types, next_members, next_callables, next_params, next_queries):
                            types = next_types;
                            members = next_members;
                            callables = next_callables;
                            params = next_params;
                            queries = next_queries;
                    }
                    continue;
                }
                for (child in Members(forest, nested)) {
                    pending.append(child);
                }
            }
            impure := QueryImpure(forest, text, callables, params, natives, names, expression, system_header);
            if (impure >= 0) {
                return QueryDeclarations.Failed(Diagnose(forest, impure, document,
                                                         "Query headers require deterministic values without side effects or suspension"));
            }
        }
        if (expression >= 0) {
            pending: int[] = [expression];
            while (length(pending) > 0) {
                part := pending[length(pending) - 1];
                pending = slice(pending, 0, length(pending) - 1);
                if (Is(forest, part, "query_expression")) {
                    continue;
                }
                if (!Is(forest, node, "system") && Is(forest, part, "call_expression") &&
                    Text(forest, text, Field(forest, part, "function")) == "changed") {
                    return QueryDeclarations.Failed(Diagnose(forest, part, document,
                                                             "changed is only available in scheduled system queries"));
                }
                if (Is(forest, part, "address_expression")) {
                    operand := Unparenthesized(forest, Field(forest, part, "operand"));
                    base := RootOf(forest, operand);
                    if (Is(forest, base, "identifier")) {
                        found := Lookup(names, Text(forest, text, base));
                        if (found >= 0 && (names[found].storage != PointerStorage ||
                                           !Is(forest, operand, "member_expression")) &&
                            QueryFieldIndex(fields, names[found].name) < 0) {
                            return QueryDeclarations.Failed(Diagnose(forest, part, document,
                                                                     "Captured query values are read-only; capture an existing pointer instead"));
                        }
                    }
                }
                for (child in Members(forest, part)) {
                    pending.append(child);
                }
            }
        }
        if (Is(forest, clause, "query_guard")) {
            for (field in fields) {
                if (field.component < 0 || field.optional || field.source_relationship != 0) {
                    continue;
                }
                owner := "self";
                for (provider in fields) {
                    if (field.source != 0 && provider.variable == field.source) {
                        owner = provider.name;
                    }
                }
                membership := format_text("{}.{}", owner, types[field.component].name);
                if (QueryExcludes(forest, text, expression, membership, true)) {
                    return QueryDeclarations.Failed(Diagnose(forest, clause, document,
                                                             "A component cannot be both a parameter and excluded"));
                }
            }
            continue;
        }
        name_node := Field(forest, clause, "name");
        name := Text(forest, text, name_node);
        if (Is(forest, node, "system") && name == "dt") {
            return QueryDeclarations.Failed(Diagnose(forest, name_node, document,
                                                     "'dt' is the implicit system step and cannot be a query binding"));
        }
        if (QueryFieldIndex(fields, name) >= 0) {
            return QueryDeclarations.Failed(Diagnose(forest, name_node, document, format_text("Duplicate query binding '{}'", name)));
        }
        annotation := Field(forest, clause, "type");
        typed := QueryType(forest, text, types, names, entity, annotation);
        if (annotation >= 0 && typed.storage == 0) {
            return QueryDeclarations.Failed(Diagnose(forest, annotation, document,
                                                     format_text("Unknown query binding type '{}'", Text(forest, text, annotation))));
        }
        component: int = -1;
        variable: int = 0;
        source: int = 0;
        provider: QueryProvider = {variable: 0, relation: 0, traversal: 0, valid: true};
        if (Is(forest, clause, "query_generator")) {
            if (typed.storage != 0 && (typed.storage != HandleStorage || typed.record != TypeWithId(types, entity))) {
                return QueryDeclarations.Failed(Diagnose(forest, clause, document, "Relationship generator type must be entity"));
            }
            typed = {storage: HandleStorage, container: 0, record: TypeWithId(types, entity)};
            from := Field(forest, clause, "source");
            if (!Is(forest, from, "member_expression")) {
                return QueryDeclarations.Failed(Diagnose(forest, from, document, "Relationship generator requires entity.Relationship"));
            }
            relation := Relationship(types, Text(forest, text, Field(forest, from, "member")));
            if (relation < 0) {
                return QueryDeclarations.Failed(Diagnose(forest, from, document, "Unknown relation type"));
            }
            root_name := Text(forest, text, Field(forest, from, "object"));
            if (root_name != "self") {
                previous := QueryFieldIndex(fields, root_name);
                if (previous < 0 || fields[previous].variable == 0) {
                    return QueryDeclarations.Failed(Diagnose(forest, from, document, "Generator source must be an earlier entity binding"));
                }
                source = fields[previous].variable;
            }
            variables += 1;
            if (variables > 8) {
                return QueryDeclarations.Failed(Diagnose(forest, clause, document, "Query supports at most eight relation variables"));
            }
            variable = variables;
        } else if (Is(forest, clause, "query_binding")) {
            value := Field(forest, clause, "value");
            inferred := QueryValueType(forest, text, document, types, members, callables, params, natives, ports, queries, names, entity, value, ops, target);
            if (typed.storage == 0) {
                typed = inferred;
            }
        } else {
            pointee := typed;
            if (typed.storage == PointerStorage) {
                pointee = PointerElement(types, Typed(-1, typed.storage, 0, typed.record));
            }
            component = pointee.record;
            if (component >= 0 && types[component].kind == OptionalComponentDecl) {
                component = types[component].parent;
            }
            if (pointee.storage != StructStorage || component < 0 || types[component].component == 0) {
                return QueryDeclarations.Failed(Diagnose(forest, clause, document, "Query binding requires a component type"));
            }
            from := Field(forest, clause, "source");
            provider = QuerySource(forest, text, types, fields, from);
            if (!provider.valid) {
                return QueryDeclarations.Failed(Diagnose(forest, from, document,
                                                         "Component source requires an earlier entity binding or an exclusive relationship provider"));
            }
            source = provider.variable;
        }
        if (typed.storage == 0) {
            return QueryDeclarations.Failed(Diagnose(forest, clause, document, "Cannot infer query binding type"));
        }
        field: QueryField = {name: name, node: clause, storage: typed.storage, container: typed.container,
                             record: typed.record, component: component, variable: variable, source: source,
                             source_relationship: provider.relation, source_traversal: provider.traversal,
                             optional: Field(forest, clause, "type") >= 0 && HasToken(forest, Field(forest, clause, "type"), "?")};
        fields.append(field);
        local: Name = {owned: false, name: name, place: LocalPlace, index: length(fields) - 1, storage: typed.storage,
                       container: typed.container, record: typed.record, writable: false, node: name_node};
        names.append(local);
    }
    // Every free value is captured by value at description construction.
    // Member names, type names and function names are declarations, not reads.
    local_names: string[] = ["self"];
    captured_names: string[] = [];
    for (clause in Members(forest, list)) {
        expression := Field(forest, clause, "value");
        if (Is(forest, clause, "query_guard")) {
            expression = Field(forest, clause, "condition");
        }
        if (expression < 0) {
            expression = Field(forest, clause, "source");
        }
        pending: int[] = [];
        if (expression >= 0) {
            pending.append(expression);
        }
        while (length(pending) > 0) {
            item := pending[length(pending) - 1];
            pending = slice(pending, 0, length(pending) - 1);
            if (Is(forest, item, "type") || Is(forest, item, "argument_name")) {
                continue;
            }
            if (Is(forest, item, "query_expression")) {
                nested := FindQuery(queries, item);
                index: int = 0;
                while (nested >= 0 && index < queries[nested].capture_count) {
                    pending.append(params[queries[nested].first_capture + index].node);
                    index += 1;
                }
                continue;
            }
            if (Is(forest, item, "identifier") && forest[item].field != "member" &&
                forest[item].field != "function" && forest[item].field != "name") {
                spelling := Text(forest, text, item);
                if (!Holds(local_names, spelling) && !Holds(captured_names, spelling)) {
                    found := Lookup(creation_names, spelling);
                    if (found >= 0 && creation_names[found].place != AliasPlace) {
                        if (system_header && Lookup(enclosing, spelling) < 0) {
                            return QueryDeclarations.Failed(Diagnose(forest, item, document,
                                                                     "System query headers cannot capture invocation values or retained state"));
                        }
                        captured_names.append(spelling);
                        captures.append(item);
                    }
                }
            }
            for (child in Members(forest, item)) {
                pending.append(child);
            }
        }
        declared_name := Field(forest, clause, "name");
        if (declared_name >= 0) {
            local_names.append(Text(forest, text, declared_name));
        }
    }
    row := length(types);
    first := length(members);
    for (field in fields) {
        member: TypeMember = {name: field.name, storage: field.storage, container: field.container, record: field.record,
                              offset: field.source, writable: false, c_string: field.optional, constant: false, read: field.node, read_key: ""};
        members.append(member);
    }
    row_name := QueryRowName(types, fields, forest[node].start);
    id := binding.ID(identity, row_name);
    declared: TypeDecl = {name: "", type_name: row_name, package: document, node: node, kind: QueryDecl,
                          first: first, count: length(fields), size: target.pointer_size, parent: -1,
                          storage: QueryStorage, id: id, layout: 0, component: 0, key: 0, value_storage: 0,
                          value_container: 0, value_record: -1};
    types.append(declared);
    // A literal again: a copy of `declared` shares its u64 id, and writing
    // into that copy would make every caller copy its arguments.
    description: TypeDecl = {name: "", type_name: row_name, package: document, node: node, kind: QueryDescriptorDecl,
                             first: first, count: length(fields), size: target.pointer_size, parent: row,
                             storage: QueryStorage, id: id, layout: 0, component: 0, key: 0, value_storage: 0,
                             value_container: 0, value_record: -1};
    descriptor := length(types);
    types.append(description);
    param_first := length(params);
    for (capture in captures) {
        found := Lookup(creation_names, Text(forest, text, capture));
        named := creation_names[found];
        param: Param = {name: named.name, storage: named.storage, container: named.container, record: named.record,
                        has_default: false, default_bits: 0, default_text: "", default_occurrence: 0,
                        reference: false, node: capture};
        params.append(param);
    }
    accepted: Param = {name: "", storage: BoolStorage, container: 0, record: -1, has_default: false,
                       default_bits: 0, default_text: "", default_occurrence: 0, reference: false, node: node};
    params.append(accepted);
    for (field in fields) {
        result: Param = {name: "", storage: field.storage, container: field.container, record: field.record,
                         has_default: false, default_bits: 0, default_text: "", default_occurrence: 0,
                         reference: false, node: field.node};
        params.append(result);
    }
    evaluator := length(callables);
    // Evaluators are numbered within their source, as each compiles alone.
    numbered: int = 0;
    for (collected in queries) {
        if (callables[collected.evaluator].document == document) {
            numbered += 1;
        }
    }
    callable: Callable = {name: format_text("__query_evaluate_{}", numbered), package: document, document: document,
                          node: node, first: param_first, count: length(captures), result: 0,
                          result_container: 0, result_record: -1, results: length(fields) + 1, waits: false};
    callables.append(callable);
    described: QuerySpec = {node: node, evaluator: evaluator, row: row, description: descriptor, variables: variables,
                            first_capture: param_first, capture_count: length(captures)};
    queries.append(described);
    return QueryDeclarations.Collected(types, members, callables, params, queries);
}
// Collects the queries of the source whose nodes are [node_start, node_end),
// after the ones already collected.
CollectQueries :: (forest: snapshot.SnapshotNode[], text: string, identity: string, document: int, node_start: int,
                   node_end: int, input_types: TypeDecl[], input_members: TypeMember[], input_callables: Callable[],
                   input_params: Param[], natives: ResolvedNative[], ports: ResolvedPort[], input_queries: QuerySpec[],
                   globals: Name[], entity: u64, target: Target, ops: Ops) -> QueryDeclarations {
    types := input_types;
    members := input_members;
    callables := input_callables;
    params := input_params;
    queries := input_queries;
    node := node_start;
    while (node < node_end) {
        if (forest[node].is_named && (Is(forest, node, "query_expression") ||
                                      (Is(forest, node, "system") && length(Members(forest, Field(forest, node, "parameters"))) > 0))) {
            switch CollectQuery(forest, text, identity, document, types, members, callables, params, natives, ports,
                                queries, globals, [], entity, node, Is(forest, node, "system"), target, ops) {
                case .Failed(diagnostic):
                    return QueryDeclarations.Failed(diagnostic);
                case .Collected(next_types, next_members, next_callables, next_params, next_queries):
                    types = next_types;
                    members = next_members;
                    callables = next_callables;
                    params = next_params;
                    queries = next_queries;
            }
        }
        node += 1;
    }
    return QueryDeclarations.Collected(types, members, callables, params, queries);
}

// Intrinsic calls keep one typed cell per argument and result. A slot of -2
// asks for the execution context; a slot of -1 leaves the header's constant.
QueryCallStep :: (intrinsic: int, arguments: Value[], initial: Cell[], result: ValueType, popped: int,
                  ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    cells := initial;
    output_cell: Cell = {storage: result.storage, container: result.container, record: result.record,
                         constant: 0, variant: -1, kind: ValueKind};
    cells.append(output_cell);
    code: Code[] = [];
    slots: Slot[] = [];
    index: int = 0;
    for (argument in arguments) {
        value := argument.slot;
        if (value == -2) {
            context_cell := cells[index];
            context_cell.kind = AddressKind;
            cells[index] = context_cell;
            slots.append(AddressSlot(target));
            value = at.slot + length(slots) - 1;
            code.append(Instruction(ops.context, target.pointer_storage, value, 0, 0, 1, node));
        }
        if (value >= 0) {
            stored := argument;
            stored.slot = value;
            code.extend(ValueWriteCode(stored, at.cell + index, ops, target, at.slot + length(slots), node));
            slots.append(AddressSlot(target));
        }
        index += 1;
    }
    host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: at.cell + length(initial),
                  result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    storage := SlotStorage(result.storage, result.container, target);
    code.extend(CellRead(storage, at.cell + length(initial), ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    output_slot: Slot = {storage: storage, kind: SlotKind(result.storage, result.container)};
    slots.append(output_slot);
    produced := Typed(at.slot + length(slots) - 1, result.storage, result.container, result.record);
    roots: Root[] = [];
    if (Pointer(result.storage, result.container)) {
        root: Root = {slot: produced.slot, storage: result.storage, container: result.container, record: result.record};
        roots.append(root);
    }
    return CellSchemaStep(Step.Emitted(code, slots, [], cells, [host], roots, [], [], [], popped, produced, NoValue(), []),
                          at.cell + length(initial), ops, target, at, node);
}
QueryCell :: (storage: int, record: int, bits: u64) -> Cell {
    return {storage: storage, container: 0, record: record, constant: bits, variant: -1, kind: ValueKind};
}
QueryCurrentStep :: (record: int, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    return QueryCallStep(QueryCurrentIntrinsic, [Typed(-2, target.pointer_storage, 0, -1)],
                         [QueryCell(target.pointer_storage, -1, 0)],
                         {storage: QueryStorage, container: 0, record: record}, 0, ops, target, at, node);
}
QueryChangedStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], members: TypeMember[],
                     params: Param[], queries: QuerySpec[], item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    base: int = 0;
    for (described in queries) {
        terms := QueryTerms(forest, text, types, members, params, described);
        index: int = 0;
        for (term in terms) {
            if (term.node == item.node && term.kind == 7) {
                return QueryCallStep(QueryTestIntrinsic,
                                     [Typed(-2, target.pointer_storage, 0, -1), Typed(-1, IntStorage, 0, -1)],
                                     [QueryCell(target.pointer_storage, -1, 0), QueryCell(IntStorage, -1, u64(base + index))],
                                     {storage: BoolStorage, container: 0, record: -1}, 0, ops, target, at, forest[item.node]);
            }
            index += 1;
        }
        base += length(terms) + 1;
    }
    return Fail(forest, item.node, document, "changed requires a component in a scheduled system query guard");
}
QueryGetStep :: (row: Value, index: int, field: ValueType, popped: int, ops: Ops, target: Target,
                 at: Bases, node: snapshot.SnapshotNode) -> Step {
    return QueryCallStep(QueryGetIntrinsic, [row, Typed(-1, IntStorage, 0, -1)],
                         [QueryCell(QueryStorage, row.record, 0), QueryCell(IntStorage, -1, u64(index))],
                         field, popped, ops, target, at, node);
}

// Cache an immutable aggregate's payload before later guards introduce
// branches. Its original header stays in the data bank for schema publication.
QuerySnapshotHeader :: (names: Name[], name: string) -> int {
    index := length(names) - 1;
    while (index >= 0) {
        if (names[index].place == QuerySnapshotHeaderPlace && names[index].name == name) {
            return names[index].index;
        }
        index -= 1;
    }
    return -1;
}
QuerySnapshotReadStep :: (binding: Name, names: Name[], ops: Ops, target: Target, at: Bases,
                          node: snapshot.SnapshotNode) -> Step {
    code := [Instruction(ops.local, target.pointer_storage, at.slot, binding.index, 0, 0, node)];
    root: Root = {slot: at.slot, storage: binding.storage, container: binding.container, record: binding.record};
    read := Step.Emitted(code, [AddressSlot(target)], [], [], [], [root], [], [], [], 0,
                         Typed(at.slot, binding.storage, binding.container, binding.record), NoValue(), []);
    return CellSchemaStep(read, QuerySnapshotHeader(names, binding.name), ops, target, at, node);
}

QueryReadonlyDestination :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                             names: Name[], destination: int) -> bool {
    root := destination;
    first: int = -1;
    while (Is(forest, root, "member_expression")) {
        first = root;
        root = Field(forest, root, "object");
    }
    if (!Is(forest, root, "identifier")) {
        return false;
    }
    found := Lookup(names, Text(forest, text, root));
    if (found < 0) {
        return false;
    }
    bound := names[found];
    if (bound.place == QueryFieldPlace) {
        return bound.storage != PointerStorage || root == destination;
    }
    if (bound.storage != QueryStorage || bound.record < 0) {
        return false;
    }
    if (first < 0) {
        return true;
    }
    field := FindField(types, members, bound.record, Text(forest, text, Field(forest, first, "member")));
    if (field < 0) {
        return false;
    }
    return members[field].storage != PointerStorage || first == destination;
}

QueryAccessPresent :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], names: Name[], expression: int) -> bool {
    spelling := Text(forest, text, expression);
    binding: Name = {owned: false, name: spelling, place: LocalPlace, index: 0, storage: 0, container: 0, record: -1,
                     writable: false, node: -1};
    if (PointerPresent(forest, text, binding, expression)) {
        return true;
    }
    declaration := expression;
    field_name := spelling;
    if (Is(forest, expression, "member_expression")) {
        object := Field(forest, expression, "object");
        if (Is(forest, object, "identifier")) {
            found := Lookup(names, Text(forest, text, object));
            if (found >= 0 && names[found].storage == QueryStorage && names[found].record >= 0) {
                declaration = types[names[found].record].node;
                field_name = Text(forest, text, Field(forest, expression, "member"));
            }
        }
    }
    at := declaration;
    while (at >= 0) {
        if (Is(forest, at, "query_expression") || Is(forest, at, "system")) {
            for (clause in Members(forest, Field(forest, at, "parameters"))) {
                if (Is(forest, clause, "query_guard") &&
                    (declaration != expression || forest[clause].end <= forest[expression].start) &&
                    PointerGuard(forest, text, Field(forest, clause, "condition"), field_name, true)) {
                    return true;
                }
            }
            return false;
        }
        at = forest[at].parent;
    }
    return false;
}

QueryEvaluator :: (queries: QuerySpec[], function: int) -> int {
    index: int = 0;
    while (index < length(queries)) {
        if (queries[index].evaluator == function) {
            return index;
        }
        index += 1;
    }
    return -1;
}
QueryNames :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
               described: QuerySpec) -> Name[] {
    names: Name[] = [];
    index: int = 0;
    for (field in QueryFields(forest, text, types, members, described)) {
        name: Name = {owned: false, name: field.name, place: QueryFieldPlace, index: index, storage: field.storage,
                      container: field.container, record: field.record, writable: false, node: field.node};
        names.append(name);
        index += 1;
    }
    return names;
}
QueryFieldRow :: (types: TypeDecl[], members: TypeMember[], node: int) -> int {
    row: int = 0;
    for (declared in types) {
        if (declared.kind == QueryDecl) {
            field := declared.first;
            while (field < declared.first + declared.count) {
                if (members[field].read == node) {
                    return row;
                }
                field += 1;
            }
        }
        row += 1;
    }
    return -1;
}
QueryFieldReadPhase: int : 67;
QueryPresencePhase: int : 68;
QueryGuardContext :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    at := node;
    while (at >= 0) {
        if (Is(forest, at, "query_guard")) {
            return true;
        }
        if (Is(forest, at, "query_binding") || Is(forest, at, "block") ||
            Is(forest, at, "callable_body") || Is(forest, at, "system_body")) {
            return false;
        }
        at = forest[at].parent;
    }
    return false;
}
QueryGuardFunction :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> bool {
    if (!Is(forest, node, "call_expression") || !QueryGuardContext(forest, node)) {
        return false;
    }
    function := Text(forest, text, Field(forest, node, "function"));
    return function == "all" || function == "any" || function == "not";
}
QueryMembership :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                    params: Param[], described: QuerySpec, node: int) -> QueryTerm {
    fields: QueryField[] = [];
    for (field in QueryFields(forest, text, types, members, described)) {
        if (forest[field.node].start < forest[node].start) {
            fields.append(field);
        }
    }
    captured: string[] = [];
    index := described.first_capture;
    while (index < described.first_capture + described.capture_count) {
        captured.append(params[index].name);
        index += 1;
    }
    terms := QueryGuardTerms(forest, text, types, fields, captured, node);
    if (length(terms) == 1 && (terms[0].kind == 0 || terms[0].kind == 4)) {
        return terms[0];
    }
    return QueryLeaf(-1, 0, 0, 0, 0, 0, node);
}
QueryMembershipStep :: (term: QueryTerm, values: Value[], top: int, item: Work, ops: Ops, target: Target,
                        at: Bases, node: snapshot.SnapshotNode) -> Step {
    if (item.phase == QueryMembershipPhase) {
        code: Code[] = [ConstantCode(ops, HandleStorage, 0, at.slot, node),
                        Instruction(ops.ne, HandleStorage, at.slot + 1, values[top - 1].slot, at.slot, -1, node)];
        return Step.Emitted(code, [ValueLocal(HandleStorage), ValueLocal(BoolStorage)], [], [], [], [], [], [], [],
                            1, Typed(at.slot + 1, BoolStorage, 0, -1), NoValue(), []);
    }
    owner := Instruction(ops.owner, HandleStorage, at.slot, 0, 0, 0, node);
    if (term.source_variable != 0) {
        owner = Instruction(ops.query_variable, HandleStorage, at.slot, 0, 0, term.source_variable, node);
    }
    arguments: Value[] = [Typed(-2, target.pointer_storage, 0, -1), Typed(at.slot, HandleStorage, 0, -1),
                          Typed(-1, WordStorage, 0, -1)];
    initial: Cell[] = [QueryCell(target.pointer_storage, -1, 0), QueryCell(HandleStorage, -1, 0),
                       QueryCell(WordStorage, -1, term.component)];
    intrinsic: int = 19;
    if (term.kind == 4) {
        intrinsic = 23;
        arguments.append(Typed(-1, IntStorage, 0, -1));
        initial.append(QueryCell(IntStorage, -1, 0));
    } else {
        arguments.append(Typed(-1, WordStorage, 0, -1));
        arguments.append(Typed(-1, IntStorage, 0, -1));
        initial.append(QueryCell(WordStorage, -1, term.source_relationship));
        initial.append(QueryCell(IntStorage, -1, u64(term.source_traversal)));
    }
    return PointerContinue(PointerPrefix([owner], [ValueLocal(HandleStorage)],
                                         QueryCallStep(intrinsic, arguments, initial, {storage: HandleStorage, container: 0, record: -1},
                                                       0, ops, target, SlotsPast(at, 1), node)), Resume(item.node, QueryMembershipPhase, 0, 0));
}
QueryBooleanPosition :: (forest: snapshot.SnapshotNode[], text: string, expression: int) -> bool {
    node := expression;
    while (node >= 0 && forest[node].parent >= 0) {
        parent := forest[node].parent;
        if (Is(forest, parent, "parenthesized_expression")) {
            node = parent;
            continue;
        }
        if (Is(forest, parent, "query_guard") || Is(forest, parent, "if_statement") ||
            Is(forest, parent, "while_statement")) {
            return Field(forest, parent, "condition") == node;
        }
        if (Is(forest, parent, "argument_list")) {
            call := forest[parent].parent;
            function := Text(forest, text, Field(forest, call, "function"));
            if (function != "has" && function != "all" && function != "any" && function != "not") {
                return false;
            }
            return QueryGuardContext(forest, call);
        }
        operator := Text(forest, text, Field(forest, parent, "operator"));
        if (Is(forest, parent, "unary_expression")) {
            return operator == "!" || operator == "not";
        }
        return Is(forest, parent, "binary_expression") &&
               (operator == "&&" || operator == "and" || operator == "||" || operator == "or");
    }
    return false;
}
// Nullable components use the same presence conversion in a header guard,
// a body condition and a short-circuit operand.
QueryBooleanStep :: (types: TypeDecl[], step: Step, ops: Ops, target: Target, at: Bases,
                     node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, value, retained, marks):
            storage := value.storage;
            if (value.container != 0 || value.record < 0 ||
                (storage != PointerStorage && (storage != StructStorage || types[value.record].kind != OptionalComponentDecl))) {
                return step;
            }
            if (storage == StructStorage) {
                storage = target.pointer_storage;
            }
            null_slot := at.slot + length(slots);
            output := null_slot + 1;
            null_value := ConstantCode(ops, storage, 0, null_slot, node);
            if (storage == PointerStorage) {
                null_value.value_record = value.record;
            }
            rewritten := append(code, null_value);
            rewritten.append(Instruction(ops.ne, storage, output, value.slot, null_slot, -1, node));
            null_type := AddressSlot(target);
            if (storage == PointerStorage) {
                null_type = ValueLocal(PointerStorage);
            }
            added := append(slots, null_type);
            added.append(ValueLocal(BoolStorage));
            return Step.Emitted(rewritten, added, locals, cells, hosts, roots, calls, bound, next, popped,
                                Typed(output, BoolStorage, 0, -1), retained, marks);
    }
}
// A component name in a Boolean position is a membership test. Selecting a
// field of the component still reads its value and may require a prior guard.
QueryPresence :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], names: Name[], node: int) -> int {
    if (!Is(forest, node, "member_expression")) {
        return -1;
    }
    component := Component(types, Text(forest, text, Field(forest, node, "member")));
    if (component < 0) {
        return -1;
    }
    owner := Field(forest, node, "object");
    if (!Is(forest, owner, "identifier")) {
        return -1;
    }
    found := Lookup(names, Text(forest, text, owner));
    if (found < 0 || names[found].storage != HandleStorage) {
        return -1;
    }
    parent := forest[node].parent;
    if (Is(forest, parent, "query_guard") || Is(forest, parent, "if_statement") || Is(forest, parent, "while_statement")) {
        return component;
    }
    if (Is(forest, parent, "unary_expression")) {
        operator := Text(forest, text, Field(forest, parent, "operator"));
        if (operator == "!" || operator == "not") {
            return component;
        }
    }
    if (Is(forest, parent, "binary_expression")) {
        operator := Text(forest, text, Field(forest, parent, "operator"));
        if (operator == "&&" || operator == "||" || operator == "and" || operator == "or") {
            return component;
        }
    }
    return -1;
}
QueryPresenceStep :: (forest: snapshot.SnapshotNode[], types: TypeDecl[], component: int, values: Value[], top: int,
                      item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    if (item.phase == 0) {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [Visit(Field(forest, item.node, "object")), Resume(item.node, QueryPresencePhase, component, 0)],
                            0, NoValue(), NoValue(), []);
    }
    return QueryCallStep(9,
                         [Typed(-2, target.pointer_storage, 0, -1), values[top - 1], Typed(-1, WordStorage, 0, -1)],
                         [QueryCell(target.pointer_storage, -1, 0), QueryCell(HandleStorage, -1, 0),
                          QueryCell(WordStorage, -1, types[component].component)],
                         {storage: BoolStorage, container: 0, record: -1}, 1, ops, target, at, forest[item.node]);
}
QueryFieldReadStep :: (binding: Name, row: int, values: Value[], top: int, item: Work, ops: Ops, target: Target,
                       at: Bases, node: snapshot.SnapshotNode) -> Step {
    if (item.phase == 0) {
        return PointerContinue(QueryCurrentStep(row, ops, target, at, node),
                               Resume(item.node, QueryFieldReadPhase, 0, 0));
    }
    return QueryGetStep(values[top - 1], binding.index,
                        {storage: binding.storage, container: binding.container, record: binding.record},
                        1, ops, target, at, node);
}

QueryExpressionStep :: (forest: snapshot.SnapshotNode[], document: int, params: Param[], queries: QuerySpec[], values: Value[], top: int,
                        item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    index := FindQuery(queries, item.node);
    if (index < 0) {
        return Fail(forest, item.node, document, "Query description was not declared");
    }
    described := queries[index];
    if (item.phase == 0) {
        next: Work[] = [];
        index: int = 0;
        while (index < described.capture_count) {
            capture := Visit(params[described.first_capture + index].node);
            capture.capture = true;
            next.append(capture);
            index += 1;
        }
        next.append(Resume(item.node, QueryMakePhase, 0, 0));
        return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
    }
    arguments: Value[] = [Typed(-2, target.pointer_storage, 0, -1), Typed(-1, IntStorage, 0, -1)];
    initial: Cell[] = [QueryCell(target.pointer_storage, -1, 0), QueryCell(IntStorage, -1, u64(index))];
    first := top - described.capture_count;
    at_capture: int = 0;
    while (at_capture < described.capture_count) {
        capture := values[first + at_capture];
        arguments.append(capture);
        captured_cell: Cell = {storage: capture.storage, container: capture.container, record: capture.record,
                               constant: 0, variant: -1, kind: ValueKind};
        initial.append(captured_cell);
        at_capture += 1;
    }
    return QueryCallStep(QueryMakeIntrinsic, arguments, initial,
                         {storage: QueryStorage, container: 0, record: described.description},
                         described.capture_count, ops, target, at, node);
}

// A component's provider is selected by the structural row. Values snapshot
// the provider here; pointers retain its checked ECS identity through removal,
// migration and suspension, using the same managed-pointer capability as native.
QueryOwnedComponentStep :: (types: TypeDecl[], field: QueryField, entity: Value, popped: int, ops: Ops,
                            target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    arguments: Value[] = [Typed(-2, target.pointer_storage, 0, -1), entity,
                          Typed(-1, WordStorage, 0, -1), Typed(-1, StructStorage, 0, field.component),
                          Typed(-1, WordStorage, 0, -1), Typed(-1, WordStorage, 0, -1)];
    initial: Cell[] = [QueryCell(target.pointer_storage, -1, 0), QueryCell(HandleStorage, -1, 0),
                       QueryCell(WordStorage, -1, types[field.component].component), QueryCell(StructStorage, field.component, 0),
                       QueryCell(WordStorage, -1, types[field.component].layout),
                       QueryCell(WordStorage, -1, u64(types[field.component].size))];
    intrinsic := ComponentPointerIntrinsic;
    if (field.storage == StructStorage) {
        intrinsic = ComponentSnapshotIntrinsic;
    }
    return QueryCallStep(intrinsic, arguments, initial,
                         {storage: field.storage, container: 0, record: field.record}, popped,
                         ops, target, at, node);
}
QueryComponentStep :: (forest: snapshot.SnapshotNode[], types: TypeDecl[], field: QueryField, ops: Ops,
                       target: Target, at: Bases) -> Step {
    node := forest[field.node];
    source := Instruction(ops.owner, HandleStorage, at.slot, 0, 0, 0, node);
    if (field.source != 0) {
        source = Instruction(ops.query_variable, HandleStorage, at.slot, 0, 0, field.source, node);
    }
    source_slots: Slot[] = [ValueLocal(HandleStorage)];
    entity := Typed(at.slot, HandleStorage, 0, -1);
    if (field.source_relationship == 0) {
        return PointerPrefix([source], source_slots,
                             QueryOwnedComponentStep(types, field, entity, 0, ops, target, SlotsPast(at, 1), node));
    }
    arguments: Value[] = [Typed(-2, target.pointer_storage, 0, -1), entity,
                          Typed(-1, WordStorage, 0, -1), Typed(-1, WordStorage, 0, -1),
                          Typed(-1, IntStorage, 0, -1)];
    initial: Cell[] = [QueryCell(target.pointer_storage, -1, 0), QueryCell(HandleStorage, -1, 0),
                       QueryCell(WordStorage, -1, types[field.component].component),
                       QueryCell(WordStorage, -1, field.source_relationship),
                       QueryCell(IntStorage, -1, u64(field.source_traversal))];
    return PointerPrefix([source], source_slots,
                         QueryCallStep(19, arguments, initial, {storage: HandleStorage, container: 0, record: -1}, 0,
                                       ops, target, SlotsPast(at, 1), node));
}

QueryEvaluateStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                      queries: QuerySpec[], described: QuerySpec, members: TypeMember[], names: Name[], values: Value[], top: int,
                      item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    kind := node.kind;
    if (item.node == described.node && item.phase == 0) {
        next: Work[] = [];
        for (clause in Members(forest, Field(forest, item.node, "parameters"))) {
            next.append(Visit(clause));
        }
        next.append(Resume(item.node, QueryFinishPhase, 0, 0));
        return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
    }
    if (item.phase == QueryFinishPhase) {
        code: Code[] = [ConstantCode(ops, BoolStorage, 1, at.slot, node),
                        Instruction(ops.result, BoolStorage, 0, at.slot, 0, 0, node)];
        next: Work[] = [];
        index: int = 0;
        for (field in QueryFields(forest, text, types, members, described)) {
            next.append(Visit(Field(forest, field.node, "name")));
            next.append(Resume(field.node, QueryReturnPhase, index + 1, 0));
            index += 1;
        }
        next.append(Resume(item.node, QueryFinishPhase, 0, 1));
        if (item.b != 0) {
            return Step.Emitted([Instruction(ops.finish, 0, 0, 0, 0, 0, node)], [], [], [], [], [], [], [], [],
                                0, NoValue(), NoValue(), []);
        }
        return Step.Emitted(code, [ValueLocal(BoolStorage)], [], [], [], [], [], [], next,
                            0, NoValue(), NoValue(), []);
    }
    if (item.phase == QueryReturnPhase) {
        value := values[top - 1];
        storage := SlotStorage(value.storage, value.container, target);
        // Stored result headers are already typed. Writing their payload
        // preserves nominal identity, array shape and authored layout.
        code: Code[] = [];
        slots: Slot[] = [];
        if (Pointer(value.storage, value.container)) {
            name := Text(forest, text, Field(forest, item.node, "name"));
            header := QuerySnapshotHeader(names, name);
            slots.append(AddressSlot(target));
            code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot, header, 0, 0, node));
            slots.append(AddressSlot(target));
            context := Instruction(ops.context, target.pointer_storage, at.slot + 1, 0, 0, 0, node);
            context.offset = target.results_offset;
            code.append(context);
            slots.append(ValueLocal(IntStorage));
            code.append(ConstantCode(ops, IntStorage, u64(item.a), at.slot + 2, node));
            slots.append(AddressSlot(target));
            indexed := Instruction(ops.index, target.pointer_storage, at.slot + 3, at.slot + 1, at.slot + 2, 0, node);
            indexed.offset = target.value_size;
            code.append(indexed);
            offsets: int[] = [target.type_offset, target.container_offset, target.name_offset,
                              target.record_offset, target.schema_offset, target.payload_offset];
            part: int = 0;
            for (offset in offsets) {
                copied := AddressSlot(target);
                if (part < 2) {
                    copied = ValueLocal(IntStorage);
                }
                slots.append(copied);
                load := Instruction(ops.load, copied.storage, at.slot + length(slots) - 1, at.slot, 0, 0, node);
                load.offset = offset;
                code.append(load);
                write := Instruction(ops.write, copied.storage, 0, at.slot + length(slots) - 1, at.slot + 3, 0, node);
                write.offset = offset;
                code.append(write);
                part += 1;
            }
        } else {
            context := Instruction(ops.context, target.pointer_storage, at.slot, 0, 0, 0, node);
            context.offset = target.results_offset;
            code.append(context);
            code.append(ConstantCode(ops, IntStorage, u64(item.a), at.slot + 1, node));
            indexed := Instruction(ops.index, target.pointer_storage, at.slot + 2, at.slot, at.slot + 1, 0, node);
            indexed.offset = target.value_size;
            code.append(indexed);
            write := Instruction(ops.write, value.storage, 0, value.slot, at.slot + 2, 0, node);
            write.offset = target.payload_offset;
            code.append(write);
            slots = [AddressSlot(target), ValueLocal(IntStorage), AddressSlot(target)];
        }
        return Step.Emitted(code, slots, [], [], [], [], [], [], [], 1, NoValue(), NoValue(), []);
    }
    if (kind == "query_guard") {
        if (item.phase == 0) {
            return Step.Emitted([], [], [], [], [], [], [], [],
                                [Expect(Field(forest, item.node, "condition"), BoolStorage, 0, -1),
                                 Resume(item.node, QueryGuardPhase, 0, 0)], 0, NoValue(), NoValue(), []);
        }
        condition := values[top - 1];
        if (!Single(condition, BoolStorage)) {
            return Fail(forest, item.node, document, "Query if condition must be bool");
        }
        code: Code[] = [Instruction(ops.branch_if, 0, 0, condition.slot, 0, at.pc + 4, node),
                        ConstantCode(ops, BoolStorage, 0, at.slot, node),
                        Instruction(ops.result, BoolStorage, 0, at.slot, 0, 0, node),
                        Instruction(ops.finish, 0, 0, 0, 0, 0, node)];
        return Step.Emitted(code, [ValueLocal(BoolStorage)], [], [], [], [], [], [], [], 1, NoValue(), NoValue(), []);
    }
    fields := QueryFields(forest, text, types, members, described);
    index := QueryFieldIndex(fields, Text(forest, text, Field(forest, item.node, "name")));
    if (index < 0) {
        return Fail(forest, item.node, document, "Unknown query field");
    }
    field := fields[index];
    if (item.phase == 0) {
        if (kind == "query_binding") {
            return Step.Emitted([], [], [], [], [], [], [], [],
                                [Expect(Field(forest, item.node, "value"), field.storage, field.container, field.record),
                                 Resume(item.node, QueryBindPhase, 0, 0)], 0, NoValue(), NoValue(), []);
        }
        if (kind == "query_generator") {
            variable := Instruction(ops.query_variable, HandleStorage, at.slot, 0, 0, field.variable, node);
            return Step.Emitted([variable], [ValueLocal(HandleStorage)], [], [], [], [], [], [],
                                [Resume(item.node, QueryBindPhase, 0, 0)], 0,
                                Typed(at.slot, HandleStorage, 0, field.record), NoValue(), []);
        }
        phase := QueryBindPhase;
        if (field.source_relationship != 0) {
            phase = QueryProviderPhase;
        }
        return PointerContinue(QueryComponentStep(forest, types, field, ops, target, at),
                               Resume(item.node, phase, 0, 0));
    }
    if (item.phase == QueryProviderPhase) {
        return PointerContinue(QueryOwnedComponentStep(types, field, values[top - 1], 1, ops, target, at, node),
                               Resume(item.node, QueryBindPhase, 0, 0));
    }
    value := values[top - 1];
    if (!Accepts(types, field.storage, field.container, field.record, value)) {
        return Fail(forest, item.node, document, "Query binding value differs from its type");
    }
    bound: Name = {owned: false, name: field.name, place: LocalPlace, index: at.local, storage: field.storage,
                   container: field.container, record: field.record, writable: false,
                   node: Field(forest, item.node, "name")};
    if (Pointer(field.storage, field.container)) {
        header := bound;
        header.place = QuerySnapshotHeaderPlace;
        header.index = at.cell - 1;
        bound.place = QuerySnapshotPlace;
        code: Code[] = [];
        slots: Slot[] = [];
        cells: Cell[] = [];
        if (field.component < 0) {
            header.index = at.cell;
            code = MoveCode(value, ops, target, at.slot, at.cell, node);
            slots.append(AddressSlot(target));
            cells.append(MovedCell(value));
        }
        code.append(Instruction(ops.save, target.pointer_storage, 0, value.slot, 0, at.local, node));
        return Step.Emitted(code, slots, [AddressSlot(target)], cells, [], [], [], [header, bound], [],
                            1, NoValue(), NoValue(), []);
    }
    code: Code[] = [Instruction(ops.save, field.storage, 0, value.slot, 0, at.local, node)];
    return Step.Emitted(code, [], [ValueLocal(field.storage)], [], [], [], [], [bound], [], 1, NoValue(), NoValue(), []);
}
package package_compiler

import snapshot "project:source_snapshot"

// A query cursor is an invocation-owned pointer, with provenance distinct
// from a numeric word, a managed pointer and a component reference.
QueryCursorKind: int : 4;
QueryCursorSlot :: (target: Target) -> Slot {
    return {storage: target.pointer_storage, kind: QueryCursorKind};
}

// Start one independent cursor, then emit its loop head and first NEXT. The
// caller has already popped the description. NEXT yields acceptance followed
// by the row; a false result jumps to the pending exit before reading the row.
// Marks are [head, exit_jump, cursor_local, row_local]. The body binds the row
// name until the loop exits and jumps back to head after each iteration.
QueryIteratorStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                      description: Value, item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    if (!Single(description, QueryStorage) || description.record < 0 || types[description.record].kind != QueryDescriptorDecl) {
        return Fail(forest, item.node, document, "for requires a query description");
    }
    if (Field(forest, item.node, "reverse") >= 0) {
        return Fail(forest, item.node, document, "Query iteration does not support reverse order");
    }
    if (Field(forest, item.node, "key") >= 0) {
        return Fail(forest, item.node, document, "Query iteration binds one row name");
    }
    name_node := Field(forest, item.node, "name");
    row_type := types[description.record].parent;
    name := Text(forest, text, name_node);
    if (name == "") {
        return Fail(forest, name_node, document, "Invalid string or embedded NUL");
    }
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [{storage: target.pointer_storage, kind: QueryCursorKind}, ValueLocal(QueryStorage)];
    cells: Cell[] = [
        {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: AddressKind},
        QueryCell(QueryStorage, description.record, 0),
        {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: QueryCursorKind},
        {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: AddressKind},
        {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: QueryCursorKind},
        QueryCell(BoolStorage, -1, 0),
        QueryCell(QueryStorage, row_type, 0),
    ];
    hosts: Host[] = [
        {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: QueryBeginIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 2,
         result_count: 1, written: false},
        {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: QueryNextIntrinsic, linked: -1, first: at.cell + 3, result_first: at.cell + 5,
         result_count: 2, written: false},
    ];

    // BEGIN receives the description once. Saving its cursor before head
    // means each `for` creates a new traversal of the same description.
    slots.append(AddressSlot(target));
    context := at.slot;
    code.append(Instruction(ops.context, target.pointer_storage, context, 0, 0, 1, node));
    code.extend(CellWrite(target.pointer_storage, context, at.cell, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    code.extend(CellWrite(QueryStorage, description.slot, at.cell + 1, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(target.pointer_storage, at.cell + 2, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    slots.append(QueryCursorSlot(target));
    code.append(Instruction(ops.save, target.pointer_storage, 0, at.slot + length(slots) - 1, 0, at.local, node));

    head := at.pc + length(code);
    code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
    context = at.slot + length(slots);
    slots.append(AddressSlot(target));
    code.append(Instruction(ops.context, target.pointer_storage, context, 0, 0, 1, node));
    code.extend(CellWrite(target.pointer_storage, context, at.cell + 3, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    cursor := at.slot + length(slots);
    slots.append(QueryCursorSlot(target));
    code.append(Instruction(ops.local, target.pointer_storage, cursor, at.local, 0, 0, node));
    code.extend(CellWrite(target.pointer_storage, cursor, at.cell + 4, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host + 1, node));
    code.extend(CellRead(BoolStorage, at.cell + 5, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    slots.append(ValueLocal(BoolStorage));
    code.append(Instruction(ops.branch_if, 0, 0, at.slot + length(slots) - 1, 0, at.pc + length(code) + 2, node));
    leave := at.pc + length(code);
    code.append(Instruction(ops.jump, 0, 0, 0, 0, Pending, node));

    code.extend(CellRead(QueryStorage, at.cell + 6, ops, target, at.slot + length(slots), node));
    slots.append(AddressSlot(target));
    slots.append(ValueLocal(QueryStorage));
    row := at.slot + length(slots) - 1;
    roots: Root[] = [];
    code.append(Instruction(ops.save, QueryStorage, 0, row, 0, at.local + 1, node));
    code.append(SymbolCode(ops, name_node, node));
    bound: Name[] = [{owned: false, name: name, place: LocalPlace, index: at.local + 1, storage: QueryStorage,
                      container: 0, record: row_type, writable: false, node: name_node}];
    next: Work[] = [Visit(Field(forest, item.node, "body")), Resume(item.node, QueryIteratorEndPhase, 0, 0)];
    return Step.Emitted(code, slots, locals, cells, hosts, roots, [], bound, next, 0, NoValue(), NoValue(),
                        [head, leave, at.local, at.local + 1]);
}

// END has its own argument cells, so cleanup does not depend on which NEXT
// last ran. Loop exhaustion and break both target this step; continue targets
// the existing loop head and leaves the cursor open.
QueryIteratorEndStep :: (cursor_local: int, ops: Ops, target: Target, at: Bases,
                         node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [AddressSlot(target), AddressSlot(target),
                     {storage: target.pointer_storage, kind: QueryCursorKind}, AddressSlot(target)];
    cells: Cell[] = [
        {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: AddressKind},
        {storage: target.pointer_storage, container: 0, record: -1, constant: 0, variant: -1, kind: QueryCursorKind},
        QueryCell(BoolStorage, -1, 0),
    ];
    code.append(Instruction(ops.context, target.pointer_storage, at.slot, 0, 0, 1, node));
    code.extend(CellWrite(target.pointer_storage, at.slot, at.cell, ops, target, at.slot + 1, node));
    code.append(Instruction(ops.local, target.pointer_storage, at.slot + 2, cursor_local, 0, 0, node));
    code.extend(CellWrite(target.pointer_storage, at.slot + 2, at.cell + 1, ops, target, at.slot + 3, node));
    host: Host = {owned_arguments: false, command: 0, syntax_node: 0, intrinsic: QueryEndIntrinsic, linked: -1, first: at.cell, result_first: at.cell + 2,
                  result_count: 1, written: false};
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    return Step.Emitted(code, slots, [], cells, [host], [], [], [], [], 0, NoValue(), NoValue(), []);
}

// A return closes active query loops from the innermost out. Ordinary loops
// have a nonnegative index or no cursor bound and need no query cleanup.
QueryIteratorCleanupStep :: (loops: Loop[], ops: Ops, target: Target, at: Bases,
                             node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    index := length(loops) - 1;
    while (index >= 0) {
        loop := loops[index];
        if (loop.each && loop.index < 0 && loop.bound >= 0) {
            start: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots), local: at.local,
                            cell: at.cell + length(cells), host: at.host + length(hosts), call: at.call};
            switch QueryIteratorEndStep(loop.bound, ops, target, start, node) {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                              added_calls, added_names, next, popped, produced, retained, marks):
                    code.extend(added_code);
                    slots.extend(added_slots);
                    cells.extend(added_cells);
                    hosts.extend(added_hosts);
            }
        }
        index -= 1;
    }
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], 0, NoValue(), NoValue(), []);
}

QueryLoopFinish :: union {
    Finished(code: Code[], breaks: int[], continues: int[], tail_step: Step)
}
QueryFinishLoop :: (input_code: Code[], breaks: int[], continues: int[], loop: Loop, ops: Ops, target: Target,
                    at: Bases, node: snapshot.SnapshotNode) -> QueryLoopFinish {
    code := input_code;
    code.append(Instruction(ops.jump, 0, 0, 0, 0, loop.head, node));
    done := code[loop.leave];
    done.target = length(code);
    code[loop.leave] = done;
    at_break := loop.first_break;
    while (at_break < length(breaks)) {
        escape := code[breaks[at_break]];
        escape.target = length(code);
        code[breaks[at_break]] = escape;
        at_break += 1;
    }
    at_continue := loop.first_continue;
    while (at_continue < length(continues)) {
        resume := code[continues[at_continue]];
        resume.target = loop.head;
        code[continues[at_continue]] = resume;
        at_continue += 1;
    }
    end_at := at;
    end_at.pc = length(code);
    return QueryLoopFinish.Finished(code, slice(breaks, 0, loop.first_break), slice(continues, 0, loop.first_continue),
                                    QueryIteratorEndStep(loop.bound, ops, target, end_at, node));
}

// Keep cleanup outside EmitBody's dispatch: each return shape supplies its
// own instructions, but closing cursors is one shared operation.
QueryCleanReturn :: (step: Step, loops: Loop[], ops: Ops, target: Target, at: Bases,
                     node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks):
            finish_index: int = 0;
            while (finish_index < length(code) && code[finish_index].op != ops.finish) {
                finish_index += 1;
            }
            if (finish_index == length(code)) {
                return step;
            }
            cleanup_at: Bases = {pc: at.pc + finish_index, slot: at.slot + length(slots), local: at.local + length(locals),
                                 cell: at.cell + length(cells), host: at.host + length(hosts), call: at.call + length(calls)};
            switch QueryIteratorCleanupStep(loops, ops, target, cleanup_at, node) {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(clean_code, clean_slots, clean_locals, clean_cells, clean_hosts, clean_roots,
                              clean_calls, clean_names, clean_next, clean_popped, clean_value, clean_kept, clean_marks):
                    added_code := extend(extend(slice(code, 0, finish_index), clean_code),
                                         slice(code, finish_index, length(code) - finish_index));
                    return Step.Emitted(added_code, extend(slots, clean_slots), locals, extend(cells, clean_cells),
                                        extend(hosts, clean_hosts), roots, calls, bound, next, popped, produced, retained, marks);
            }
    }
}
package package_compiler

import snapshot "project:source_snapshot"
import raw "project:compiler_syntax"
import graph "project:package_graph"
import syntax "project:syntax_diagnostics"
import binding "project:lexical_binding"
import writer "project:prepared_writer"
import strings "core:strings"

// Compiles a behavior asset to the prepared module of the game a target
// describes: its retained states, and its event handlers, which read and
// write those states and write fields of the owner's components. Its module,
// states and handlers take the IDs stage zero gives them.

// An event the game declares; its payload is event_fields[first, first + count).
pub GameEvent :: struct {
    name: string;
    id: u64;
    abi: u64;
    first: int;
    count: int;
}
pub GameEventField :: struct {
    name: string;
    storage: int;
    nominal: u64;
    has_default: bool;
    default_owner: bool;
}
// A type the game links, a component when `component` is its component ID;
// its fields are type_fields[first, first + count). A module requires every
// type but a namespace, such as SceneGlobals; types[underlying], when that is
// not -1, is the type it stands for.
pub GameType :: struct {
    required: bool;
    underlying: int;
    name: string;
    id: u64;
    layout: u64;
    storage: int;
    size: int;
    component: u64;
    first: int;
    count: int;
    relationship: bool;
    traits: int;
}
// A game type's field: of the type types[record] when that is not -1; a
// constant whose value is its name; read by natives[read] when that is not
// -1, with the key `read_key` instead of the value when that is not "".
pub GameField :: struct {
    name: string;
    storage: int;
    offset: int;
    writable: bool;
    c_string: bool;
    record: int;
    constant: bool;
    read: int;
    read_key: string;
}
// A native that makes a record of type types[record] of its arguments;
// argument i gives the record's field make_fields[first + i].
pub NativeMake :: struct {
    native: int;
    record: int;
    first: int;
}
// A name the game binds in every behavior, of the type types[record] when
// that is not -1.
pub GameGlobal :: struct {
    name: string;
    storage: int;
    record: int;
}
// A native that combines numbers, and records of them field by field, for a
// binary operator: natives[native].
pub NumericOperator :: struct {
    native: int;
    operator: string;
}
// A behavior's retained state, with its nominal type and initial value.
StateDecl :: struct {
    name: string;
    id: u64;
    storage: int;
    record: int;
    bits: u64;
    text: string;
    node: int;
}
// State rows and every function's variable defaults retain the same header.
StateValue :: (kept: StateDecl, types: TypeDecl[], layouts: int[], wide: int) -> writer.Value {
    value := Header(kept.storage, 0, kept.record, types, layouts);
    value.wide = wide;
    value.text = kept.text;
    value.has_text = kept.storage == TextStorage;
    return value;
}
// What a module holds beyond its functions. A behavior's functions keep its
// states, and handled[i] is the event function i handles, -1 for none; its
// operators may combine records, and its globals are names.
Game :: union {
    Package
    | Library(entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
              make_fields: int[])
    | Behavior(kept: StateDecl[], handled: int[], declared: GameEvent[], payloads: GameEventField[],
               entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
               make_fields: int[])
}
// Prepared function kinds.
HandlerFunction: int : 1;
// The reference kind of a component field, as the reference intrinsics take it.
ComponentReference: int : 2;
// Effects a handler declares.
ReadEffect: int : 1;
WriteEffect: int : 2;
InvocationReadEffect: int : 64;

// A behavior's names: the game's globals, its states, then `self`, its owner,
// whatever global the game names so.
BehaviorNames :: (kept_states: StateDecl[], globals: GameGlobal[], owner_record: int) -> Name[] {
    names: Name[] = [];
    index: int = 0;
    while (index < length(globals)) {
        bound: Name = {owned: false, name: globals[index].name, place: GlobalPlace, index: index, storage: globals[index].storage,
                       container: 0, record: globals[index].record, writable: false, node: -1};
        names.append(bound);
        index += 1;
    }
    index = 0;
    while (index < length(kept_states)) {
        kept: Name = {owned: false, name: kept_states[index].name, place: StatePlace, index: index,
                      storage: kept_states[index].storage, container: 0, record: kept_states[index].record,
                      writable: true,
                      node: kept_states[index].node};
        names.append(kept);
        index += 1;
    }
    owner: Name = {owned: false, name: "self", place: SelfPlace, index: 0, storage: HandleStorage, container: 0,
                   record: owner_record,
                   writable: false, node: -1};
    return append(names, owner);
}
// The component of each component reference a body makes, or, when
// `written`, of each it writes through.
ComponentsOf :: (cells: Cell[], hosts: Host[], written: bool) -> u64[] {
    found: u64[] = [];
    for (host in hosts) {
        if (host.intrinsic == ReferenceMakeIntrinsic && cells[host.first + 2].constant == u64(ComponentReference) &&
            (host.written || !written)) {
            found.append(cells[host.first + 6].constant);
        }
    }
    return found;
}
// Each of `items` once, in order.
Distinct :: (items: u64[]) -> u64[] {
    kept: u64[] = [];
    for (item in items) {
        seen := false;
        for (known in kept) {
            if (known == item) {
                seen = true;
            }
        }
        if (!seen) {
            kept.append(item);
        }
    }
    return kept;
}
// A handler's effects, as stage zero's analysis gives them: reading a state
// reads what the invocation retains, storing one also reads it and writes,
// reading a component reads, and writing one reads and writes.
Effects :: (ops: Ops, code: Code[], reads_components: bool, writes_components: bool) -> int {
    effects: int = 0;
    if (reads_components) {
        effects = ReadEffect;
    }
    if (writes_components) {
        effects = ReadEffect | WriteEffect;
    }
    for (instruction in code) {
        if (instruction.op == ops.variable) {
            effects = effects | ReadEffect | InvocationReadEffect;
        } else if (instruction.op == ops.store || instruction.op == ops.store_value) {
            effects = effects | ReadEffect | InvocationReadEffect | WriteEffect;
        }
    }
    return effects;
}
// The game's types as shared native declarations, in order, a
// namespace as one no module requires; their fields are members, and a
// native type's parent is its underlying type.
NativeTypes :: (types: GameType[]) -> TypeDecl[] {
    declared: TypeDecl[] = [];
    for (linked in types) {
        kind := NativeDecl;
        if (!linked.required) {
            kind = NamespaceDecl;
        }
        if (linked.relationship) {
            kind = RelationshipDecl;
        }
        row: TypeDecl = {name: linked.name, type_name: linked.name, package: -1, node: -1, kind: kind,
                         first: linked.first, count: linked.count, size: linked.size, parent: linked.underlying,
                         storage: linked.storage, id: linked.id, layout: linked.layout, component: linked.component,
                         key: linked.traits, value_storage: 0, value_container: 0, value_record: -1};
        declared.append(row);
    }
    // Optional query snapshots keep their underlying nominal component type
    // and layout, while semantic lookup remembers that a guard is required.
    index: int = 0;
    while (index < length(types)) {
        if (declared[index].kind == NativeDecl && declared[index].component != 0) {
            optional := declared[index];
            optional.kind = OptionalComponentDecl;
            optional.parent = index;
            optional.name = format_text("{}?", optional.name);
            declared.append(optional);
        }
        index += 1;
    }
    return declared;
}
NativeFields :: (type_fields: GameField[]) -> TypeMember[] {
    fields: TypeMember[] = [];
    for (linked in type_fields) {
        row: TypeMember = {name: linked.name, storage: linked.storage, container: 0, record: linked.record,
                           offset: linked.offset, writable: linked.writable, c_string: linked.c_string, constant: linked.constant,
                           read: linked.read, read_key: linked.read_key};
        fields.append(row);
    }
    return fields;
}
// The event named `name`, matched as the catalog matches names: an exact
// name first, else the one that matches loosely; -1 for none or several.
FindEvent :: (game_events: GameEvent[], name: string) -> int {
    found: int = -1;
    index: int = 0;
    while (index < length(game_events)) {
        if (game_events[index].name == name) {
            return index;
        }
        if (NameMatches(game_events[index].name, name)) {
            if (found != -1) {
                found = -2;
            } else {
                found = index;
            }
        }
        index += 1;
    }
    if (found < 0) {
        return -1;
    }
    return found;
}
// Whether every field of an event's payload is a scalar a handler can take.
ScalarPayload :: (declared: GameEvent, event_fields: GameEventField[]) -> bool {
    at := declared.first;
    while (at < declared.first + declared.count) {
        storage := event_fields[at].storage;
        if (storage == StructStorage || storage == UnionStorage || storage <= 0) {
            return false;
        }
        at += 1;
    }
    return true;
}
// A handler's payload parameters, or why the handler cannot take them.
Payload :: union {
    Failed(diagnostic: syntax.Diagnostic) | Bound(params: Param[])
}
// The handler's parameters, one per payload field in payload order. The
// handler names fields in any order; each it leaves out gets an unnamed
// parameter, as stage zero gives it.
PayloadParams :: (forest: snapshot.SnapshotNode[], source: string, handler: int, event_name: string,
                  declared: GameEvent, event_fields: GameEventField[]) -> Payload {
    listed: int[] = [];
    at: int = 0;
    while (at < declared.count) {
        listed.append(int(-1));
        at += 1;
    }
    parameter := FirstMember(forest, Field(forest, handler, "parameters"));
    while (parameter >= 0) {
        name := Field(forest, parameter, "name");
        spelled := Text(forest, source, name);
        at = 0;
        while (at < declared.count && !NameMatches(event_fields[declared.first + at].name, spelled)) {
            at += 1;
        }
        if (at == declared.count) {
            return Payload.Failed(Diagnose(forest, name, 0,
                                           format_text("{} has no payload field '{}'", event_name, spelled)));
        }
        if (listed[at] >= 0) {
            return Payload.Failed(Diagnose(forest, name, 0, format_text("Payload field '{}' is listed twice",
                                                                        event_fields[declared.first + at].name)));
        }
        listed[at] = name;
        parameter = NextMember(forest, parameter);
    }
    params: Param[] = [];
    at = 0;
    while (at < declared.count) {
        param: Param = {name: "", storage: event_fields[declared.first + at].storage, container: 0, record: -1,
                        has_default: false, default_bits: 0, default_text: "", default_occurrence: 0,
                        reference: false, node: listed[at]};
        if (listed[at] >= 0) {
            param.name = Text(forest, source, listed[at]);
        }
        params.append(param);
        at += 1;
    }
    return Payload.Bound(params);
}
// A number or one signed number. Unary plus keeps its operand's value;
// minus stays attached for the literal readers. Other unary operators are
// expressions, not numeric literal defaults.
StateNumberNode :: (forest: snapshot.SnapshotNode[], source: string, node: int) -> int {
    if (Is(forest, node, "number")) {
        return node;
    }
    if (!Is(forest, node, "unary_expression")) {
        return -1;
    }
    operand := Field(forest, node, "operand");
    if (!Is(forest, operand, "number")) {
        return -1;
    }
    operator := Text(forest, source, Field(forest, node, "operator"));
    if (operator == "+") {
        return operand;
    }
    if (operator == "-") {
        return node;
    }
    return -1;
}
// A numeric literal's natural storage follows its spelling. Hexadecimal e
// is a digit; only decimal points and exponents select number storage.
StateNumberStorage :: (forest: snapshot.SnapshotNode[], source: string, node: int) -> int {
    digits := node;
    if (Is(forest, node, "unary_expression")) {
        digits = Field(forest, node, "operand");
    }
    spelling := Text(forest, source, digits);
    hexadecimal := strings.ByteLength(spelling) > 1 && strings.ByteAt(spelling, 0) == 48 &&
                   (strings.ByteAt(spelling, 1) == 120 || strings.ByteAt(spelling, 1) == 88);
    if (!hexadecimal) {
        index: int = 0;
        while (index < strings.ByteLength(spelling)) {
            digit := strings.ByteAt(spelling, index);
            if (digit == 46 || digit == 101 || digit == 69) {
                return FloatStorage;
            }
            index += 1;
        }
    }
    switch ParseNumber(forest, source, node) {
        case .Number(negative, magnitude):
            if (Fits(negative, magnitude, IntStorage)) {
                return IntStorage;
            }
            if (Fits(negative, magnitude, Int64Storage)) {
                return Int64Storage;
            }
        case .Invalid:
            return WordStorage;
    }
    return WordStorage;
}
// The written scalar type, or a literal initializer's natural type.
StateType :: (forest: snapshot.SnapshotNode[], source: string, types: ^(TypeDecl[]), entity: u64,
              member: int) -> ValueType {
    written := Field(forest, member, "type");
    value := Field(forest, member, "value");
    if (written < 0) {
        if (Is(forest, value, "boolean")) {
            return {storage: BoolStorage, container: 0, record: -1};
        }
        if (Is(forest, value, "string")) {
            return {storage: TextStorage, container: 0, record: -1};
        }
        literal := StateNumberNode(forest, source, value);
        if (literal >= 0) {
            return {storage: StateNumberStorage(forest, source, literal), container: 0, record: -1};
        }
        return {storage: 0, container: 0, record: -1};
    }
    spelled := Text(forest, source, Field(forest, written, "name"));
    if ((spelled == "entity" || spelled == "number") && Field(forest, written, "trait") < 0 &&
        Field(forest, written, "arguments") < 0 && !HasToken(forest, written, "?") &&
        !HasToken(forest, written, "[")) {
        if (spelled == "number") {
            return {storage: FloatStorage, container: 0, record: -1};
        }
        return {storage: HandleStorage, container: 0, record: TypeWithId(types^, entity)};
    }
    no_names: Name[] = [];
    return ReadType(forest, source, types, no_names, 0, written);
}
// A scalar state's literal default. Handles also admit an unwritten empty
// value; the other scalar types require an initializer, as stage zero does.
StateDefault :: (forest: snapshot.SnapshotNode[], source: string, name: string, storage: int,
                 value: int, ops: Ops) -> Default {
    if (value < 0) {
        if (storage == HandleStorage) {
            return Default.Read(0, "");
        }
        return Default.Failed({start: 0, end: 0, line: 1, column: 1, document: 0,
                               message: format_text("'{}' requires a default value", name)});
    }
    if (Is(forest, value, "nil") && Text(forest, source, value) == "null") {
        return Default.Read(0, "");
    }
    literal := StateNumberNode(forest, source, value);
    if (storage == HandleStorage && literal >= 0) {
        switch NumberBits(forest, source, literal) {
            case .Finite(double_bits, float_fits, float_bits):
                if ((double_bits & 0x7fffffffffffffff) == 0) {
                    return Default.Read(0, "");
                }
            case .OutOfRange:
                return Default.Failed(Diagnose(forest, value, 0, "Numeric literal is outside the range of its type"));
        }
        return Default.Failed(Diagnose(forest, value, 0, "entity default requires null or zero"));
    }
    if (storage == BoolStorage && Is(forest, value, "boolean")) {
        bits: u64 = 0;
        if (Text(forest, source, value) == "true") {
            bits = 1;
        }
        return Default.Read(bits, "");
    }
    if (storage == TextStorage && Is(forest, value, "string")) {
        decoded := compiler_json_value_string(Text(forest, source, value));
        if (!decoded.valid) {
            return Default.Failed(Diagnose(forest, value, 0, "Invalid string literal"));
        }
        return Default.Read(0, decoded.value);
    }
    if (Floating(storage) && literal >= 0) {
        switch FloatConstantStep(forest, source, 0, Typed(-1, NumberStorage, 0, literal), storage, ops,
                                 NoBases(), forest[value]) {
            case .Failed(diagnostic):
                return Default.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, result, retained, marks):
                return Default.Read(code[0].payload, "");
        }
    }
    if (Integer(storage)) {
        switch ParseNumber(forest, source, literal) {
            case .Number(negative, magnitude):
                if (Fits(negative, magnitude, storage)) {
                    return Default.Read(Bits(negative, magnitude), "");
                }
                return Default.Failed(Diagnose(forest, value, 0,
                                               format_text("Numeric literal is outside the range of {}",
                                                           TypeName(storage))));
            case .Invalid:
                return Default.Failed(Diagnose(forest, value, 0, "state default needs a literal of its declared type"));
        }
    }
    return Default.Failed(Diagnose(forest, value, 0, "state default needs a literal of its declared type"));
}
// A system's body reads its step from the execution context, including empty
// headers. Helpers receive it explicitly; it is not a mutable local.
SystemStepName :: (target: Target, storage: int) -> Name {
    return {owned: false, name: "dt", place: SystemStepPlace, index: target.delta_seconds_offset,
            storage: storage, container: 0, record: -1, writable: false, node: -1};
}
// `identity` names the source as the project does, such as
// "behaviors/Counter.chibi"; the module, states and handlers take their IDs
// from it. The target, natives, events, types, entity, operators, globals and
// record makes are the game's, as `chibi-compile --stage-one-input` exports
// them.
pub CompileBehavior :: (identity: string, source: string, target: Target, abi: u64, names: string[],
                        natives: Native[], ports: Port[], native_ids: u64[], game_events: GameEvent[],
                        event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                        entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                        make_fields: int[]) -> Result {
    context: BodyContext = BodyContext.Unknown;
    return CompileBehaviorResolved(identity, source, target, abi, names, LegacyNatives(natives, names), LegacyPorts(ports), native_ids,
                                   game_events, event_fields, types, type_fields, entity, operators, globals,
                                   makes, make_fields, resize([int(0)], length(natives)), context);
}
CompileBehaviorResolved :: (identity: string, source: string, target: Target, abi: u64, names: string[],
                            natives: ResolvedNative[], ports: ResolvedPort[], native_ids: u64[], game_events: GameEvent[],
                            event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                            entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                            make_fields: int[], native_effects: int[], context: BodyContext) -> Result {
    return CompileSources([identity], [source], target, abi, names, natives, ports, native_ids, game_events,
                          event_fields, types, type_fields, entity, operators, globals, makes, make_fields,
                          native_effects, context, false);
}
// Every source is declared before a body is emitted. Source-owned records
// replace their catalog row in place, preserving nominal indices in fields.
SourceTypes :: union {
    Failed(diagnostic: syntax.Diagnostic) | Read(types: TypeDecl[])
}
PromoteRecords :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], roots: int[],
                   types: TypeDecl[], members: TypeMember[], target: Target) -> SourceTypes {
    file: int = 0;
    while (file < length(documents)) {
        root := roots[file];
        source := documents[file].text;
        if (Is(forest, root, "library")) {
            namespace_name := Text(forest, source, Field(forest, root, "name"));
            member := FirstMember(forest, Field(forest, root, "body"));
            while (member >= 0) {
                if (Is(forest, member, "record_declaration")) {
                    name := Text(forest, source, Field(forest, member, "name"));
                    id := binding.ID("symbol", format_text("{}:1:{}", documents[file].identity, name));
                    found := TypeWithId(types, id);
                    if (found < 0 || types[found].type_name != format_text("{}.{}", namespace_name, name) ||
                        types[found].kind != NativeDecl || types[found].storage != StructStorage ||
                        Field(forest, member, "parameters") >= 0) {
                        return SourceTypes.Failed(Diagnose(forest, member, file, "library record differs from the declaration catalog"));
                    }
                    declared := types[found];
                    item := FirstMember(forest, Field(forest, member, "body"));
                    count: int = 0;
                    while (item >= 0) {
                        storage := ScalarStorage(Text(forest, source, Field(forest, item, "type")));
                        if (count >= declared.count || storage == 0 || Field(forest, item, "value") >= 0) {
                            return SourceTypes.Failed(Diagnose(forest, item, file, "library record needs scalar fields without defaults"));
                        }
                        field := members[declared.first + count];
                        if (field.name != Text(forest, source, Field(forest, item, "name")) ||
                            field.storage != storage || field.record >= 0) {
                            return SourceTypes.Failed(Diagnose(forest, item, file, "library record differs from the declaration catalog"));
                        }
                        count += 1;
                        item = NextMember(forest, item);
                    }
                    if (count == 0 || count != declared.count || LayoutHash(declared, members, types, target) != declared.layout) {
                        return SourceTypes.Failed(Diagnose(forest, member, file, "library record layout differs from the declaration catalog"));
                    }
                    declared.name = name;
                    declared.package = file;
                    declared.node = member;
                    declared.kind = RecordDecl;
                    types[found] = declared;
                }
                member = NextMember(forest, member);
            }
        }
        file += 1;
    }
    return SourceTypes.Read(types);
}
SourceMembers :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Read(game: Game, callables: Callable[], params: Param[])
}
// Signatures may declare the sequence and optional types they use in `table`.
DeclareSource :: (forest: snapshot.SnapshotNode[], document: snapshot.Document, package: int, declaration: int,
                  aliases: Name[], table: ^(TypeDecl[]), callables: Callable[], params: Param[],
                  game_events: GameEvent[], event_fields: GameEventField[], entity: u64,
                  operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[], make_fields: int[],
                  ops: Ops) -> SourceMembers {
    source := document.text;
    identity := document.identity;
    solid := SolidOffsets(source);
    is_library := Is(forest, declaration, "library");
    is_system := Is(forest, declaration, "system");
    kept_states: StateDecl[] = [];
    handled: int[] = [];
    member := FirstMember(forest, Field(forest, declaration, "body"));
    if (is_system) {
        tick := FindEvent(game_events, "Tick");
        if (tick < 0 || game_events[tick].count != 1 || event_fields[game_events[tick].first].name != "dt") {
            return SourceMembers.Failed(Diagnose(forest, declaration, package,
                                                 "systems require Tick(dt) in the target event catalog"));
        }
        callable: Callable = {name: Text(forest, source, Field(forest, declaration, "name")), package: package,
                              document: package, node: declaration, first: length(params), count: 0, result: 0,
                              result_container: 0, result_record: -1, results: 0, waits: false};
        callables.append(callable);
        handled.append(tick);
    }
    while (member >= 0) {
        if (!is_library && Is(forest, member, "state_declaration")) {
            name := Text(forest, source, Field(forest, member, "name"));
            declared := StateType(forest, source, table, entity, member);
            if ((!Numeric(declared.storage) && declared.storage != BoolStorage && declared.storage != TextStorage &&
                 declared.storage != HandleStorage) || declared.container != 0 ||
                (declared.storage == HandleStorage && declared.record < 0)) {
                return SourceMembers.Failed(Diagnose(forest, member, package, "state type is not supported yet"));
            }
            bits: u64 = 0;
            initial := "";
            switch StateDefault(forest, source, name, declared.storage, Field(forest, member, "value"), ops) {
                case .Failed(diagnostic):
                    return SourceMembers.Failed(snapshot.Stamp(diagnostic, package));
                case .Read(default_bits, default_text):
                    bits = default_bits;
                    initial = default_text;
            }
            for (kept in kept_states) {
                if (kept.name == name) {
                    return SourceMembers.Failed(Diagnose(forest, member, package, format_text("Duplicate declaration '{}'", name)));
                }
            }
            kept: StateDecl = {name: name, id: binding.ID("symbol", format_text("{}:1:{}", identity, name)),
                               storage: declared.storage, record: declared.record, bits: bits, text: initial,
                               node: Field(forest, member, "name")};
            kept_states.append(kept);
        } else if (!is_library && Is(forest, member, "handler")) {
            if (Text(forest, source, Field(forest, member, "kind")) != "on" || Field(forest, member, "alias") >= 0 ||
                !Is(forest, Field(forest, member, "name"), "identifier")) {
                return SourceMembers.Failed(Diagnose(forest, member, package, "only `on Event` handlers are supported yet"));
            }
            name := Text(forest, source, Field(forest, member, "name"));
            found := FindEvent(game_events, name);
            if (found < 0) {
                return SourceMembers.Failed(Diagnose(forest, member, package, format_text("Unknown event '{}'", name)));
            }
            if (!ScalarPayload(game_events[found], event_fields)) {
                return SourceMembers.Failed(Diagnose(forest, member, package, "events with record payloads are not supported yet"));
            }
            first := length(params);
            switch PayloadParams(forest, source, member, name, game_events[found], event_fields) {
                case .Failed(diagnostic):
                    return SourceMembers.Failed(snapshot.Stamp(diagnostic, package));
                case .Bound(added):
                    params.extend(added);
            }
            callable: Callable = {name: name, package: package, document: package, node: member, first: first,
                                  count: game_events[found].count, result: 0, result_container: 0, result_record: -1,
                                  results: 0, waits: false};
            callables.append(callable);
            handled.append(found);
        } else if (Is(forest, member, "function_declaration")) {
            name := Text(forest, source, Field(forest, member, "name"));
            if (FindCallable(callables, package, name) >= 0 || FindType(table^, package, name) >= 0) {
                return SourceMembers.Failed(Diagnose(forest, member, package, format_text("Duplicate declaration '{}'", name)));
            }
            switch FunctionSignature(forest, source, identity, solid, table, aliases, package, package, member, name,
                                     length(params)) {
                case .Failed(diagnostic):
                    return SourceMembers.Failed(diagnostic);
                case .Read(procedure, added):
                    params.extend(added);
                    callables.append(procedure);
                    handled.append(int(-1));
            }
        } else if (!is_system && (!is_library || !Is(forest, member, "record_declaration"))) {
            return SourceMembers.Failed(Diagnose(forest, member, package, "unsupported executable source member"));
        }
        member = NextMember(forest, member);
    }
    if (is_library) {
        return SourceMembers.Read(Game.Library(entity, operators, globals, makes, make_fields), callables, params);
    }
    return SourceMembers.Read(Game.Behavior(kept_states, handled, game_events, event_fields, entity, operators,
                                            globals, makes, make_fields), callables, params);
}
// The names a query in the source at `root` reads: its states, the game's
// globals and the owner, and a system's step.
SourceNames :: (forest: snapshot.SnapshotNode[], root: int, game: Game, types: TypeDecl[], target: Target) -> Name[] {
    names: Name[] = [];
    switch game {
        case .Package:
            return names;
        case .Library(owner, operators, globals, makes, fields):
            return BehaviorNames([], globals, TypeWithId(types, owner));
        case .Behavior(kept, handlers, declared_events, payloads, owner, operators, globals, makes, fields):
            names = BehaviorNames(kept, globals, TypeWithId(types, owner));
            if (Is(forest, root, "system")) {
                tick := declared_events[FindEvent(declared_events, "Tick")];
                names.append(SystemStepName(target, payloads[tick.first].storage));
            }
    }
    return names;
}
// A system's step, and the rows of the system query enclosing a callable.
SystemNames :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], members: TypeMember[],
                query_specs: QuerySpec[], callable: Callable, game_events: GameEvent[],
                event_fields: GameEventField[], target: Target) -> Name[] {
    names: Name[] = [];
    if (Is(forest, callable.node, "system")) {
        tick := game_events[FindEvent(game_events, "Tick")];
        names.append(SystemStepName(target, event_fields[tick.first].storage));
    }
    for (described in query_specs) {
        if (Is(forest, described.node, "system") &&
            (callable.node == described.node || Ancestor(forest, Field(forest, described.node, "body"), callable.node))) {
            names.extend(QueryNames(forest, text, types, members, described));
        }
    }
    return names;
}
// The queries whose evaluators `document` declares, as its module owns them.
SourceQueries :: (queries: QuerySpec[], callables: Callable[], document: int) -> QuerySpec[] {
    owned: QuerySpec[] = [];
    for (described in queries) {
        if (callables[described.evaluator].document == document) {
            owned.append(described);
        }
    }
    return owned;
}
// Parsed roots, signatures and catalog types share one index space. Bodies
// establish exact imports; dependencies are assembled before their callers.
SourceNatives :: (documents: snapshot.Document[], callables: Callable[], natives: ResolvedNative[],
                  identities: u64[]) -> ResolvedNative[] {
    owned: u64[] = [];
    for (callable in callables) {
        owned.append(binding.ID("symbol", format_text("{}:1:{}:callable", documents[callable.document].identity,
                                                      callable.name)));
    }
    resolved: ResolvedNative[] = [];
    index: int = 0;
    for (native in natives) {
        row := native;
        for (id in owned) {
            row.source = row.source || identities[2 * index] == id;
        }
        resolved.append(row);
        index += 1;
    }
    return resolved;
}
CompileSources :: (identities: string[], sources: string[], target: Target, abi: u64, names: string[],
                   natives: ResolvedNative[], ports: ResolvedPort[], native_ids: u64[], game_events: GameEvent[],
                   event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                   entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                   make_fields: int[], native_effects: int[], context: BodyContext, closure: bool) -> Result {
    ops := ResolveOps(names, true);
    if (abi == 0 || !Complete(ops) || !NativeInputValid(natives, ports, native_ids, native_effects) ||
        length(identities) == 0 || length(identities) != length(sources)) {
        return InputFailure(-1, "unsupported compiler input or target");
    }
    forest: snapshot.SnapshotNode[] = [];
    documents: snapshot.Document[] = [];
    roots: int[] = [];
    links: graph.Binding[] = [];
    module_ids: u64[] = [];
    index: int = 0;
    while (index < length(sources)) {
        id := binding.ID("module", identities[index]);
        for (known in module_ids) {
            if (known == id) {
                return InputFailure(index, "duplicate executable source identity");
            }
        }
        module_ids.append(id);
        top: int = -1;
        first := length(forest);
        switch raw.Parse(sources[index]) {
            case .Parsed(nodes, fields, is_named, is_extra, root):
                errors := syntax.Diagnose(nodes, root);
                if (length(errors) > 0) {
                    return Result.Rejected(snapshot.Stamp(errors[0], index));
                }
                at: int = 0;
                while (at < length(nodes)) {
                    forest.append(snapshot.Node(nodes[at], fields[at], is_named[at], is_extra[at], first));
                    at += 1;
                }
                top = root + first;
        }
        root := FirstMember(forest, top);
        if ((!Is(forest, root, "behavior") && !Is(forest, root, "system") && !Is(forest, root, "library")) ||
            NextMember(forest, root) >= 0) {
            return InputFailure(index, "an executable asset needs one behavior, system or library declaration");
        }
        if (Is(forest, root, "library")) {
            name := Text(forest, sources[index], Field(forest, root, "name"));
            for (link in links) {
                if (link.name == name) {
                    return InputFailure(index, "duplicate library declaration");
                }
            }
            link: graph.Binding = {name: name, file: -1, target: index, import_index: -2};
            links.append(link);
        }
        roots.append(root);
        document: snapshot.Document = {original_path: identities[index], path: identities[index], directory: "",
                                       key: identities[index], identity: identities[index], text: sources[index], root: 0,
                                       syntax_root: top, header_start: 0, header_end: 0, header_line: 0, header_column: 0,
                                       header_document: index, node_start: first, node_count: length(forest) - first,
                                       first_import: 0, import_count: 0, has_key: true, has_syntax: true, has_header: false};
        documents.append(document);
        index += 1;
    }
    namespaces: graph.Binding[] = [];
    index = 0;
    while (index < length(documents)) {
        for (link in links) {
            bound: graph.Binding = {name: link.name, file: index, target: link.target, import_index: -2};
            namespaces.append(bound);
        }
        index += 1;
    }
    declared_types := NativeTypes(types);
    members := NativeFields(type_fields);
    switch DeclareMath(forest, documents, declared_types, members, target) {
        case .Failed(message):
            return InputFailure(0, message);
        case .Read(math_types, math_members):
            declared_types = math_types;
            members = math_members;
    }
    switch PromoteRecords(forest, documents, roots, declared_types, members, target) {
        case .Failed(diagnostic):
            return Result.Rejected(diagnostic);
        case .Read(promoted):
            declared_types = promoted;
    }
    // A library has no owner to query from.
    has_queries := false;
    index = 0;
    while (index < length(documents)) {
        if (!Is(forest, roots[index], "library")) {
            declared_types = DeclarePointers(forest, sources[index], declared_types, Aliases(namespaces, index),
                                             index, roots[index]);
        }
        node := documents[index].node_start;
        while (node < documents[index].node_start + documents[index].node_count) {
            if (Is(forest, node, "query_expression") ||
                (Is(forest, node, "system") && length(Members(forest, Field(forest, node, "parameters"))) > 0)) {
                if (Is(forest, roots[index], "library")) {
                    return Result.Rejected(Diagnose(forest, node, index, "queries need a behavior or system source"));
                }
                has_queries = true;
            }
            node += 1;
        }
        index += 1;
    }
    if (has_queries) {
        declared_types = QueryPointers(declared_types, members);
    }
    query_specs: QuerySpec[] = [];
    games: Game[] = [];
    callables: Callable[] = [];
    params: Param[] = [];
    index = 0;
    while (index < length(documents)) {
        switch DeclareSource(forest, documents[index], index, roots[index], Aliases(namespaces, index),
                             &declared_types, callables, params, game_events, event_fields, entity, operators,
                             globals, makes, make_fields, ops) {
            case .Failed(diagnostic):
                return Result.Rejected(diagnostic);
            case .Read(game, declared, parameters):
                games.append(game);
                callables = declared;
                params = parameters;
        }
        // A source's evaluators follow its callables, which its module owns.
        if (has_queries && !Is(forest, roots[index], "library")) {
            first := documents[index].node_start;
            switch CollectQueries(forest, sources[index], identities[index], index, first,
                                  first + documents[index].node_count, declared_types, members, callables, params,
                                  natives, ports, query_specs,
                                  SourceNames(forest, roots[index], games[index], declared_types, target), entity,
                                  target, ops) {
                case .Failed(diagnostic):
                    return Result.Rejected(diagnostic);
                case .Collected(query_types, query_members, query_callables, query_params, descriptions):
                    declared_types = query_types;
                    members = query_members;
                    callables = query_callables;
                    params = query_params;
                    query_specs = descriptions;
            }
        }
        index += 1;
    }
    callables = WaitingCallables(forest, callables);
    switch TaskResultDeclarations(callables, params, declared_types, members) {
        case .Collected(task_types, task_members):
            declared_types = task_types;
            members = task_members;
    }
    natives = SourceNatives(documents, callables, natives, native_ids);
    bodies: Body[] = [];
    summaries: int[] = [];
    edges: graph.Edge[] = [];
    constants: ConstDecl[] = [];
    // A scoped parameter's `p^` reads and writes `p` in every body.
    scoped := forest;
    if (AnyReference(params)) {
        scoped = ScopedTargets(forest, documents, callables, params);
    }
    pass: int = 0;
    while (pass < 2) {
        solid: int[] = [];
        solid_document: int = -1;
        index = 0;
        while (index < length(callables)) {
            callable := callables[index];
            generic: int[] = [];
            if (pass > 0) {
                generic = GenericUpdates(scoped, bodies[index], summaries, context);
            }
            if (pass == 0 || length(generic) > 0) {
                game := games[callable.package];
                if (solid_document != callable.document) {
                    solid = SolidOffsets(documents[callable.document].text);
                    solid_document = callable.document;
                }
                undeclared := OccurrenceIn(DocumentHash(documents[callable.document].key), SymbolRecord, 0,
                                           solid[length(solid) - 1]);
                behaving: Name[] = [];
                switch game {
                    case .Package:
                        return InputFailure(callable.document, "invalid executable source mode");
                    case .Library(owner, operators, globals, makes, fields):
                        behaving = BehaviorNames([], globals, TypeWithId(declared_types, owner));
                    case .Behavior(kept, handlers, declared_events, payloads, owner, operators, globals, makes, fields):
                        behaving = BehaviorNames(kept, globals, TypeWithId(declared_types, owner));
                }
                meaning := binding.ID("symbol", format_text("{}:1:{}:callable", identities[callable.package], callable.name));
                if (Is(forest, callable.node, "handler")) {
                    meaning = game_events[FindEvent(game_events, callable.name)].id;
                } else if (Is(forest, callable.node, "system")) {
                    meaning = game_events[FindEvent(game_events, "Tick")].id;
                }
                if (QueryEvaluator(query_specs, index) < 0) {
                    behaving.extend(SystemNames(forest, documents[callable.document].text, declared_types, members,
                                                query_specs, callable, game_events, event_fields, target));
                }
                body := FunctionBody(scoped, documents, callables, params, &declared_types, members, constants, natives,
                                     ports, native_ids, extend(Aliases(namespaces, callable.document), behaving),
                                     operators, makes, make_fields, index, solid, undeclared, meaning, context,
                                     generic, ops, target, SourceQueries(query_specs, callables, callable.document));
                switch body {
                    case .Failed(diagnostic):
                        return Result.Rejected(diagnostic);
                    case .Inferred(value):
                        return InputFailure(callable.document, "expression inferred where a callable body was required");
                    case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                                  direct_write, facts):
                        if (pass == 0) {
                            for (call in calls) {
                                target_package := callables[call.callee].package;
                                if (target_package != callable.package) {
                                    edge: graph.Edge = {from: callable.package, to: target_package, import_index: -1};
                                    edges.append(edge);
                                }
                            }
                        }
                }
                if (pass == 0) {
                    bodies.append(body);
                } else {
                    if (!StablePreparation(scoped, bodies[index], body, summaries, context)) {
                        return InputFailure(callable.document, "array update effects changed during preparation");
                    }
                    bodies[index] = body;
                }
            }
            index += 1;
        }
        if (pass == 0) {
            summaries = WriteSummaries(bodies);
        }
        pass += 1;
    }
    done := resize([false], length(documents));
    fingerprints := resize([u64(0)], length(documents));
    starts := resize([int(0)], length(documents));
    lengths := resize([int(0)], length(documents));
    effects := resize([int(0)], length(callables));
    data: u8[] = [];
    remaining := length(documents);
    while (remaining > 0) {
        progress := false;
        index = 0;
        while (index < length(documents)) {
            ready := !done[index];
            for (edge in edges) {
                if (edge.from == index && !done[edge.to]) {
                    ready = false;
                }
            }
            if (ready) {
                switch Assemble(forest, documents, index, index, identities, module_ids, fingerprints,
                                resize([true], length(documents)), namespaces, callables, params, declared_types,
                                members, constants, natives, ports, native_ids, native_effects, effects, ops,
                                target, abi, games[index], bodies, SourceQueries(query_specs, callables, index)) {
                    case .Rejected(diagnostic):
                        return Result.Rejected(diagnostic);
                    case .Compiled(module, bytes, summaries):
                        effects = summaries;
                        fingerprints[index] = writer.Fingerprint(bytes);
                        if (!closure) {
                            return Result.Compiled(module, bytes);
                        }
                        starts[index] = length(data);
                        lengths[index] = length(bytes);
                        data.extend(bytes);
                }
                done[index] = true;
                remaining -= 1;
                progress = true;
            }
            index += 1;
        }
        if (!progress) {
            return InputFailure(-1, "cross-library import cycle has no publishable generation");
        }
    }
    return Result.Compiled(module_ids[0], writer.Closure(module_ids[0], module_ids, identities, data, starts, lengths));
}
CompileBehaviorsResolved :: (identities: string[], sources: string[], target: Target, abi: u64, names: string[],
                             natives: ResolvedNative[], ports: ResolvedPort[], native_ids: u64[], game_events: GameEvent[],
                             event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                             entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                             make_fields: int[], native_effects: int[], context: BodyContext) -> u8[] {
    switch CompileSources(identities, sources, target, abi, names, natives, ports, native_ids, game_events,
                          event_fields, types, type_fields, entity, operators, globals, makes, make_fields,
                          native_effects, context, true) {
        case .Rejected(diagnostic):
            return [];
        case .Compiled(module, bytes):
            return bytes;
    }
}
BehaviorRejectionResolved :: (identities: string[], sources: string[], target: Target, abi: u64, names: string[],
                              natives: ResolvedNative[], ports: ResolvedPort[], native_ids: u64[], game_events: GameEvent[],
                              event_fields: GameEventField[], types: GameType[], type_fields: GameField[],
                              entity: u64, operators: NumericOperator[], globals: GameGlobal[], makes: NativeMake[],
                              make_fields: int[], native_effects: int[], context: BodyContext) -> string {
    switch CompileSources(identities, sources, target, abi, names, natives, ports, native_ids, game_events,
                          event_fields, types, type_fields, entity, operators, globals, makes, make_fields,
                          native_effects, context, true) {
        case .Rejected(diagnostic):
            if (diagnostic.document < 0 || diagnostic.document >= length(identities)) {
                return diagnostic.message;
            }
            return format_text("{}:{}:{}: {}", identities[diagnostic.document], diagnostic.line, diagnostic.column,
                               diagnostic.message);
        case .Compiled(module, bytes):
            return "";
    }
}

// Resolves only reflected native nominal ports. Unsupported ports remain in
// place, so their native indices stay stable and only a use is rejected.
CatalogRecordValid :: (types: TypeDecl[], record: int) -> bool {
    if (record < 0 || record >= length(types)) {
        return false;
    }
    first := types[record];
    at := record;
    depth: int = 0;
    while (depth < length(types)) {
        if (at < 0 || at >= length(types)) {
            return false;
        }
        declared := types[at];
        if ((declared.kind != NativeDecl && declared.kind != MathDecl) || declared.storage != first.storage || declared.size <= 0 ||
            declared.size != first.size || declared.layout != first.layout ||
            (declared.storage == StructStorage && declared.layout == 0)) {
            return false;
        }
        if (declared.parent < 0) {
            return true;
        }
        at = declared.parent;
        depth += 1;
    }
    return false;
}
CatalogPorts :: (ports: CatalogPort[], types: TypeDecl[], entity: u64) -> ResolvedPort[] {
    resolved: ResolvedPort[] = [];
    for (port in ports) {
        record: int = -1;
        storage := port.storage;
        if (port.container < 0 || port.container > ArrayContainer ||
            (storage < UnsupportedPort && storage != AnyPort) || storage > StructStorage) {
            storage = UnsupportedPort;
        }
        if (port.nominal != 0) {
            found := TypeWithId(types, port.nominal);
            duplicate := false;
            // A component's optional query view shares its identity.
            if (found >= 0) {
                at := found + 1;
                while (at < length(types)) {
                    duplicate = duplicate || (types[at].id == port.nominal && types[at].kind != OptionalComponentDecl);
                    at += 1;
                }
            }
            valid := found >= 0 && !duplicate && port.container == 0 &&
                     (storage == StructStorage || storage == HandleStorage);
            if (valid) {
                declared := types[found];
                valid = declared.storage == storage && CatalogRecordValid(types, found);
                if (storage == StructStorage) {
                    valid = valid && declared.size > 0 && declared.layout != 0;
                }
            }
            if (valid) {
                record = found;
            } else {
                storage = UnsupportedPort;
            }
        } else if (storage == StructStorage || storage == HandleStorage) {
            storage = UnsupportedPort;
        }
        if (port.default_owner) {
            owner := TypeWithId(types, entity);
            valid := storage == HandleStorage && port.container == 0 && owner >= 0 && record >= 0;
            if (valid) {
                canonical := Canonical(types, owner);
                valid = CatalogRecordValid(types, owner) && canonical >= 0 && canonical == Canonical(types, record);
            }
            if (!valid) {
                storage = UnsupportedPort;
            }
        }
        row: ResolvedPort = {name: port.name, storage: storage, container: port.container,
                             c_string: port.c_string, record: record, has_default: port.has_default,
                             default_owner: port.default_owner, default_supported: port.default_supported,
                             default_bits: port.default_bits, default_text: port.default_text};
        resolved.append(row);
    }
    return resolved;
}
// Legacy makers adapt ports the pure catalog cannot describe. Rich makers
// require all their ports, so an unsupported maker fails at its selected call.
CatalogMakes :: (makes: NativeMake[], natives: ResolvedNative[], ports: ResolvedPort[]) -> NativeMake[] {
    supported: NativeMake[] = [];
    for (make in makes) {
        if (make.native >= 0 && make.native < length(natives) && Supported(ports, natives[make.native])) {
            supported.append(make);
        }
    }
    return supported;
}
// Rich game entry points carry nominal ports and the real native effects;
// the pure package/bootstrap entry points keep their original record layouts.
pub CompileBehaviorsWithCatalog :: (identities: string[], sources: string[], target: Target, abi: u64,
                                    names: string[], natives: CatalogNative[], ports: CatalogPort[], native_ids: u64[],
                                    game_events: GameEvent[], event_fields: GameEventField[], types: GameType[],
                                    type_fields: GameField[], entity: u64, operators: NumericOperator[],
                                    globals: GameGlobal[], makes: NativeMake[], make_fields: int[],
                                    native_effects: int[]) -> u8[] {
