import syntax "project:syntax_diagnostics"
import strings "core:strings"

// Borrowed tables become ordinary owned invocation values at the ABI boundary.
// Indices and scope-parent chains retain the analyzer's structural invariants.
pub Scope :: struct {
    parent: int;
    function: int;
    start: int;
    end: int;
    line: int;
    column: int;
    document: int;
}
pub Symbol :: struct {
    name: string;
    kind: int;
    scope: int;
    id_slot: int;
    start: int;
    end: int;
    line: int;
    column: int;
    document: int;
}
pub Function :: struct {
    symbol: int;
    scope: int;
}
pub Environment :: union {
    Tables(scopes: Scope[], symbols: Symbol[], functions: Function[],
           ids: u64[], document_keys: string[])
}
pub Context :: struct {
    identity: string;
    scope: int;
    function: int;
    package_scope: int;
    has_identity: bool;
    has_documents: bool;
}
pub Request :: struct {
    name: string;
    kind: int;
    start: int;
    end: int;
    line: int;
    column: int;
    document: int;
}
pub Declaration :: union {
    Appended(id: u64, diagnostics: syntax.Diagnostic[])
    | Existing(symbol: int, diagnostics: syntax.Diagnostic[])
}

pub FunctionKind: int : 1;
MacroKind: int : 2;
StateKind: int : 4;
SharedStateKind: int : 5;
ParameterKind: int : 6;
ResultKind: int : 7;
LocalKind: int : 8;
ActionKind: int : 9;

pub FindName :: (environment: Environment, scope: int, name: string) -> int {
    switch environment {
        case .Tables(scopes, symbols, functions, ids, keys):
            current := scope;
            while (current >= 0) {
                index := length(symbols) - 1;
                while (index >= 0) {
                    symbol := symbols[index];
                    if (symbol.scope == current && symbol.kind != FunctionKind &&
                        symbol.kind != MacroKind && symbol.name == name) {
                        return index;
                    }
                    index -= 1;
                }
                current = scopes[current].parent;
            }
            return -1;
    }
}
pub FindStorage :: (environment: Environment, scope: int, name: string, kind: int) -> int {
    switch environment {
