        field := fields[index];
        bytes.extend(Text(field.name, true, items, slots));
        bytes.extend(Words([wide[field.nominal], Flag(field.has_default), Flag(field.default_owner)]));
        bytes.extend(slice(pool, starts[field.initial], sizes[field.initial]));
        index += 1;
    }
    return bytes;
}

// What Write writes: which values, and its metadata strings in the order it
// writes them, a run of sources of one asset naming it once.
Gathered :: union {
    Of(texts: string[], used: bool[])
}
Gather :: (module: Module) -> Gathered {
    switch module {
        case .Tables(id, owner_type, abi, pointer_size, wide, values, ints, requirements, fields, event_declarations,
                     event_fields, imports, functions, spans, roots, instructions, locals, parameters, frames,
                     sources, results, data, hosts, commands, calls, references, components, points, watches, states,
                     entries, queries, query_root, query_variable_count, query_filter, descriptions, system_description):
            // Each step is a value Write writes, or -1 - n for named[n].
            named: string[] = [];
            steps: int[] = [];
            for (requirement in requirements) {
                named.append(requirement.name);
                steps.append(-length(named));
                index := requirement.first;
                while (requirement.authored && index < requirement.first + requirement.count) {
                    field := fields[index];
                    named.append(field.name);
                    steps.append(-length(named));
                    if (field.has_type_name) {
                        named.append(field.type_name);
                        steps.append(-length(named));
                    }
                    if (field.has_unit) {
                        named.append(field.unit);
                        steps.append(-length(named));
                    }
                    index += 1;
                }
            }
            for (declared in event_declarations) {
                named.append(declared.name);
                steps.append(-length(named));
                index := declared.first;
                while (index < declared.first + declared.count) {
                    named.append(event_fields[index].name);
                    steps.append(-length(named));
                    steps.append(event_fields[index].initial);
                    index += 1;
                }
            }
            asset := "";
            known := false;
            for (function in functions) {
                table: int = 0;
                while (table < Tables) {
                    span := spans[function.spans + table];
                    item := span.first;
                    last := span.first + span.count;
                    if (table == ArgumentDefaults || table == ResultDefaults || table == VariableDefaults ||
                        table == CommandArguments || table == CommandResults) {
                        while (item < last) {
                            steps.append(item);
                            item += 1;
                        }
                    } else if (table == Roots) {
                        while (item < last) {
                            steps.append(roots[item].shape);
                            item += 1;
                        }
                    } else if (table == Instructions) {
                        while (item < last) {
                            steps.append(instructions[item].value);
                            if (instructions[item].has_message) {
                                named.append(instructions[item].message);
                                steps.append(-length(named));
                            }
                            item += 1;
                        }
                    } else if (table == Locals) {
                        while (item < last) {
                            steps.append(locals[item].initial);
                            item += 1;
                        }
                    } else if (table == Parameters) {
                        while (item < last) {
                            steps.append(parameters[item].initial);
                            item += 1;
                        }
                    } else if (table == Frames || table == Sources || table == Stacks) {
                        while (item < last) {
                            row := item;
                            if (table == Frames) {
                                row = frames[item].source;
                            }
                            source := sources[row];
                            if (source.has_asset && (!known || source.asset != asset)) {
                                asset = source.asset;
                                known = true;
                                named.append(asset);
                                steps.append(-length(named));
                            }
                            item += 1;
                        }
                    } else if (table == Results) {
                        while (item < last) {
                            named.append(results[item].name);
                            steps.append(-length(named));
                            item += 1;
                        }
                    } else if (table == DataValues) {
                        while (item < last) {
                            steps.append(data[item].initial);
                            item += 1;
                        }
                    } else if (table == SourceWatches) {
                        while (item < last) {
                            steps.append(watches[item].initial);
                            item += 1;
                        }
                    }
                    table += 1;
                }
            }
            for (retained in states) {
                steps.append(retained.initial);
            }
            for (item in entries) {
                if (item.has_entry) {
                    named.append(item.entry_name);
                    steps.append(-length(named));
                }
                if (item.has_event_name) {
                    named.append(item.event_name);
                    steps.append(-length(named));
                }
            }
            for (description in descriptions) {
                steps.append(description.row_type);
            }
            // A value writes its own strings, then those of its nested values
            // in order, so a stack walks each written value in that order.
            texts: string[] = [];
            used := resize([false], length(values));
            stack: int[] = [];
            for (step in steps) {
                if (step < 0) {
                    texts.append(named[-1 - step]);
                    continue;
                }
                if (length(stack) == 0) {
                    stack.append(step);
                }
                stack[0] = step;
                top: int = 1;
                while (top > 0) {
                    top -= 1;
                    v := values[stack[top]];
                    used[stack[top]] = true;
                    if (v.has_type_name) {
                        texts.append(v.type_name);
                    }
                    if (v.container == 0 && v.tag == NameTag && v.has_text) {
                        texts.append(v.text);
                    }
                    nested := v.first + v.count - 1;
                    aggregate := v.container != 0 || v.tag == StructTag || v.tag == UnionTag;
                    while (aggregate && v.present && nested >= v.first) {
                        if (top < length(stack)) {
                            stack[top] = nested;
                        } else {
                            stack.append(nested);
                        }
                        top += 1;
                        nested -= 1;
                    }
                }
            }
            return Gathered.Of(texts, used);
    }
}

// The complete inner module.
pub Write :: (module: Module) -> u8[] {
    switch Gather(module) {
        case .Of(texts, used):
            return WriteTables(module, Table(texts), used);
    }
}
WriteTables :: (module: Module, items: string[], used: bool[]) -> u8[] {
    slots := TableSlots(items);
    switch module {
        case .Tables(id, owner_type, abi, pointer_size, wide, values, ints, requirements, fields, event_declarations,
                     event_fields, imports, functions, spans, roots, instructions, locals, parameters, frames,
                     sources, results, data, hosts, commands, calls, references, components, points, watches, states,
                     entries, queries, query_root, query_variable_count, query_filter, descriptions, system_description):
            // Nested values follow their parent, so encoding from the last
            // value back finds every nested value already in the pool.
            pool: u8[] = [];
            starts := resize([int(0)], length(values));
            sizes := resize([int(0)], length(values));
            at := length(values) - 1;
            while (at >= 0) {
                if (used[at]) {
                    start := length(pool);
                    pool.extend(ValueBytes(values[at], wide, pool, starts, sizes, items, slots));
                    starts[at] = start;
                    sizes[at] = length(pool) - start;
                }
                at -= 1;
            }

            bytes := Words([Magic, u64(Version), u64(pointer_size), abi, id, owner_type,
                            Zig(length(requirements))]);
            for (requirement in requirements) {
                bytes.extend(Words([wide[requirement.id], wide[requirement.layout],
                                    Zig(requirement.storage)]));
                bytes.extend(Text(requirement.name, true, items, slots));
                bytes.extend(Words([u64(requirement.size), Flag(requirement.authored)]));
                if (requirement.authored) {
                    bytes.extend(Ints([requirement.count]));
                    index: int = 0;
                    while (index < requirement.count) {
                        field := fields[requirement.first + index];
                        bytes.extend(Text(field.name, true, items, slots));
                        bytes.extend(Ints([field.kind]));
                        bytes.extend(Text(field.type_name, field.has_type_name, items, slots));
                        bytes.extend(Text(field.unit, field.has_unit, items, slots));
                        bytes.extend(Words([Flag(field.kind == TextTag)]));
                        index += 1;
                    }
                }
            }
            bytes.extend(Ints([length(event_declarations)]));
            for (declared in event_declarations) {
                bytes.extend(EventBytes(declared, event_fields, wide, pool, starts, sizes, items, slots));
            }
            bytes.extend(Ints([length(imports)]));
            for (imported in imports) {
                bytes.extend(Words([wide[imported.id], wide[imported.fingerprint]]));
            }

            // Consecutive sources of one asset share its encoded text.
            asset := "";
            asset_bytes: u8[] = [];
            bytes.extend(Ints([length(functions)]));
            for (function in functions) {
                bytes.extend(FunctionHead(function));
                table: int = 0;
                while (table < Tables) {
                    span := spans[function.spans + table];
                    bytes.extend(Ints([span.count]));
                    item := span.first;
                    last := span.first + span.count;
                    if (table == ArgumentDefaults || table == ResultDefaults || table == VariableDefaults ||
                        table == CommandArguments || table == CommandResults) {
                        while (item < last) {
                            bytes.extend(slice(pool, starts[item], sizes[item]));
                            item += 1;
                        }
                    } else if (table == ArgumentKinds || table == ResultKinds || table == Slots ||
                               table == SlotKinds || table == CommandArgumentKinds || table == CommandResultKinds) {
                        bytes.extend(Ints(slice(ints, span.first, span.count)));
                    } else if (table == Roots) {
                        while (item < last) {
                            bytes.extend(Ints([roots[item].bank, roots[item].index]));
                            bytes.extend(slice(pool, starts[roots[item].shape], sizes[roots[item].shape]));
                            item += 1;
                        }
                    } else if (table == Instructions) {
                        while (item < last) {
                            bytes.extend(InstructionBytes(instructions[item], wide, pool, starts, sizes, items, slots));
                            item += 1;
                        }
                    } else if (table == Locals) {
                        while (item < last) {
                            bytes.extend(LocalBytes(locals[item], wide, pool, starts, sizes));
                            item += 1;
                        }
                    } else if (table == Parameters) {
                        while (item < last) {
                            initial := parameters[item].initial;
                            bytes.extend(slice(pool, starts[initial], sizes[initial]));
                            bytes.extend(Ints([parameters[item].frame, parameters[item].pin]));
                            item += 1;
                        }
                    } else if (table == Frames) {
                        while (item < last) {
                            frame := frames[item];
                            source := sources[frame.source];
                            bytes.extend(SourceBytes(source, wide, Text(source.asset, source.has_asset, items, slots)));
                            bytes.extend(Ints([frame.depth, frame.resume, frame.source_index, frame.stack]));
                            item += 1;
                        }
                    } else if (table == Sources || table == Stacks) {
                        while (item < last) {
                            if (sources[item].has_asset && (length(asset_bytes) == 0 || sources[item].asset != asset)) {
                                asset = sources[item].asset;
                                asset_bytes = Text(asset, true, items, slots);
                            }
                            bytes.extend(SourceBytes(sources[item], wide, asset_bytes));
                            item += 1;
                        }
                    } else if (table == Results) {
                        while (item < last) {
                            bytes.extend(Ints([results[item].index]));
                            bytes.extend(Text(results[item].name, true, items, slots));
                            item += 1;
                        }
                    } else if (table == DataValues) {
                        while (item < last) {
                            bytes.extend(Ints([data[item].kind]));
                            bytes.extend(slice(pool, starts[data[item].initial], sizes[data[item].initial]));
                            bytes.extend(Words([u64(data[item].size)]));
                            item += 1;
                        }
                    } else if (table == Hosts) {
                        while (item < last) {
                            bytes.extend(HostBytes(hosts[item], wide));
                            item += 1;
                        }
                        // No query rows. Commands and their banks follow separately.
                        bytes.extend(Zeros(1));
                    } else if (table == Commands) {
                        while (item < last) {
                            command := commands[item];
                            bytes.extend(Words([wide[command.capability], wide[command.abi], 0, 0]));
                            bytes.extend(Text("", false, items, slots));
                            bytes.extend(Words([Zig(command.first), Zig(command.count), wide[command.node], 0,
                                                Zig(command.result_first), Zig(command.result_count), 0]));
                            item += 1;
                        }
                    } else if (table == Calls) {
                        while (item < last) {
                            bytes.extend(CallBytes(calls[item], references[calls[item].function], wide));
                            item += 1;
                        }
                    } else if (table == Definitions) {
                        while (item < last) {
                            bytes.extend(ReferenceBytes(references[ints[item]], wide));
                            item += 1;
                        }
                    } else if (table == Components) {
                        while (item < last) {
                            bytes.extend(Words([wide[components[item].id], Flag(components[item].binding)]));
                            item += 1;
                        }
                    } else if (table == ComponentWrites) {
                        while (item < last) {
                            bytes.extend(Words([wide[ints[item]]]));
                            item += 1;
                        }
                        // No state selections follow component writes.
                        bytes.extend(Zeros(1));
                    } else if (table == SourcePoints) {
                        while (item < last) {
                            bytes.extend(PointBytes(points[item], wide));
                            item += 1;
                        }
                    } else {
                        while (item < last) {
                            watch := watches[item];
                            bytes.extend(PointBytes(points[watch.origin], wide));
                            bytes.extend(slice(pool, starts[watch.initial], sizes[watch.initial]));
                            bytes.extend(Words([Zig(watch.ordinal), Flag(watch.output),
                                                Flag(watch.reference)]));
                            item += 1;
                        }
                    }
                    table += 1;
                }
                // Points, watches and edges are debugger tables this module has none of.
                bytes.extend(Zeros(3));
            }

            bytes.extend(Ints([length(states)]));
            for (retained in states) {
                bytes.extend(Words([wide[retained.id]]));
                bytes.extend(slice(pool, starts[retained.initial], sizes[retained.initial]));
                bytes.extend(Words([Flag(retained.shared), Flag(retained.contains_tasks)]));
            }
            bytes.extend(Ints([length(entries)]));
            for (item in entries) {
                bytes.extend(EntryHead(item, wide, items, slots));
                bytes.extend(ReferenceBytes(references[item.body], wide));
                bytes.extend(ReferenceBytes(references[item.subscription], wide));
            }
            bytes.extend(Ints([length(queries)]));
            for (term in queries) {
                bytes.extend(Words([Zig(term.kind), Flag(term.required), wide[term.component_id], wide[term.source_relationship],
                                    Zig(term.source_traversal), Zig(term.source_variable), Zig(term.target_variable)]));
                if (term.predicate < 0) {
                    bytes.extend(Ints([-1, -1, 0, 0]));
                } else {
                    bytes.extend(ReferenceBytes(references[term.predicate], wide));
                }
                bytes.extend(Ints([term.count]));
                bytes.extend(Ints(slice(ints, term.first, term.count)));
            }
            bytes.extend(Ints([query_root, query_variable_count, query_filter, length(descriptions)]));
            for (description in descriptions) {
                bytes.extend(Ints([description.query_root, description.query_variable_count]));
                initial := description.row_type;
                bytes.extend(slice(pool, starts[initial], sizes[initial]));
                bytes.extend(ReferenceBytes(references[description.evaluate], wide));
            }
            // The selected system description is one-based; zero means none.
            // Reactive bindings and actions are absent from authored compiler modules.
            bytes.extend(Ints([system_description, 0, 0]));
            strings_at := length(bytes);
            bytes.extend(TableBytes(items));
            return extend(bytes, Word(u64(strings_at)));
    }
}

// FNV-1a over the module bytes, as import fingerprints use; zero becomes one.
pub Fingerprint :: (bytes: u8[]) -> u64 {
    hash: u64 = 14695981039346656037;
    for (item in bytes) {
        hash = (hash ^ u64(item)) * 1099511628211;
    }
    if (hash == 0) {
        return 1;
    }
    return hash;
}

Word :: (value: u64) -> u8[] {
    bytes: u8[] = [];
    index: int = 0;
    rest := value;
    while (index < 8) {
        bytes.append(u8(wrap: rest));
        rest = rest >> 8;
        index += 1;
    }
    return bytes;
}
// CHIBICLO v1: header words "CHIBICLO", version, root id and row count, then
// rows sorted bytewise by name: id, name length, module length, name, module.
// Module bytes are data[starts[i], starts[i] + lengths[i]).
pub Closure :: (root: u64, ids: u64[], names: string[], data: u8[],
                starts: int[], lengths: int[]) -> u8[] {
    order: int[] = [];
    index: int = 0;
    while (index < length(names)) {
        at := length(order);
        order.append(index);
        while (at > 0 && strings.Compare(names[order[at - 1]], names[index]) > 0) {
            order[at] = order[at - 1];
            at -= 1;
        }
        order[at] = index;
        index += 1;
    }
    magic: u8[] = [67, 72, 73, 66, 73, 67, 76, 79];
    bytes := magic;
    bytes.extend(Word(1));
    bytes.extend(Word(root));
    bytes.extend(Word(u64(length(names))));
    for (row in order) {
        name := names[row];
        size := strings.ByteLength(name);
        bytes.extend(Word(ids[row]));
        bytes.extend(Word(u64(size)));
        bytes.extend(Word(u64(lengths[row])));
        bytes.extend(Raw(name));
        bytes.extend(slice(data, starts[row], lengths[row]));
    }
    return bytes;
}
package scalar_facts

// Internal opt-in owned result for one source document holding a set of
// ordinary pure functions over numbers, bool, strings, and records and
// unions of numbers and bool, which may recurse. A function's body is
// locals, assignments, asserts, if statements, switches over integers or a
// union's variants, while loops, loops over int ranges, breaks, continues and
// returns. Values and conditions are literals, variables, arithmetic,
// shifts, conversions, comparisons, logic, record literals, field reads,
// union variants, their tests and payloads, a string's byte count, bytes and
// slices, and direct calls of functions of the set, whose operands are such
// expressions.
// This is not a general IR, and no compiler-private identity crosses this
// boundary.
//
// The compiler host passes arrays of flat records, so a module is one array
// of rows. Row 0 is its Source: `name` is the path and `text` the document.
// A rejected module has exactly one more row, its Rejection: `text` is the
// diagnostic's message and the range is its source. Nothing else survives
// a rejection, and it must never be emitted.
//
// An accepted module's row 1 is its Document: `name` is the shared source
// snapshot's document key, and `text` is empty for a package and the library's
// name for a native library source. Then each record and union the source declares
// follows in declaration order:
// - a record is a Record row, its `name`, `count` fields and declaration
//   range, then `count` Member rows: `name`, scalar `type`, ordinal `value`
//   and name range;
// - a union is a Union row, its `name`, `count` variants and declaration
//   range, then each variant in order: a Variant row, its `name`, ordinal
//   `value`, `count` payload fields and range, then `count` Member rows:
//   `name`, scalar `type`, name range and `value`, the payload's ordinal
//   among all the union's payloads in declaration order.
// Then, for each function with several named results in declaration order,
// a record of them: a Record row named for the function with `.results`, its
// declaration's range, then a Member row for each result as for a field.
// The d-th of them is type RecordType + d, which a function's result, a
// parameter, a variable and an operand may have. Then each function follows
// in declaration order; a package's first is the module's entry and takes no
// parameters and returns int, and a library has no entry:
// - a Function row: its `name`, result `type`, `count` parameters and
//   declaration range, and in a library its stable symbol ID as `literal`,
//   the ID the runtime binds it by;
// - `count` Parameter rows: `name`, `type`, ordinal `value`, name range;
// - a Local row for each named result, with its name's range, whose operand
//   is its zero: a Literal, or a Zero for a record. A function with one
//   named result returns its value, and one with several the record of
//   them. A return of one named result's value returns it. A return of
//   several values is an Assign row for each, with the value's range, in
//   order, then a Return of the record of them all with the range of the
//   values' closing parenthesis. A bare return returns the results' values,
//   and a body that does not end in a terminating statement does so at its
//   closing brace;
// - its body's statement rows in source order, each with its statement's
//   range. The body ends in a terminating statement: a return, an if
//   statement with an else whose two branches end in terminating statements,
//   a switch with a default arm whose arms all end in terminating
//   statements, or a while loop whose condition is the literal true and whose
//   own body has no break. Statements after a terminating one are still recorded,
//   though they never run.
// The statements:
// - a Local row declares variable `value` of `type`, its `name`, and its
//   `count` operand rows follow, its initial value. The variables are the
//   parameters, then the locals in declaration order;
// - an Assign row stores its `count` operands' value in variable `value` of
//   `type`. A compound assignment's operands read the variable first, then
//   the value, then combine them, since no operand can change a variable;
// - an If row is followed by its `count` condition operands, then the
//   statements of its consequence, then optionally an Else row, the range of
//   its alternative, and the alternative's statements, then an End row with
//   the If row's range. An else-if is an Else row whose one statement is an
//   If;
// - a While row is followed by its `count` condition operands, then the
//   statements of its body, then an End row with the While row's range. The
//   condition runs before each pass;
// - a For row declares variable `value`, an int named `name`, and its
//   `count` operands follow: its first bound's, then its last bound's, each
//   an int, run once before the loop. Its `literal` is the sum of
//   RangeExclusive for `..<` and RangeReverse for `for <`. The statements of
//   its body follow, then an End row with the For row's range. The variable
//   takes each value from the first bound up to the last, the last itself
//   only for `..`, or the same values from the last down, and the body cannot
//   assign it. A bound evaluated once cannot change, so neither end wraps;
// - a Switch row is followed by its `count` operands, its value, of its
//   integer `type`, run once. Then each arm in source order: a Case row with
//   the arm's range and the Switch row's `type`, its `count` operands, the
//   arm's value of that type, or none for the default arm, then the arm's
//   statements. An End row with the Switch row's range follows the last arm.
//   The value arms are tried in order, each value evaluated only when the
//   arms before it missed, and the first arm whose value equals the switch's
//   runs; the default arm, wherever it is, runs when none does. An arm does
//   not fall through into the next. A switch on a union variable is one on
//   its Tag: its operands read the variable, then take its Tag, and each
//   variant arm's value is a Literal of the variant's ordinal, with the range
//   of the pattern's name. Its last arm is its default arm when it has none,
//   since the variable holds one of the variants the arms cover. Each of an
//   arm's bindings, in order, is a Local row with the binding's range whose
//   operands read the variable and take that Payload, with the same range,
//   before the arm's statements;
// - a Break or Continue row leaves, or ends the pass of, the innermost loop
//   it is in, through any switch around it. It has no operands;
// - a Return row is followed by its `count` operands, the returned value;
// - an Assert row, with the range of its assert's call, is followed by its
//   `count` condition operands. When the condition is false, the call from
//   the VM ends with the failure the VM's assert at that range gives, and
//   every call it is in ends with it.
// A variable is visible from the end of its declaration to the end of the
// statements it is declared among; locals of a consequence, an alternative,
// an arm or a loop body are not visible after it, and a For row's variable is
// visible only in its body.
//
// Operand rows are in evaluation order, each after the operands it consumes:
// a Literal's `literal` is its value, or 0 and 1 for false and true, and a
// word's is its bits, as a float's and a double's are their IEEE encodings; a
// string Literal's `text` is its decoded bytes and its `literal` 0;
// a Read's `value` is its variable's ordinal; a Compare's `value` is its
// operator and it consumes the two most recent unconsumed operands, numbers
// of one type, or two bools or two strings for == and !=, left first, to
// give a bool, two strings being equal when their bytes are; an
// Arithmetic's `value` is its operator and it consumes the two most recent
// unconsumed operands, both of its number `type`, left first, to give one of
// that type; a Unary's `value` is its operator and it consumes the most
// recent unconsumed operand of its `type`; a Convert's `value` is Clamp or
// Wrap and it consumes the most recent unconsumed operand, a number its
// `type` converts from, to give one of its `type`; a Logical's `value` is
// LogicalAnd or LogicalOr and it consumes the most recent unconsumed operand,
// its left bool, then its `count` right operand rows follow it, which run
// only when the left does not decide the value, and give a bool, its value;
// a Call's `value` is its callee's function ordinal, `name` its callee's name
// and `count` its arguments, the `count` most recent unconsumed operands in
// argument order; an argument the call omits is a Literal of its parameter's
// default with the call's range. A Zero row is the record of its `type` whose
// fields are all zero; an Update's `value` is a field ordinal of its record
// `type`, and it consumes the two most recent unconsumed operands, a record of
// that type then a value of the field's type, to give the record with that
// field replaced; a Field's `value` is a field ordinal and it consumes the
// most recent unconsumed operand, a record, to give that field, of its
// `type`. A Make's `value` is a variant ordinal of its union `type` and
// `count` that variant's payloads, and it consumes the `count` most recent
// unconsumed operands, the payloads in order, to give the union holding that
// variant; a Tag consumes the most recent unconsumed operand, a union, to give
// its variant's ordinal, an int; a Payload's `value` is a payload ordinal of a
// union and it consumes the most recent unconsumed operand, that union, to
// give the payload, of its `type`. Payloads are read only where their variant
// is held; the backend cannot check this, and another variant's payload reads
// its zero. `v is .V` is the Tag of `v`, a Literal of V's ordinal with the
// pattern's range, then an Equal Compare, or NotEqual for `is not`. A Text
// row reads a string's bytes as the runtime's text natives do, and its
// `value` is its operator: TextLength consumes the most recent unconsumed
// operand, a string, to give its byte count; TextByte consumes the two most
// recent, a string then an index, to give the byte there, 0 to 255, or -1
// outside the string; TextSlice consumes the three most recent, a string,
// then a start and a count, to give the string of those bytes, its start
// clamped to the string and its count to the bytes after the start; and
// TextFormat consumes the `count` most recent, at least one, a string format
// then each argument, a number, bool or string of its own type, to give the
// string format_text makes of them, which the runtime allocates. The
// indexes, starts, counts and byte counts are ints. A record
// literal is a Zero row with the literal's range, then each
// field's value in source order and its Update, with the field's range. An
// assignment to a field, `v.f = x`, is an Assign of `v` whose operands read
// `v`, then `x`, then update `f` with the target's range, and a compound one
// reads `v` and its field `f` before `x` and their combination. A condition's last operand is its bool; a
// return's last operand is the function's returned value, and a Local's or an
// Assign's is its variable's. A shift's count is converted to the shifted
// type before the shift consumes it, and an integer operand of floating
// arithmetic, a comparison or a float to double widening has its own Convert
// rows, as the ordinary compiler converts them.
//
// Ranges are half-open source-byte offsets into the source text; lines and
// columns are one-based source-byte positions. Fields a row does not use are
// zero or empty. The rows own their strings: a host snapshot of the array is
// the retained result, not a view into the producer's invocation.
pub Row :: struct {
    kind: int;
    type: int;
    value: int;
    count: int;
    literal: i64;
    name: string;
    text: string;
    start: int;
    end: int;
    line: int;
    column: int;
}

pub SourceRow: int : 0;
pub RejectionRow: int : 1;
pub DocumentRow: int : 2;
pub FunctionRow: int : 3;
pub ParameterRow: int : 4;
pub ReturnRow: int : 5;
pub LiteralRow: int : 6;
pub ReadRow: int : 7;
pub CallRow: int : 8;
pub IfRow: int : 9;
pub CompareRow: int : 10;
pub ArithmeticRow: int : 11;
pub UnaryRow: int : 12;
pub ConvertRow: int : 13;
pub LocalRow: int : 14;
pub AssignRow: int : 15;
pub ElseRow: int : 16;
pub EndRow: int : 17;
pub LogicalRow: int : 18;
pub WhileRow: int : 19;
pub ForRow: int : 20;
pub BreakRow: int : 21;
pub ContinueRow: int : 22;
